var ZAIKA_EXTRA_BN={"biryani":{"intro":"বিরিয়ানি সেই পদ যা বেশিরভাগ বাড়িতে অতিথি ও উৎসবের জন্য তুলে রাখা হয়, আর করাচি ধাঁচটি তার জোরালো মসলা, আলাদা আলাদা ভাতের দানা এবং ঢাকনা ওঠার আগেই বাড়ি ভরে যাওয়া দমের গন্ধের জন্য পরিচিত। নিচের পদ্ধতিতে মুরগি রসালো ও ভাত সুগন্ধি থাকে, স্তরগুলো একটিমাত্র নরম পিণ্ডে পরিণত হয় না। মেরিনেট করাই আসল স্বাদের কাজটি করে, তাই রান্নাটা মূলত স্তরে স্তরে সাজানো আর অপেক্ষা করা। হাঁড়ি থেকে সরাসরি, রায়তা ও সালাদ দিয়ে পরিবেশন করুন, আর বাষ্প উঠতে উঠতে সবাইকে দ্বিতীয়বার নিতে দিন।","ing":["মুরগি 750 গ্রাম","দই 1 কাপ","বাসমতি চাল 3 কাপ (ভেজানো)","বিরিয়ানি মসলা 3 টেবিল চামচ","আদা রসুন বাটা 2 টেবিল চামচ","পেঁয়াজ 3টি (ভাজা)","টমেটো 2টি","কাঁচা লঙ্কা 4টি","টাটকা ধনেপাতা","পুদিনা","লেবু","জাফরান / খাবারের রং","ঘি 3 টেবিল চামচ","ভাতের জলের জন্য লবণ","তেজপাতা","এলাচ","লবঙ্গ"],"steps":["ভাত ধুয়ে নিন যতক্ষণ না জল পরিষ্কার আসে, 30 মিনিট ভিজিয়ে রাখুন, তারপর ছেঁকে নিন। দই, বিরিয়ানি মসলা, আদা রসুন বাটা ও লবণ মুরগিতে মিশিয়ে 30 মিনিট মেরিনেট করুন।","লবণ ও গোটা মসলা দিয়ে বড় হাঁড়িতে জল ফোটান। ভাত দিন এবং 70 শতাংশ সেদ্ধ হওয়া পর্যন্ত, মাঝখানটা এখনও শক্ত থাকা অবস্থায় রান্না করুন, তারপর সঙ্গে সঙ্গে ছেঁকে নিন।","ঘি গরম করুন, পেঁয়াজ গভীর সোনালি হওয়া পর্যন্ত ভাজুন, আর স্তরে দেওয়ার জন্য অর্ধেক তুলে রাখুন। বাকিটা কড়াইয়ে রাখুন।","টমেটো ও মেরিনেট করা মুরগি দিন, আর মাঝারি বেশি আঁচে 10 থেকে 12 মিনিট ভাজুন, যতক্ষণ না মসলা ঘন হয় ও তেল আলাদা হয়।","মুরগির মসলা ভারী হাঁড়িতে ছড়িয়ে দিন। অর্ধেক ভাত দিন, তারপর ধনেপাতা, পুদিনা, ভাজা পেঁয়াজ, লেবু ও জাফরান ছড়িয়ে দিন।","বাকি ভাত দিন, উপরে বাকি পেঁয়াজ, ভেষজ ও জাফরান আর এক চামচ ঘি দিন। ঢাকনাটা কাপড় বা ফয়েল দিয়ে বন্ধ করুন।","ঢাকনা না খুলে কম আঁচে 20 মিনিট দমে রান্না করুন, তারপর আঁচ থেকে সরিয়ে 10 মিনিট রেখে দিন।","ঢাকনা খুলুন, কাঁটাচামচ দিয়ে পাশ থেকে আলতো করে ঝুরঝুরে করুন, রংগুলো দেখা যায় এমনভাবে হালকা করে মেশান, আর গরম পরিবেশন করুন।"],"tip":"ভাত বেশি সেদ্ধ করবেন না। দমেই রান্না শেষ হবে। দমের সময় বাষ্প যাতে না বেরোয়, ঢাকনার উপর একটা কাপড় দিন, আর ভাতের জলের স্বাদ নিন। সেটা হালকা নোনতা হওয়া উচিত, কারণ সাদা ভাতের এই মসলাই দরকার।","notes":["হাড়সহ মুরগি দমের সময় বেশি রসালো থাকে। লেগের টুকরো ব্যবহার করুন আর বাড়তি চর্বি ছেঁটে ফেলুন।","পুরোনো বাসমতি আলাদা দানা দেয়। নতুন চাল সহজে নরম হয়ে যায়, তাই ফোটানোর সময়ের দিকে খেয়াল রাখুন।","পুরো চর্বিযুক্ত দই মেরিনেড মুরগিতে লেগে থাকতে সাহায্য করে। কম চর্বির দই গরমে পড়লে ফেটে যেতে পারে।","বিরিয়ানি মসলা ব্র্যান্ডভেদে আলাদা হয়। বাড়তি লঙ্কা দেওয়ার আগে মসলার স্বাদ নিন, আর এখন নয়, পরের বার ঠিক করুন।"],"variations":["সবজি বিরিয়ানি: মুরগির বদলে আলু, ফুলকপি, মটর ও গাজর নিন, সবজি অল্প মেরিনেট করুন, আর দম 15 মিনিটে কমিয়ে দিন।","খাসির বিরিয়ানি: 750 গ্রাম খাসি নিন, স্তর সাজানোর আগে মসলা রান্না করুন যতক্ষণ না মাংস প্রায় নরম হয়, আর দমে 30 মিনিট রাখুন।","কম ঝাল: কাঁচা লঙ্কা অর্ধেক করুন, বাড়তি শুকনো লঙ্কা দেবেন না, আর বাড়তি রায়তা দিয়ে পরিবেশন করুন।"],"serving":"রায়তা, কাচুম্বর সালাদ ও লেবুর ফালি দিয়ে 4 জনের জন্য উদারভাবে যথেষ্ট। হাঁড়িটা টেবিলের মাঝখানে রাখুন আর ঢাকনাটা সেখানেই খুলুন, যাতে সবাই দমের গন্ধ পায়। ভাতই প্রধান পদ বলে নান ঐচ্ছিক। এক গ্লাস লস্যি বা পুদিনার পানীয় ঝালের সঙ্গে ভালো ভারসাম্য আনে।","storage":"1 ঘণ্টার মধ্যে ঠান্ডা করুন আর বায়ুরোধী পাত্রে ফ্রিজে 2 দিন পর্যন্ত রাখুন। ঢাকা প্যানে কম আঁচে 2 টেবিল চামচ জল দিয়ে, বা মাইক্রোওয়েভে ঢেকে, পুরোপুরি বাষ্প ওঠা পর্যন্ত গরম করুন। একবারের বেশি গরম করবেন না। ভাগে ভাগে 1 মাস পর্যন্ত ফ্রিজ করুন, আর গরম করার আগে ফ্রিজে সারারাত গলিয়ে নিন।","mistakes":["দমের আগে ভাত পুরোপুরি ফোটানো। হাঁড়িতে সেটা নরম হয়ে যায়।","দমের সময় ঢাকনা খোলা। বাষ্প বেরিয়ে যায় আর ভাত কম সেদ্ধ থাকে।","ভাতের জলে খুব কম লবণ দেওয়া। স্তরগুলো স্বাদহীন লাগে।","দমের পর জোরে নাড়া। দানাগুলো ভেঙে যায় আর রংগুলো এক রঙে মিশে যায়।"],"faq":[["জাফরান ছাড়া কি বিরিয়ানি বানানো যায়?","হ্যাঁ। গরম দুধে গোলা এক চিমটি হলুদ খাবারের রং ব্যবহার করুন, বা বাদ দিন। স্বাদ আসে মসলা ও দম থেকে, শুধু রং থেকে নয়।"],["মুরগি কতক্ষণ মেরিনেট করতে হবে?","30 মিনিট ন্যূনতম। ফ্রিজে দুই থেকে চার ঘণ্টা আরও ভালো। ফ্রিজে রাখুন, আর মেরিনেট করা মুরগি ঘরের তাপমাত্রায় ফেলে রাখবেন না।"],["আমার ভাত আঠালো হলো কেন?","ভাত বেশি ফোটানো হয়েছিল, বা সঙ্গে সঙ্গে ছাঁকা হয়নি, বা হাঁড়ি জোরে নাড়া হয়েছিল। 70 শতাংশ সেদ্ধ অবস্থায় ছেঁকে নিন আর ঝুরঝুরে করার আগে হাঁড়ি রেখে দিন।"],["হাড় ছাড়া মুরগি ব্যবহার করা যাবে?","হ্যাঁ। থাইয়ের টুকরো ব্যবহার করুন আর মসলা রান্না 3 থেকে 4 মিনিট কমিয়ে দিন, যাতে মুরগি শুকিয়ে না যায়।"]]},"nihari":{"intro":"নিহারি সবচেয়ে সত্যি অর্থে ধীরগতির খাবার, এক সপ্তাহান্তের ঝোল যা ধৈর্যকে পুরস্কৃত করে এমন মাংস দিয়ে যা এত নরম যে হাড় ছেড়ে যায়, আর এমন ঝোল দিয়ে যা চামচে লেগে থাকে। এই সংস্করণে গরুর নলা প্রায় দুই ঘণ্টা ধরে আলতো করে রান্না হয়, যতক্ষণ না সংযোগকারী টিস্যু নরম হয় আর মসলা রং ও স্বাদে গভীর হয়। শেষে দেওয়া ময়দার গোলা নিহারিকে তার বিখ্যাত ঘন, চকচকে শেষটা দেয়, তাই সেটা ধীরে ঢালতে হবে আর ভালো করে নাড়তে হবে। টগবগে গরম, টাটকা নান ও ক্লাসিক সাজানোর জিনিস দিয়ে পরিবেশন করুন, আর টেবিলে বাড়তি লেবু রাখুন।","ing":["গরুর মাংস (নলা) 1 কেজি","নিহারি মসলা 4 টেবিল চামচ","ময়দা 3 টেবিল চামচ","আদা রসুন বাটা 2 টেবিল চামচ","পেঁয়াজ 1টি","ঘি / তেল 1/2 কাপ","সাজানোর জন্য আদা","কাঁচা লঙ্কা","লেবু","টাটকা ধনেপাতা"],"steps":["ঘি গরম করুন, কাটা পেঁয়াজ পুড়িয়ে না ফেলে হালকা বাদামি করুন, আদা রসুন বাটা দিন, আর কাঁচা গন্ধ যাওয়া পর্যন্ত 1 মিনিট ভাজুন।","মাংস ও নিহারি মসলা দিন আর মাঝারি বেশি আঁচে 8 থেকে 10 মিনিট ভাজুন, যতক্ষণ না মাংসের রং বদলায় আর মসলা প্রতিটি টুকরো ঢেকে ফেলে।","মাংস প্রায় 2 ইঞ্চি ঢেকে যায় এমন পরিমাণ গরম জল দিন, ফুটতে দিন, আর উপরের ফেনা তুলে ফেলুন।","হাঁড়ি ঢেকে কম আঁচে 2 ঘণ্টা রান্না করুন। মাঝে মাঝে নাড়ুন, আর জলের স্তর মাংসের নিচে নেমে গেলে গরম জল দিন।","মাংস দেখে নিন। কাঁটাচামচে ছিঁড়ে যাওয়া উচিত আর হাড় থেকে সহজে ছেড়ে যাওয়া উচিত। এখনও শক্ত থাকলে 20 থেকে 30 মিনিট আরও রান্না করুন।","ময়দা 1 কাপ ঠান্ডা জলের সঙ্গে মেশান যতক্ষণ না পুরোপুরি মসৃণ হয়, কোনো ডেলা থাকে না। হাঁড়ি নাড়তে নাড়তে পাতলা ধারায় ঢালুন।","ঝোল ঘন, চকচকে হয়ে চামচের পেছন ঢেকে ফেলা পর্যন্ত ঘন ঘন নেড়ে 10 থেকে 15 মিনিট অল্প আঁচে ফোটান।","10 মিনিট রেখে দিন, লবণের স্বাদ দেখুন, আর নান দিয়ে পরিবেশন করুন, আদা, কাঁচা লঙ্কা, লেবু ও ধনেপাতা দিয়ে সাজিয়ে।"],"tip":"ঝোল পাতলা রাখবেন না। নিহারি তার ঘন, চকচকে ঝোলের জন্য পরিচিত। ময়দা ধীরে দিন যাতে ডেলা না হয়, আর ঢালার সময় অনবরত নাড়ুন।","notes":["হাড় ও সংযোগকারী টিস্যুসহ নলা নিহারির জন্য আদর্শ। এটা ঝোলকে শরীর দেয়। হাড় ছাড়া ঝোলের মাংসও চলে, তবে ঝোল কম সমৃদ্ধ হয়।","নিহারি মসলা ব্র্যান্ডভেদে শক্তিতে আলাদা হয়। প্রথমবার উল্লেখ করা পরিমাণ ব্যবহার করুন, আর পরের বার ঠিক করুন।","ঘি ঐতিহ্যবাহী স্বাদ দেয়। তেলও চলে, আর অর্ধেক ঘি ও অর্ধেক তেল ভালো মাঝামাঝি পথ।","ময়দা শুধু ঘনত্বের জন্য। বাড়তি দেবেন না, কারণ এটা মসলার স্বাদ ম্লান করে।"],"variations":["খাসির নিহারি: একই পদ্ধতি ব্যবহার করুন আর প্রায় 1 ঘণ্টা 30 মিনিট রান্না করুন, আগে দেখে নিন, কারণ খাসি তাড়াতাড়ি নরম হয়।","মুরগির নিহারি: হাড়সহ মুরগি নিন, 35 থেকে 40 মিনিট রান্না করুন, ময়দার গোলা আগে দিন, আর হালকা ঝোল আশা করুন।","বেশি ঝাল: বাড়তি কাঁচা লঙ্কা রান্নার সময় নয়, পরিবেশনের সময় দিন, যাতে ঝাল টাটকা থাকে।"],"serving":"নান ও টেবিলে সাজানোর ছোট বাটি দিয়ে 5 জনের জন্য যথেষ্ট, যাতে প্রত্যেকে স্বাদমতো আদা, লঙ্কা, লেবু ও ধনেপাতা দিতে পারে। নিহারি ঐতিহ্যগতভাবে সকালের খাবার বা সপ্তাহান্তের দুপুরের খাবারের পদ, গভীর বাটিতে মাংসের উপর প্রচুর ঝোল ঢেলে পরিবেশন করা হয়। নান গরম রাখুন আর হাঁড়িটা টগবগ করতে করতে টেবিলে আনুন।","storage":"ঠান্ডা করুন আর বায়ুরোধী পাত্রে ফ্রিজে 3 দিন পর্যন্ত রাখুন। ঝোল ঠান্ডা হলে ঘন হয়। একটু গরম জল দিয়ে কম আঁচে আলতো করে গরম করুন, পুরোপুরি বাষ্প ওঠা পর্যন্ত নাড়ুন। 2 মাস পর্যন্ত ফ্রিজ করুন, ফ্রিজে সারারাত গলিয়ে নিন, আর সাজানোর জিনিস শুধু পরিবেশনের সময় টাটকা দিন।","mistakes":["বেশি আঁচে রান্না করা। মাংস শক্ত হয় আর ঝোল খুব দ্রুত কমে যায়।","ময়দা শুকনো বা একবারে দেওয়া। ডেলা হয় আর সহজে নেড়ে সরানো যায় না।","রান্নার সময় কম দেওয়া। মাংস হাড় ছেড়ে পড়ার বদলে চিবোনো থাকে।","ঠান্ডা নান দিয়ে আর সাজানো ছাড়া পরিবেশন করা। সেগুলো ছাড়া স্বাদ ফিকে লাগে।"],"faq":[["আমার নিহারির ঝোল পাতলা কেন?","ময়দা খুব কম ছিল, বা দেওয়ার পর ফোটানো খুব কম হয়েছিল। নেড়ে 10 থেকে 15 মিনিট ফোটান। দরকার হলে জলে গোলা 1 টেবিল চামচ বাড়তি ময়দা দিন।"],["প্রেসার কুকার ব্যবহার করা যাবে?","হ্যাঁ। চাপ ওঠার পর মাংস ও মসলা 25 থেকে 30 মিনিট রান্না করুন, তারপর ময়দার গোলা দিয়ে খোলা হাঁড়িতে শেষ করুন। নিরাপত্তার জন্য আপনার কুকারের নির্দেশ মেনে চলুন।"],["নিহারি কি খুব ঝাল?","মসলা পোড়া গরম নয়, উষ্ণতা দেয়। পরিবেশনের সময় টাটকা লঙ্কা প্রত্যেককে বেছে নিতে দেয় তার বাটি কতটা ঝাল হবে।"],["এক দিন আগে কি বানানো যায়?","হ্যাঁ। স্বাদ ফ্রিজে সারারাত থাকলে আরও ভালো হয়। আলতো করে গরম করুন, বেশি ঘন হলে একটু গরম জল দিন, আর সাজানোর জিনিস টাটকা দিন।"]]},"karahi":{"intro":"চিকেন কারাহি সেরা ধাবার খাবার, গভীর কড়াইয়ে দ্রুত রান্না করা, পেঁয়াজ ছাড়া আর লুকোনোর মতো লম্বা মসলার তালিকা ছাড়া। টাটকা টমেটো মসলার মধ্যে গলে যায়, আদা ও কাঁচা লঙ্কা শেষে যায়, আর পুরো পদটি প্রায় 40 মিনিটে তৈরি হয়। কৌশল হলো আঁচ ও সময়। আঁচ বেশি রাখুন, টমেটোকে তার কাজ করতে দিন, আর কারাহি এখনও চিড়বিড় করার সময় আদা দিয়ে শেষ করুন। মসলা চকচকে ও মুরগি নরম থাকতে থাকতে গরম রুটি বা নান দিয়ে সরাসরি কড়াই থেকে খান।","ing":["মুরগি 750 গ্রাম","টমেটো 4টি বড়","আদা রসুন বাটা 1 টেবিল চামচ","কাঁচা লঙ্কা 4টি","আদার জুলিয়েন","ঘি / তেল 1/2 কাপ","লবণ","থেঁতো করা শুকনো লঙ্কা","গরম মসলা","টাটকা ধনেপাতা"],"steps":["টমেটো চার টুকরো করুন আর আদা, লঙ্কা ও ধনেপাতা তৈরি রাখুন। কারাহি দ্রুত এগোয়, তাই সবকিছু হাতের নাগালে থাকতে হবে।","কড়াইয়ে বেশি আঁচে ঘি গরম করুন। মুরগি দিন আর বাইরের রং বদলানো পর্যন্ত ঘন ঘন উল্টে 4 থেকে 5 মিনিট ভাজুন।","আদা রসুন বাটা দিন আর 1 মিনিট ভাজুন। টমেটো ও একটু লবণ দিন, ঢেকে দিন, আর মাঝারি বেশি আঁচে 8 থেকে 10 মিনিট রান্না করুন।","ঢাকনা খুলুন আর নরম টমেটো চামচের পেছন দিয়ে চটকে দিন। মসলা ঘন হয়ে তেল উপরে ওঠা পর্যন্ত ভাজতে থাকুন।","থেঁতো করা শুকনো লঙ্কা দিন আর লবণের স্বাদ দেখুন। মসলা শুকনো মনে হলে শুধু 2 টেবিল চামচ গরম জল দিন, এর বেশি নয়।","আদার জুলিয়েনের অর্ধেক আর কাটা দুটি কাঁচা লঙ্কা দিন। 2 মিনিট আরও ভাজুন যাতে তাদের স্বাদ মসলায় যায়।","গরম মসলা ছড়িয়ে দিন, ঢেকে দিন, আর কম আঁচে 5 মিনিট দম দিন। মুরগি পুরোপুরি রান্না হওয়া উচিত আর তবু রসালো থাকা উচিত।","বাকি আদা, লঙ্কা ও টাটকা ধনেপাতা দিয়ে সাজান। সঙ্গে সঙ্গে পরিবেশন করুন, সরাসরি কড়াই থেকে, রুটি বা নান দিয়ে।"],"tip":"কারাহিতে জল দেবেন না। টমেটোর নিজের জলই যথেষ্ট। আঁচ বেশি রাখুন যাতে মুরগি নরম থাকে আর মসলা ভালো করে ভাজা হয়, আর টাটকা আদা শুরুতে নয়, শেষে দিন।","notes":["পাকা, নরম টমেটো ব্যবহার করুন। শক্ত টমেটো গলতে বেশি সময় নেয় আর মসলা জলীয় রেখে দেয়।","হাড়সহ মুরগি বেশি স্বাদ দেয় আর রসালো থাকে। হাড় ছাড়া থাইও চলে, তবে 3 থেকে 4 মিনিট কম রান্না করুন।","ঘি ধাবার স্বাদ দেয়। তেলও চলে, তবে শেষে একটু বাড়তি আদা দিয়ে স্বাদ তুলুন।","টাটকা আদার জুলিয়েন সাজানো আর স্বাদ দুটোই। শুকনো আদার গুঁড়ো এখানে এর বদলি নয়।"],"variations":["খাসির কারাহি: 750 গ্রাম খাসি নিন, নরম হওয়া পর্যন্ত ঢেকে 40 থেকে 50 মিনিট রান্না করুন, তারপর মসলা যথারীতি বেশি আঁচে ভাজুন।","কাঁচা লঙ্কার কারাহি: শুকনো লঙ্কা বাদ দিন, 8টি কাঁচা লঙ্কা ব্যবহার করুন, অর্ধেক মসলায় আর অর্ধেক সাজানোর জন্য, টাটকা, তীক্ষ্ণ ঝালের জন্য।","মাখন কারাহি: আঁচ থেকে নামিয়ে নেড়ে 1 টেবিল চামচ মাখন ও 2 টেবিল চামচ ক্রিম দিয়ে শেষ করুন, আরও সমৃদ্ধ, মৃদু সংস্করণের জন্য।"],"serving":"রুটি বা নান, পেঁয়াজ ও লেবুর সাধারণ সালাদ, আর পছন্দ হলে রায়তা দিয়ে 4 জনের জন্য যথেষ্ট। কড়াইয়ের মধ্যেই পরিবেশন করুন, পাশে লেবুর ফালি দিয়ে, আর গরম থাকতে খান। মসলা রুটি দিয়ে তুলে খাওয়ার জন্যই, তাই বাড়তি রুটি তৈরি রাখুন। ঠান্ডা পানীয় বা লস্যি ঝালের সঙ্গে সাহায্য করে।","storage":"1 ঘণ্টার মধ্যে ঠান্ডা করুন আর বায়ুরোধী পাত্রে ফ্রিজে 2 দিন পর্যন্ত রাখুন। কড়াইয়ে মাঝারি আঁচে, ঢেকে, 1 থেকে 2 টেবিল চামচ জল দিয়ে পুরোপুরি বাষ্প ওঠা পর্যন্ত গরম করুন। গরম করার পর টাটকা আদা ও ধনেপাতা দিন। 1 মাস পর্যন্ত ফ্রিজ করা যায়, তবে টমেটোর মসলা গলার পর নরম হয়ে যায়, তাই টাটকাই সেরা।","mistakes":["শুরুতেই জল দেওয়া। মসলা ঘন, চকচকে কারাহির বদলে পাতলা ঝোলে পরিণত হয়।","শুরু থেকে শেষ পর্যন্ত কম আঁচে রান্না করা। মুরগি ভাপে সেদ্ধ হয়, টমেটো টুকরো টুকরো থাকে, আর মসলা ঠিকমতো ভাজা হয় না।","শুধু শুরুতে আদা দেওয়া। সেটা রান্না হয়ে যায়, আর টাটকা শেষটা হারিয়ে যায়।","হাড় ছাড়া মুরগি বেশি রান্না করা। বেশি আঁচে দ্রুত শুকিয়ে যায়, তাই আগেই দেখে নিন।"],"faq":[["আমার কারাহিতে মসলা নেই কেন?","টমেটো চটকে যথেষ্টক্ষণ ভাজা হয়নি, বা জল দেওয়া হয়েছিল। টমেটো ভালো করে চটকে নিন আর তেল আলাদা হওয়া পর্যন্ত ভাজুন।"],["কড়াই ছাড়া কি কারাহি বানানো যায়?","হ্যাঁ। গভীর, ভারী ওক বা ভাজার প্যান ব্যবহার করুন। পাতলা প্যান মসলা পুড়িয়ে দেয়, তাই আঁচ একটু কম রাখুন আর বেশি নাড়ুন।"],["কারাহিতে কি পেঁয়াজ থাকার কথা?","ঐতিহ্যবাহী পাকিস্তানি কারাহিতে পেঁয়াজ থাকে না। টমেটোর জলই মসলা বানায়। পেঁয়াজ অন্য পদ বানায়, ঝোলের কাছাকাছি।"],["মুরগি রান্না হয়েছে বুঝব কীভাবে?","সবচেয়ে মোটা অংশে একটা টুকরো কাটলে রস পরিষ্কার বেরোয়, আর মাংস আর গোলাপি থাকে না। নিশ্চিত না হলে সবচেয়ে বড় টুকরোটা কেটে দেখুন।"]]},"daal":{"intro":"ডাল ফ্রাই সেই প্রতিদিনের পদ যা প্রমাণ করে যে ডাল নরম করে রান্না করা হলে আর তড়কা গরম গরম ঢেলে সঙ্গে সঙ্গে ঢেকে দিলে সাধারণ খাবারও মনে রাখার মতো হতে পারে। মসুর ও মুগ দ্রুত রান্না হয় এবং কোনো ক্রিম ছাড়াই ক্রিমের মতো হয়, আর উপরের ঘি, রসুন, জিরা ও গোটা শুকনো লঙ্কা সেই সুগন্ধ দেয় যা বাটির আগেই টেবিলে পৌঁছে যায়। এটা ভাত বা রুটির জন্য আরামের খাবার, ব্যস্ত সপ্তাহের রাতের জন্য আর যেসব দিনে অভিনব কিছু দরকার নেই সেসব দিনের জন্য। পুরো রেসিপিতে প্রায় 35 মিনিট লাগে, আর তার বেশিরভাগটাই ডাল চুপচাপ ফুটতে থাকে।","ing":["মসুর / মুগ ডাল 1½ কাপ","হলুদ 1/2 চা চামচ","লবণ","রসুন 4 কোয়া","জিরা 1 চা চামচ","গোটা শুকনো লঙ্কা 3টি","ঘি 3 টেবিল চামচ","কাঁচা লঙ্কা","টাটকা ধনেপাতা","লেবু"],"steps":["ডাল কয়েকবার জল বদলে ধুয়ে নিন যতক্ষণ না জল মোটামুটি পরিষ্কার হয়, তারপর ভালো করে ছেঁকে নিন।","ডাল হাঁড়িতে হলুদ ও 4 কাপ জল দিয়ে বসান। ফুটতে দিন, ফেনা তুলে ফেলুন, আর আঁচ কমিয়ে দিন।","20 থেকে 25 মিনিট মাঝে মাঝে নেড়ে অল্প আঁচে ফোটান, যতক্ষণ না ডাল পুরোপুরি নরম ও ক্রিমের মতো হয়। বেশি ঘন হয়ে গেলে গরম জল দিন।","স্বাদ দেখে লবণ দিন। ডাল ঢালার মতো তরল হওয়া উচিত, শক্ত নয়, কারণ ঠান্ডা হলে সেটা ঘন হয়।","রসুন পাতলা করে কাটুন। ছোট প্যানে মাঝারি আঁচে ঘি গরম করুন আর জিরা দিন। চিড়বিড় করলে রসুন দিন।","রসুন সোনালি হওয়া পর্যন্ত ভাজুন, বাদামি নয়। গোটা শুকনো লঙ্কা দিন, দশ পর্যন্ত গুনুন, আর প্যানটা সঙ্গে সঙ্গে আঁচ থেকে নামিয়ে নিন।","গরম তড়কা একবারে ডালের উপর ঢেলে দিন, চিড়বিড় শব্দ শুনুন, আর সুগন্ধ ভেতরে থাকার জন্য হাঁড়িটা 2 মিনিট ঢেকে রাখুন।","কাঁচা লঙ্কা ও ধনেপাতা মেশান, উপরে লেবু চিপে দিন, আর ভাত বা রুটির সঙ্গে গরম পরিবেশন করুন।"],"tip":"তড়কা ঢালার সঙ্গে সঙ্গেই ডাল ঢেকে দিন। এতে সুগন্ধ রান্নাঘরে বেরিয়ে না গিয়ে ডালের ভেতরেই থাকে, আর রসুনের স্বাদ পুরো হাঁড়িতে ছড়িয়ে যায়।","notes":["মসুর ডাল সবচেয়ে তাড়াতাড়ি রান্না হয় আর ক্রিমের মতো হয়। মুগ ডাল একটু বেশি আকৃতি ধরে রাখে। দুটোই চলে, আর অর্ধেক অর্ধেক মিশ্রণও ভালো।","হলুদ রং ও হালকা স্বাদের জন্য। বেশি হলে ডাল তেতো হয়, তাই মেপে দিন।","তড়কার জন্য রসুন কাটুন, থেঁতো করবেন না। ফালিগুলো সমানভাবে সোনালি হয় আর মচমচে থাকে।","ঘি তড়কার স্বাদ সবচেয়ে ভালো বয়ে নেয়। তেলও চলে, তবে পূরণের জন্য এক কোয়া বাড়তি রসুন দিন।"],"variations":["পালং ডাল: রান্না করা ডালে 2 কাপ কাটা পালং শাক মেশান আর তড়কার আগে 5 মিনিট ফোটান।","টমেটো ডাল: শুরুতে ডালের সঙ্গে 1টি কাটা টমেটো দিন, টক আর একটু ঘন ফলাফলের জন্য।","বাড়তি রসুন: তড়কায় রসুন দ্বিগুণ করুন আর তার সঙ্গে আধা চা চামচ থেঁতো করা শুকনো লঙ্কা দিন।"],"serving":"ভাপা ভাত বা রুটি, লেবুর ফালি, আর পাশে সাধারণ সালাদ বা আচার দিয়ে 4 জনের জন্য যথেষ্ট। ডাল সবচেয়ে ভালো পরিবেশন করা হয় পাতলা ও গরম, গভীর বাটিতে, উপরে তড়কা দেখা যায় এমনভাবে। ভাতের সঙ্গে পরিবেশন করলে টেবিলে ভাতের উপর ডাল ঢেলে দিন। একটা ভাজা ডিম বা এক টুকরো পাঁপড় এটাকে আরও ভরাট খাবার বানিয়ে দেয়।","storage":"ঠান্ডা করুন আর বায়ুরোধী পাত্রে ফ্রিজে 3 দিন পর্যন্ত রাখুন। ডাল ফ্রিজে ঘন হয়, তাই গরম করার সময় একটু গরম জল মেশান। কম আঁচে নেড়ে, পুরোপুরি বাষ্প ওঠা পর্যন্ত গরম করুন, আর গরম করার পর টাটকা ধনেপাতা দিন। ভাগে ভাগে 1 মাস পর্যন্ত ফ্রিজ করুন, ফ্রিজে গলিয়ে নিন, আর সেরা সুগন্ধের জন্য টাটকা তড়কা বানান।","mistakes":["ডাল কম রান্না করা। দানাদার ডাল কখনও ক্রিমের মতো হয় না, তড়কা যত ভালোই হোক।","রসুন পুড়িয়ে ফেলা। বাদামি রসুন তেতো হয়ে পুরো হাঁড়ি নষ্ট করে, তাই প্যানটা আগেই আঁচ থেকে নামিয়ে নিন।","তড়কার পর হাঁড়ি ঢাকা ছাড়া রাখা। সুগন্ধ বেরিয়ে যায় আর ডাল স্বাদহীন লাগে।","শক্ত জলের এলাকায় একদম শুরুতে লবণ দিলে নরম হওয়া ধীর হতে পারে, তাই ডাল শক্ত থাকলে নরম হওয়ার পর লবণ দিন।"],"faq":[["তড়কা ডালের জন্য কোন ডাল সবচেয়ে ভালো?","মসুর সবচেয়ে দ্রুত ও সবচেয়ে ক্রিমের মতো হয়। মুগ কাছাকাছি দ্বিতীয়। তুর ডালও চলে, তবে বেশি রান্না লাগে আর প্রেসার কুকার সাহায্য করে।"],["ঘি ছাড়া কি ডাল ফ্রাই বানানো যায়?","হ্যাঁ। তেল ব্যবহার করুন আর এক কোয়া বাড়তি রসুন দিন। ফলাফল হালকা হয়, আর তড়কা তবু কাজ করে, তবে সুগন্ধ কম সমৃদ্ধ হয়।"],["আমার ডাল জলীয় হলো কেন?","যথেষ্টক্ষণ ফোটানো হয়নি, বা বেশি জল ব্যবহার করা হয়েছিল। ঘন করতে কয়েক মিনিট ঢাকা ছাড়া ফোটান, আর মনে রাখবেন ঠান্ডা হলে আরও ঘন হয়।"],["প্রেসার কুকারে কি ডাল রান্না করা যায়?","হ্যাঁ। 2টি সিটি বা চাপে প্রায় 8 মিনিট রান্না করুন, চাপ নিজে থেকে বেরোতে দিন, তারপর খোলা হাঁড়িতে তড়কা দিয়ে শেষ করুন।"]]},"chapli":{"intro":"চাপলি কাবাব হলো প্লেটে পেশোয়ার: চ্যাপ্টা, নরম, মসলায় ভরপুর, আর কিনারাগুলো মচমচে হওয়া পর্যন্ত তাওয়ায় ভাজা। নামটা এসেছে এর চ্যাপ্টা আকৃতি থেকে, আর স্বাদ আসে টমেটো, ডালিমের বীজ, থেঁতো করা গোটা ধনে ও কাঁচা লঙ্কা থেকে, যা কিমার মধ্যে মেশানো হয়। এটা একই সঙ্গে স্ট্রিট ফুড আর উৎসবের খাবার, নান, পেঁয়াজ ও সবুজ চাটনি দিয়ে খাওয়া হয়, আর সবচেয়ে ভালো হয় ঠান্ডা কিমা ও নরম হাতে বানালে। মাঝারি কম আঁচে ভাজুন যাতে বাইরেটা পুড়ে না গিয়ে ভেতরটা রান্না হয়, আর কাবাব বানানোর লোকেরা যেমন করে, মাঝখানে এক টুকরো টমেটো চেপে দিন।","ing":["গরুর কিমা 500 গ্রাম","টমেটো 1টি মিহি করে কাটা","পেঁয়াজ 1টি","ডালিমের বীজ 1 টেবিল চামচ","থেঁতো করা গোটা ধনে","কাঁচা লঙ্কা 3টি","আদা","লবণ","ভুট্টার আটা 2 টেবিল চামচ","ভাজার জন্য তেল"],"steps":["পেঁয়াজ ও টমেটো খুব মিহি করে কাটুন আর বাড়তি টমেটোর রস চিপে ফেলে দিন, যাতে মিশ্রণটা আকৃতি দেওয়ার মতো শক্ত থাকে।","কিমা একটা বাটিতে টমেটো, পেঁয়াজ, ডালিমের বীজ, থেঁতো করা ধনে, লঙ্কা, আদা, লবণ ও ভুট্টার আটার সঙ্গে রাখুন। হাত দিয়ে মেশান যতক্ষণ না সবে মিশে যায়।","ঢেকে মিশ্রণটা ফ্রিজে 20 মিনিট রেখে দিন। ঠান্ডা কিমা আকৃতি ধরে রাখে আর ভালো ভাজা হয়।","ঠান্ডা জলে হাত ভিজিয়ে নিন। একটা ভাগ নিন, প্রায় 4 ইঞ্চি চওড়া পাতলা গোল আকারে চ্যাপ্টা করুন, আর মাঝখানে ছোট এক টুকরো টমেটো চেপে দিন।","তাওয়ায় মাঝারি আঁচে উদারভাবে তেল গরম করুন। তেল চিড়বিড় করার মতো গরম হওয়া উচিত, তবে ধোঁয়া ওঠা উচিত নয়।","কাবাবগুলো ফাঁক রেখে ঢুকিয়ে দিন। না চেপে প্রথম পাশ 4 থেকে 5 মিনিট ভাজুন।","চওড়া খুন্তি দিয়ে আলতো করে উল্টে দিন আর দুই পাশ সোনালি হয়ে পুরোপুরি রান্না হওয়া পর্যন্ত আরও 4 থেকে 5 মিনিট ভাজুন।","তুলে নিন, অল্প ছেঁকে নিন, আর সবুজ চাটনি, কাটা পেঁয়াজ ও নান দিয়ে গরম পরিবেশন করুন।"],"tip":"কাবাব খুব বেশি চাপবেন না। আলতো করে উল্টান, নইলে ভেঙে যাবে। ঠান্ডা কিমায় ভালো কাবাব হয়, তাই প্রতিটি ব্যাচ আকৃতি দেওয়া পর্যন্ত মিশ্রণটা ফ্রিজে রাখুন।","notes":["কিছুটা চর্বিযুক্ত কিমা ব্যবহার করুন, প্রায় 15 থেকে 20 শতাংশ। খুব চর্বিহীন কিমায় শুকনো, ঝুরঝুরে কাবাব হয়।","ভুট্টার আটা মিশ্রণটা বাঁধে আর ক্লাসিক গঠন দেয়। গমের আটাও চলে, তবে কাবাব আরও ঘন হয়।","ডালিমের বীজ টক একটা ঝলক দেয়। হালকা করে থেঁতো করুন, বাটা বানাবেন না।","মিহি করে কাটা টমেটো আর্দ্রতা ও স্বাদ দেয়, তবে বেশি রস কাবাব ভেঙে ফেলে, তাই আগে ছেঁকে নিন।"],"variations":["মুরগির চাপলি: মুরগির কিমা ব্যবহার করুন, 1 টেবিল চামচ বাড়তি ভুট্টার আটা দিন, আর প্রতি পাশ 3 থেকে 4 মিনিট ভাজুন, কারণ মুরগি তাড়াতাড়ি রান্না হয়।","বাড়তি ঝাল: 1 চা চামচ থেঁতো করা শুকনো লঙ্কা ও একটা বাড়তি কাঁচা লঙ্কা দিন, আর বাড়তি চাটনি দিয়ে পরিবেশন করুন।","চাপলি বার্গার: সেঁকা বানের মধ্যে একটা কাবাব রাখুন পেঁয়াজ, টমেটো, চাটনি ও ভাজা ডিম দিয়ে, পেশোয়ার ধাঁচের বার্গারের জন্য।"],"serving":"নান, সবুজ চাটনি, কাটা পেঁয়াজ, লেবু ও সালাদ দিয়ে প্রধান পদ হিসেবে 4 জনের জন্য যথেষ্ট। প্রতিজনকে প্রচুর চাটনি দিয়ে 2টি কাবাব পরিবেশন করুন, আর বাড়তি নান গরম রাখুন। চাপলি কাবাব স্টার্টার হিসেবেও চলে, প্রধান পদের আগে প্রতিজনকে চাটনি ও লেবু দিয়ে একটা কাবাব। পুদিনার রায়তা ঝাল সুন্দরভাবে ঠান্ডা করে।","storage":"রান্না করা কাবাব ঠান্ডা করে বায়ুরোধী পাত্রে ফ্রিজে 2 দিন পর্যন্ত রাখুন। তাওয়ায় মাঝারি আঁচে পুরোপুরি গরম হওয়া পর্যন্ত, বা 180C ওভেনে 8 থেকে 10 মিনিট গরম করুন। রান্না না করা মিশ্রণ ফ্রিজে 1 দিন পর্যন্ত থাকে। আকৃতি দেওয়া, রান্না না করা কাবাব বেকিং কাগজের ভাঁজের মধ্যে 1 মাস পর্যন্ত ফ্রিজ করুন, আর জমাট অবস্থা থেকে ভাজুন, প্রতি পাশে 2 মিনিট যোগ করে।","mistakes":["মোটা কাবাব আকৃতি দেওয়া। বাইরেটা পুড়ে যায় ভেতরটা রান্না হওয়ার আগেই, তাই পাতলা ও সমান রাখুন।","খুব বেশি আঁচে ভাজা। মসলা পুড়ে যায় আর কাবাব উল্টানোর সময় ভেঙে যায়।","খুন্তি দিয়ে চাপা। রস বেরিয়ে যায় আর কাবাব শুকিয়ে যায়।","দোকান থেকে আনা গরম কিমা ব্যবহার করা। সেটা নরম, আঠালো আর আকৃতি দেওয়া কঠিন, তাই আগে ঠান্ডা করুন।"],"faq":[["আমার চাপলি কাবাব ভেঙে যায় কেন?","মিশ্রণটা বেশি ভেজা ছিল, কাবাব খুব মোটা ছিল, বা খুব তাড়াতাড়ি উল্টানো হয়েছিল। টমেটো ছেঁকে নিন, মিশ্রণ ঠান্ডা করুন, কাবাব পাতলা রাখুন, আর উল্টানোর আগে প্রথম পাশ বসতে দিন।"],["চাপলি কাবাব কি বেক করা যায়?","হ্যাঁ। তেল মাখিয়ে 200C তাপে 15 থেকে 18 মিনিট বেক করুন, একবার উল্টে। ভাজা কাবাবের চেয়ে কম মচমচে হয়, তবে তবু সুস্বাদু।"],["ডালিমের বীজ কীসের জন্য?","আনারদানা টক, ফলের একটা সুর দেয় যা সমৃদ্ধ কিমার ভারসাম্য আনে। না পেলে 1 চা চামচ লেবুর রস ও কয়েকটা থেঁতো করা শুকনো ক্র্যানবেরি ব্যবহার করুন, তবে স্বাদ আলাদা হয়।"],["মিশ্রণ কি আগে বানানো যায়?","হ্যাঁ। মিশিয়ে ঢেকে ফ্রিজে 1 দিন পর্যন্ত রাখুন। ভাজার ঠিক আগে আকৃতি দিন, যাতে কাবাব আকৃতি ধরে রাখে।"]]},"tikka":{"intro":"চিকেন টিক্কা সেই পদ যা ভালোভাবে ধৈর্য শেখায়। মেরিনেড কাজ করে, দই ও মসলা অন্তত এক ঘণ্টা ধরে মাংসের ভেতরে ঢোকে, আর গ্রিলের শুধু বেশি আঁচ ও প্রতি পাশে কয়েক মিনিট দরকার। ঠিকঠাক হলে বাইরেটা হালকা পোড়া ও ধোঁয়াটে হয়, ভেতরটা রসালো থাকে, আর শেষে লেবু ও চাট মসলা সবকিছু জাগিয়ে তোলে। এটা স্টার্টার হিসেবে, নান দিয়ে প্রধান পদ হিসেবে, আর পরের দিন মোড়ক ও সালাদে কেটে দিয়ে চলে। নিচের রেসিপিতে ওভেন গ্রিল বা বারবিকিউ ব্যবহার করা হয়, আর আপনার কাছে যেটা আছে সেটা হলে গরম প্যানও চলে।","ing":["মুরগি (লেগ / হাড় ছাড়া) 750 গ্রাম","দই 1/2 কাপ","শুকনো লঙ্কা 1 টেবিল চামচ","হলুদ","গরম মসলা","জিরা গুঁড়ো","আদা রসুন বাটা 1 টেবিল চামচ","লেবু 1টি","মাখানোর জন্য তেল / মাখন"],"steps":["মুরগি সমান টুকরো করে কাটুন আর প্রতিটি টুকরোয় 2টি অগভীর কাট দিন, যাতে মেরিনেড ভেতরে পৌঁছায়।","দই, শুকনো লঙ্কা, হলুদ, গরম মসলা, জিরা গুঁড়ো, আদা রসুন বাটা, লেবুর রস ও লবণ মসৃণ বাটা বানিয়ে মেশান।","মুরগি ভালো করে মাখান, ঢেকে দিন, আর অন্তত 1 ঘণ্টা ফ্রিজে রাখুন। সারারাত রাখাও চলে আর গভীর স্বাদ দেয়।","রান্নার 20 মিনিট আগে মুরগি বের করে নিন, যাতে আঁচে পড়ার সময় ফ্রিজের ঠান্ডা না থাকে।","গ্রিল বা বারবিকিউ বেশি আঁচে গরম করুন। ঝাঁঝরি হালকা তেল দিন আর মুরগি টুকরোগুলোর মধ্যে ফাঁক রেখে এক স্তরে রাখুন।","প্রথম পাশ 6 থেকে 8 মিনিট গ্রিল করুন, একবার মাখন বা তেল মাখিয়ে, কিনারাগুলো হালকা পোড়া পর্যন্ত।","উল্টে দিন আর পুরোপুরি রান্না হয়ে রস পরিষ্কার বেরোনো পর্যন্ত আরও 6 থেকে 8 মিনিট গ্রিল করুন।","5 মিনিট রেখে দিন, লেবুর রস ও চাট মসলা ছড়িয়ে দিন, আর পেঁয়াজ, চাটনি ও নান দিয়ে গরম পরিবেশন করুন।"],"tip":"মেরিনেট যত লম্বা হয়, টিক্কা তত নরম হয়। সময় কম হলে অন্তত 30 মিনিট দিন, আর কাট দেওয়া কখনও বাদ দেবেন না, কারণ এভাবেই মেরিনেড মোটা টুকরোয় ঢোকে।","notes":["থাইয়ের মাংস বেশি আঁচে বুকের মাংসের চেয়ে রসালো থাকে। বুকের মাংসও চলে, তবে এক মিনিট আগে দেখে নিন।","দই ঝুলিয়ে নিন বা ঘন দই ব্যবহার করুন। জলীয় দই মুরগি থেকে সরে যায় আর গ্রিলে পুড়ে যায়।","মেরিনেডে টাটকা লেবু নরম করতে সাহায্য করে, তবে বেশি লেবু বেশি সময় থাকলে উপরের অংশ নরম পিণ্ডের মতো হতে পারে, তাই সারারাতের মেরিনেডে লেবু হালকা রাখুন।","চাট মসলা শেষে দেওয়া হয়, মেরিনেডে নয়, যাতে এর টক ভাব উজ্জ্বল থাকে।"],"variations":["মালাই টিক্কা: শুকনো লঙ্কার বদলে সাদা গোলমরিচ নিন, মেরিনেডে 2 টেবিল চামচ ক্রিম ও 1 টেবিল চামচ পনির দিন, মৃদু, ক্রিমের মতো সংস্করণের জন্য।","হরিয়ালি টিক্কা: ধনেপাতা, পুদিনা, কাঁচা লঙ্কা ও দই মিশিয়ে সবুজ মেরিনেড বানান, আর একইভাবে গ্রিল করুন।","টিক্কা মোড়ক: বেঁচে যাওয়া টিক্কা কাটুন, পরের দিন দুপুরের খাবারের জন্য পেঁয়াজ, চাটনি ও সালাদ দিয়ে পরোটা বা রুটিতে মুড়ে নিন।"],"serving":"নান বা রুটি, কাটা পেঁয়াজ, লেবুর ফালি, সবুজ চাটনি ও সালাদ দিয়ে 4 জনের জন্য যথেষ্ট। গ্রিল থেকে সরাসরি গরম প্লেটে পরিবেশন করুন, লেবু টেবিলে উপরে চিপে দেওয়া হয়। টিক্কা ভাতের উপর, মোড়কে, বা সালাদের উপরেও ভালো বসে। পাশে বাড়তি চাটনি রাখুন, কারণ লোকেরা সবসময় আরও চায়।","storage":"ঠান্ডা করুন আর বায়ুরোধী পাত্রে ফ্রিজে 2 দিন পর্যন্ত রাখুন। 180C গরম ওভেনে 8 মিনিট, বা মাঝারি আঁচে প্যানে, বাষ্প ওঠা পর্যন্ত গরম করুন। বেশিক্ষণ মাইক্রোওয়েভ করবেন না, কারণ এতে মুরগি শুকিয়ে যায় আর পোড়া ভাব নরম হয়। মেরিনেট করা, রান্না না করা মুরগি ফ্রিজে 1 দিন পর্যন্ত থাকে। রান্না করা টিক্কা 1 মাস পর্যন্ত ফ্রিজ করুন আর ফ্রিজে গলিয়ে নিন।","mistakes":["ফ্রিজের ঠান্ডা মুরগি গ্রিল করা। ভেতরটা রান্না হওয়ার আগেই বাইরেটা পুড়ে যায়, তাই আগে ঘরের তাপমাত্রায় আনুন।","গ্রিল ভরে ফেলা। টুকরোগুলো পোড়ার বদলে ভাপে সেদ্ধ হয়, তাই ফাঁক রাখুন আর দরকার হলে ব্যাচে রান্না করুন।","রেখে দেওয়া বাদ দেওয়া। সঙ্গে সঙ্গে কাটলে রস বেরিয়ে যায় আর টিক্কা শুকিয়ে যায়।","পাতলা মেরিনেড ব্যবহার করা। সেটা ঝরে পড়ে আর পুড়ে যায়, মুরগিকে স্বাদহীন রেখে দেয়।"],"faq":[["প্যানে কি টিক্কা রান্না করা যায়?","হ্যাঁ। অল্প তেল দিয়ে বেশি আঁচে ভারী প্যান ব্যবহার করুন, প্রতি পাশ 6 থেকে 7 মিনিট। একই ধোঁয়াটে পোড়া ভাব হবে না, তবে স্বাদ কাছাকাছি।"],["বাড়িতে ধোঁয়াটে স্বাদ পাব কীভাবে?","গ্রিল করার পর হাঁড়িতে গরম কয়লার টুকরোসহ ছোট একটা স্টিলের বাটি রাখুন, তার উপর কয়েক ফোঁটা তেল ছিটিয়ে দিন, 2 মিনিট ঢেকে রাখুন, আর বাটিটা সরিয়ে নিন। রান্নাঘর বাতাস চলাচলযুক্ত রাখুন।"],["বুকের মুরগি ব্যবহার করা যাবে?","হ্যাঁ, তবে বেশি রান্না করবেন না। প্রতি পাশ 5 থেকে 6 মিনিট পর দেখে নিন, আর ভালো করে রেখে দিন। থাই বেশি ক্ষমাশীল।"],["টিক্কা কি ঝাল?","এটা উষ্ণ ও মসলাদার, প্রচণ্ড ঝাল নয়। মৃদু সংস্করণের জন্য শুকনো লঙ্কা 1 চা চামচে কমিয়ে দিন, আর চাটনিকে টেবিলে ঝাল যোগ করতে দিন।"]]},"halwapuri":{"intro":"হালুয়া পুরি লাহোরে রবিবারের সকালের খাবার, আর অনেক বাড়িতে এটা শুধু খাবার নয়, পুরো একটা অনুষ্ঠান। তিনটি জিনিস একসঙ্গে আসে, ফোলা পুরি, নরম সুজির হালুয়া, আর আলু দিয়ে মসলাদার ছোলা, আর আনন্দ হলো এক কামড়ে প্রতিটার একটু করে নেওয়া। প্রতিটি অংশ নিজে নিজে সহজ, তবে সময়ের ব্যাপারটা গুরুত্বপূর্ণ। পুরি সবার শেষে ভাজুন, যাতে সেটা ফোলা ও গরম আসে, হালুয়া গরম ও নরম রাখুন, আর ছোলা ফুটতে দিন যতক্ষণ না মসলা সেগুলো ঢেকে ফেলে। ধীর সকালে রান্না করুন, একসঙ্গে খান, আর তাড়াহুড়ো করবেন না।","ing":["ময়দা 2 কাপ","সুজি 1 কাপ","চিনি 1 কাপ","ঘি 1/2 কাপ","ছোলা (সেদ্ধ) 2 কাপ","আলু 1টি","পেঁয়াজ","টমেটো","গরম মসলা","হলুদ","শুকনো লঙ্কা","এলাচ","সাজানোর জন্য বাদাম"],"steps":["ময়দা জল ও এক চিমটি লবণ দিয়ে শক্ত, মসৃণ ময়দা মেখে নিন। ঢেকে 20 মিনিট রেখে দিন।","ছোলা আগে থেকে সেদ্ধ না হলে, নরম কিন্তু নরম পিণ্ড না হওয়া পর্যন্ত সেদ্ধ করুন, আর রান্নার জল থেকে 1 কাপ রেখে দিন।","সুজি কম আঁচে ঘিয়ে ভাজুন, অনবরত নেড়ে, যতক্ষণ না সোনালি হয় আর বাদামের মতো গন্ধ আসে, প্রায় 8 থেকে 10 মিনিট।","গরম জল ও চিনি সাবধানে দিন, এটা ফুটে উঠবে, হালুয়া ঘন হওয়া পর্যন্ত নাড়ুন, তারপর এলাচ দিন আর কম আঁচে 5 মিনিট ঢেকে রাখুন।","তেল গরম করুন, পেঁয়াজ নরম হওয়া পর্যন্ত ভাজুন, টমেটো, আলু, গরম মসলা, হলুদ ও শুকনো লঙ্কা দিন, আর মসলা ভালো করে ভাজুন।","ছোলা ও রান্নার জল দিন, 10 মিনিট ফোটান, আর ঝোল ঘন করতে কয়েকটা ছোলা পাশে চেপে দিন।","ছোট পুরি বেলুন, মুদ্রার কিনারার চেয়ে মোটা নয়, আর গরম তেলে ডুবিয়ে ভাজুন, আলতো করে চেপে যাতে প্রতিটা ফুলে ওঠে। কাগজে ছেঁকে নিন।","পুরি, হালুয়া ও ছোলা এক প্লেটে একসঙ্গে পরিবেশন করুন, হালুয়ার উপর বাদাম দিয়ে সাজিয়ে।"],"tip":"পুরি বেলার সময় বেশি ময়দা ব্যবহার করবেন না, নইলে ফুলবে না। তেল ভালো গরম হলে পুরি সঙ্গে সঙ্গে ফুলে ওঠে, তাই আগে ময়দার ছোট এক টুকরো দিয়ে পরীক্ষা করুন, সেটা সেকেন্ডের মধ্যে উঠে আসা উচিত।","notes":["শক্ত ময়দায় ফোলা পুরি হয়। নরম ময়দা তেল শুষে নেয় আর চ্যাপ্টা থাকে, তাই শক্ত করে মাখুন আর ভালো করে রেখে দিন।","মিহি সুজিতে মসৃণ হালুয়া হয়। মোটা সুজিতে বেশি জল ও বেশি রান্না লাগে।","ছোলার রান্নার জল রেখে দিন। এটা ঝোল স্বাভাবিকভাবে ঘন করে আর স্বাদ বয়ে নেয়।","এলাচ হালুয়ায় শেষে যায়, যাতে এর সুগন্ধ রান্না হয়ে যাওয়ার বদলে টাটকা থাকে।"],"variations":["ছোলার বদলে আলুর তরকারি: একই মসলায় আলু রান্না করুন, অর্ধেক চটকে দিন, আর ঝাল পাশের পদ হিসেবে পরিবেশন করুন।","কম মিষ্টি হালুয়া: চিনি 3/4 কাপে কমিয়ে দিন আর একটু বাড়তি এলাচ দিন, ঝাল ছোলার সঙ্গে মানানসই হালুয়ার জন্য।","গোটা গমের পুরি: অর্ধেক গোটা গমের আটা ও অর্ধেক সাদা ময়দা ব্যবহার করুন, ময়দা একটু বেশি সময় রেখে দিন, আর একটু মোটা বেলুন।"],"serving":"প্রতিজনকে 2 থেকে 3টি পুরি, এক চামচ হালুয়া, আর এক প্লেটে উদারভাবে এক হাতা ছোলা দিয়ে 4 জনের জন্য যথেষ্ট। আচার, কাটা পেঁয়াজ ও লেবু দিয়ে পরিবেশন করুন, আর পাশে চা। হালুয়া পুরি বসে খাওয়ার সকালের খাবার, গরম খাওয়া হয়, সবাই একসঙ্গে টেবিলে। বাড়তি পুরি বানান, কারণ সেটাই সবচেয়ে তাড়াতাড়ি শেষ হয়।","storage":"পুরি টাটকা খান, এটা ভালো থাকে না। হালুয়া ফ্রিজে বায়ুরোধী পাত্রে 3 দিন পর্যন্ত থাকে, আর প্যানে কম আঁচে একটু দুধ বা জল দিয়ে গরম করা যায়। ছোলা ফ্রিজে 3 দিন পর্যন্ত থাকে, আর চুলায় টগবগ করা পর্যন্ত গরম করা যায়। সাজানো প্লেট জমিয়ে রাখবেন না, তিনটি অংশ আলাদা রাখুন আর পরিবেশনের সময় একত্র করুন।","mistakes":["পুরি বেশি মোটা বেলা বা বেশি শুকনো ময়দা ব্যবহার করা। ফোলার বদলে চ্যাপ্টা ও চিবোনো থাকে।","বেশি আঁচে সুজি ভাজা। জায়গায় জায়গায় বাদামি হয় আর পোড়া স্বাদ আসে, তাই আঁচ কম রাখুন আর নাড়ুন।","গরম সুজিতে ঠান্ডা জল দেওয়া। ডেলা হয়ে যায়, তাই গরম জল ব্যবহার করুন আর সঙ্গে সঙ্গে নাড়ুন।","যথেষ্ট গরম নয় এমন তেলে পুরি ভাজা। তেল শুষে নেয় আর তেলতেলে হয়।"],"faq":[["আমার পুরি ফোলে না কেন?","ময়দা খুব নরম ছিল, পুরি খুব মোটা বেলা হয়েছিল, বা তেল যথেষ্ট গরম ছিল না। শক্ত করে মাখুন, পাতলা বেলুন, আর আগে তেল পরীক্ষা করুন।"],["কৌটোর ছোলা ব্যবহার করা যাবে?","হ্যাঁ। ছেঁকে ধুয়ে নিন, তারপর মসলায় 10 মিনিট ফোটান। একটু গরম জল দিন, কারণ কৌটোর ছোলার রান্নার জল থাকে না।"],["হালুয়া কতটা মিষ্টি হওয়া উচিত?","ঐতিহ্যবাহী হালুয়া পুরির হালুয়া বেশ মিষ্টি হয়, ঝাল ছোলার ভারসাম্যের জন্য। কম মিষ্টি পছন্দ হলে চিনি কমান, তবে অর্ধেক করবেন না, নইলে গঠন বদলে যায়।"],["অংশগুলো কি আগে বানানো যায়?","হ্যাঁ। আগের দিন হালুয়া ও ছোলা বানিয়ে ফ্রিজে রাখুন। সকালে পুরি টাটকা ভাজুন, কারণ গরম করা পুরি কখনও তত ভালো হয় না।"]]},"samosa":{"intro":"ভালো সমোসা প্রথম কামড়েই বোঝা যায়, মচমচে পেস্ট্রি যা ভেঙে যায়, তারপর মটর, আদা ও ধনেপাতা দিয়ে মসলাদার আলু। পেস্ট্রি শক্ত ও রাখা হতে হবে, পুর ভেজা নয়, শুকনো হতে হবে, আর ভাজা ধীরে, কম আঁচে হতে হবে, যাতে খোলসটা এক মিনিটে বাদামি হয়ে ভেতরে ফ্যাকাসে থাকার বদলে পুরোটা সোনালি হয়। এই রেসিপিতে ক্লাসিক পাঞ্জাবি সমোসা হয়, যেটা সবুজ ও তেঁতুলের চাটনি আর এক কাপ চা দিয়ে পরিবেশন করা হয়। দ্বিগুণ বানান, কারণ এগুলো দ্রুত শেষ হয়, আর বাড়তিগুলো অন্য দিনের জন্য ভাজার আগে ফ্রিজ করুন।","ing":["ময়দা 2 কাপ","জোয়ান 1/2 চা চামচ","আলু (সেদ্ধ) 4টি","মটর 1/2 কাপ","আদা","কাঁচা লঙ্কা","গরম মসলা","টাটকা ধনেপাতা","ডালিমের বীজ","ভাজার জন্য তেল"],"steps":["জোয়ান ও 3 টেবিল চামচ তেল আঙুলের ডগা দিয়ে ময়দায় মাখুন যতক্ষণ না ব্রেডক্রাম্বের মতো দেখায়।","অল্প অল্প করে জল দিন আর শক্ত, কড়া ময়দা মাখুন। নরম হওয়া উচিত নয়। ঢেকে 20 মিনিট রেখে দিন।","আলু সবে নরম হওয়া পর্যন্ত সেদ্ধ করুন, ঠান্ডা করুন, আর মোটামুটি ভেঙে নিন। মসৃণ করে চটকাবেন না।","1 টেবিল চামচ তেল গরম করুন, আদা ও কাঁচা লঙ্কা 30 সেকেন্ড ভাজুন, মটর, গরম মসলা, লবণ ও ডালিমের বীজ দিন, আর 2 মিনিট রান্না করুন।","আলু ও ধনেপাতা দিন, ভালো করে মেশান, আর পুর শুকিয়ে যাওয়া পর্যন্ত 2 থেকে 3 মিনিট রান্না করুন। পুরোপুরি ঠান্ডা করুন।","ময়দা বলের ভাগে ভাগ করুন, প্রতিটা ডিম্বাকারে বেলুন, অর্ধেক করে কাটুন, আর সোজা কিনারা জল দিয়ে বন্ধ করে শঙ্কু বানান।","প্রতিটি শঙ্কু চার ভাগের তিন ভাগ ভরুন, উপরের কিনারা শক্ত করে বন্ধ করুন, আর বন্ধ করতে চাপ দিন। পুর বেরোচ্ছে না দেখে নিন।","কম আঁচে তেলে 12 থেকে 15 মিনিট ভাজুন, মাঝে মাঝে উল্টে, গাঢ় সোনালি ও মচমচে হওয়া পর্যন্ত। ছেঁকে নিন আর চাটনি দিয়ে পরিবেশন করুন।"],"tip":"সমোসা সবসময় কম আঁচে ভাজুন। বেশি আঁচে পেস্ট্রি পুড়ে যাবে আর ভেতরটা কাঁচা থাকবে, আর খোলস মচমচে ও সমান হওয়ার বদলে ফোসকা পড়বে।","notes":["শক্ত ময়দাই মচমচে পেস্ট্রির রহস্য। নরম ময়দায় চিবোনো, তেলতেলে সমোসা হয়।","ভরার আগে পুর পুরোপুরি ঠান্ডা করুন। গরম পুর ভেতর থেকে পেস্ট্রিতে বাষ্প দেয় আর বন্ধটা দুর্বল করে।","জোয়ান ক্লাসিক স্বাদ দেয় আর হজমে সাহায্য করে। পেলে বাদ দেবেন না।","শুকনো পুর জরুরি। ভেজা পুর বেরিয়ে যায়, পেস্ট্রি নরম করে, আর ভাজা এলোমেলো করে।"],"variations":["কিমা সমোসা: আলুর বদলে রান্না করা, মসলাদার কিমা নিন, পুরোপুরি ঠান্ডা করুন, আর একইভাবে ভাজুন।","পনির সমোসা: আরও সমৃদ্ধ নিরামিষ পুরের জন্য মটর, গরম মসলা ও ধনেপাতা দিয়ে ভাঙা পনির ব্যবহার করুন।","বেক করা সমোসা: তেল মাখিয়ে 190C তাপে 20 থেকে 25 মিনিট বেক করুন, একবার উল্টে। কম মচমচে, তবে হালকা।"],"serving":"প্রতিজনকে 2টি সমোসা, সবুজ চাটনি, তেঁতুলের চাটনি, কাটা পেঁয়াজ ও গরম চা দিয়ে 6 জনের জন্য যথেষ্ট। প্লেটে পরিবেশন করুন, পুর দেখাতে একটা কেটে দিন, আর পাশে বাড়তি চাটনি রাখুন। সমোসা সবচেয়ে ভালো গরম, ভাজার 30 মিনিটের মধ্যে, পেস্ট্রি এখনও মচমচে থাকতে। উপরে ছড়ানো একটু চাট মসলা টক একটা শেষ দেয়।","storage":"সেরা মচমচে ভাবের জন্য টাটকা খান। ঠান্ডা, ভাজা সমোসা ফ্রিজে 2 দিন পর্যন্ত থাকে আর আবার মচমচে হওয়া পর্যন্ত 180C ওভেনে 8 থেকে 10 মিনিট গরম করা যায়। মাইক্রোওয়েভ করবেন না, কারণ পেস্ট্রি নরম হয়ে যায়। রান্না না করা, আকৃতি দেওয়া সমোসা ট্রেতে ফ্রিজ করুন, তারপর 1 মাস পর্যন্ত ব্যাগে রাখুন, আর জমাট অবস্থা থেকে কম আঁচে ভাজুন, 3 থেকে 4 মিনিট যোগ করে।","mistakes":["নরম ময়দা মাখা। সহজে বেলা যায়, তবে নরম ও তেলতেলে ভাজা হয়।","গরম, ভেজা পুর দিয়ে ভরা। বন্ধটা খুলে যায় আর পুর তেলে বেরিয়ে যায়।","বেশি আঁচে ভাজা। বাইরেটা দ্রুত বাদামি হয় আর ভেতরের পেস্ট্রি আটার মতো থাকে।","শঙ্কু বেশি ভরা। তেলে ফেটে যায়, তাই শুধু চার ভাগের তিন ভাগ ভরুন।"],"faq":[["আমার সমোসার পেস্ট্রি মচমচে নয়, নরম কেন?","ময়দা খুব নরম ছিল, বা ভাজার আঁচ খুব বেশি ছিল। শক্ত করে মাখুন, ময়দা রেখে দিন, আর কম আঁচে ধীরে ভাজুন।"],["এয়ার ফ্রায়ারে কি সমোসা বানানো যায়?","হ্যাঁ। তেল মাখিয়ে 180C তাপে 12 থেকে 15 মিনিট এয়ার ফ্রাই করুন, একবার উল্টে। খোলস মচমচে হয়, যদিও ডুবিয়ে ভাজার চেয়ে একটু শুকনো।"],["ভাজার সময় সমোসা খুলে যাওয়া কীভাবে আটকাব?","জল দিয়ে বন্ধ করুন আর শক্ত করে চাপ দিন, আর আকৃতি দেওয়া সমোসা ভাজার আগে 10 মিনিট রেখে দিন, যাতে বন্ধটা বসে যায়।"],["তৈরি পেস্ট্রি ব্যবহার করা যাবে?","ঠেকায় স্প্রিং রোলের শিট ব্যবহার করা যায়, তবে স্বাদ ও গঠন আলাদা। ক্লাসিক মচমচে ভাব আসে এই রেসিপির শক্ত ময়দার মণ্ড থেকে।"]]},"bunkebab":{"intro":"বান কাবাব হলো করাচির স্ট্রিট ফুড, যার অনেক অনুগামী রয়েছে: নরম বান, ভাজা শামি কাবাব, কাটা পেঁয়াজ ও টমেটো, আর চাটনি যা প্রতিটি কামড়ে ঝাল, টক ও টাটকা ভাব আনে। এটা বাড়িতে 25 মিনিটে বানানো ফাস্ট ফুড, যদি শামি কাবাব তৈরি থাকে, আর সবচেয়ে ভালো খাওয়া হয় গরম, সরাসরি তাওয়া থেকে, বান হালকা সেঁকা আর তবু নরম অবস্থায়। ভারসাম্যটাই যেকোনো একক উপকরণের চেয়ে বেশি গুরুত্বপূর্ণ। বেশি চাটনি কাবাব ডুবিয়ে দেয়, কম চাটনি বান শুকনো রেখে দেয়, আর ভালো সেঁকা বান হাতে ভেঙে না পড়ে সবকিছু একসঙ্গে ধরে রাখে।","ing":["শামি কাবাব 8টি","বান 4টি","পেঁয়াজ","টমেটো","সবুজ চাটনি","তেঁতুলের চাটনি","দই","কাঁচা লঙ্কা","টাটকা ধনেপাতা","বান সেঁকার জন্য মাখন"],"steps":["পেঁয়াজ পাতলা গোল করে কাটুন, টমেটো কাটুন, আর চাটনি, লঙ্কা ও ধনেপাতা ছোট বাটিতে তৈরি রাখুন।","তাওয়ায় মাঝারি আঁচে অল্প তেল গরম করুন। শামি কাবাব প্রতি পাশ 2 থেকে 3 মিনিট ভাজুন, পুরোপুরি গরম হয়ে কিনারাগুলো হালকা মচমচে হওয়া পর্যন্ত।","কাবাব তুলে নিন আর গরম রাখুন। তাওয়া হালকা মুছে নিন, মাখন দিন, আর বানের কাটা পাশগুলো প্রায় 1 মিনিট হালকা সোনালি হওয়া পর্যন্ত সেঁকে নিন।","নিচের বানে সবুজ চাটনি আর উপরের বানে তেঁতুলের চাটনি মাখান। পাতলা স্তরই যথেষ্ট, কাবাবই প্রধান থাকা উচিত।","প্রতিটি নিচের বানে 2টি কাবাব রাখুন। কাবাব ছোট হলে একটু ওভারল্যাপ করুন যাতে প্রতিটি কামড়ে কাবাব থাকে।","পেঁয়াজের গোলা, টমেটোর ফালি, কাঁচা লঙ্কা ও ধনেপাতা দিন। ঠান্ডা, ক্রিমের মতো কামড় পছন্দ হলে এক চামচ ফেটানো দই দিন।","বান বন্ধ করুন আর আলতো করে চাপ দিন। চাটনি শুধু কিনারা পর্যন্ত পৌঁছানো উচিত, বেরিয়ে পড়া উচিত নয়।","সঙ্গে সঙ্গে গরম পরিবেশন করুন, পাশে বাড়তি চাটনি ও ঠান্ডা পানীয় দিয়ে। করাচি ধাঁচে দুই হাতে খান।"],"tip":"বান বেশি সেঁকবেন না। হালকা সোনালিই যথেষ্ট, নইলে শক্ত ও ঝুরঝুরে হয়ে যাবে, আর কাবাব ভেতরে ঠিকমতো বসার বদলে বেরিয়ে যাবে।","notes":["শামি কাবাব ভেতরে নরম ও বাইরে হালকা মচমচে হওয়া উচিত। খুব নরম হলে ভাজার আগে 15 মিনিট ঠান্ডা করুন, যাতে আকৃতি ধরে রাখে।","নরম বার্গার বান ব্যবহার করুন, শক্ত রোল নয়। বান কাবাবের চারপাশে আলতো করে চেপে বসা উচিত, তার সঙ্গে লড়াই করা উচিত নয়।","তেঁতুলের চাটনি মিষ্টি টক সুর দেয়। আগে স্বাদ দেখে নিন, কারণ কিছু খুব মিষ্টি হয় আর কম লাগে।","পেঁয়াজের গোলা পরিবেশনের ঠিক আগে কাটলে মচমচে থাকে। কেটে রাখা পেঁয়াজ নরম ও তীক্ষ্ণ হয়ে যায়।"],"variations":["মুরগির বান কাবাব: মুরগির শামি কাবাব ব্যবহার করুন আর একটু বাড়তি সবুজ চাটনি দিন, কারণ মুরগি গরুর চেয়ে মৃদু।","ডিমের বান কাবাব: কাবাবের উপর একটা ভাজা ডিম দিন, কুসুম সবে জমাট অবস্থায়, আরও সমৃদ্ধ স্ট্রিট ধাঁচের সংস্করণের জন্য।","ঝাল বান কাবাব: কাটা কাঁচা লঙ্কা ও এক চামচ লঙ্কা রসুন সস দিন, আর দই বাদ দিন।"],"serving":"প্রতিজনকে 1টি বান কাবাব, বাড়তি চাটনি, আর পাশে সাধারণ সালাদ বা ফ্রেঞ্চ ফ্রাই দিয়ে 4 জনের জন্য যথেষ্ট। বান কাবাব স্ট্রিট ফুড, তাই কাগজে মুড়ে বা প্লেটে, তাওয়া থেকে গরম পরিবেশন করুন, আর সঙ্গে সঙ্গে খান। ঠান্ডা লস্যি, ফিজি পানীয়, বা চায়ের সঙ্গে ভালো যায়। বড় ভিড়ের জন্য বান, কাবাব ও চাটনি সাজিয়ে রাখুন আর লোকদের নিজেরটা নিজে বানাতে দিন।","storage":"বান কাবাব টাটকা খাওয়াই সেরা আর একবার সাজানোর পর ভালো থাকে না, কারণ বান চাটনি শুষে নেয়। অংশগুলো আলাদা রাখুন। রান্না করা শামি কাবাব ফ্রিজে 2 দিন পর্যন্ত থাকে আর তাওয়ায় গরম করা যায়। চাটনি বন্ধ জারে ফ্রিজে 4 দিন পর্যন্ত থাকে। পরিবেশনের ঠিক আগে সেঁকে ও সাজিয়ে নিন, যাতে বান নরম ও কাবাব গরম থাকে।","mistakes":["বান বেশি সেঁকা। শক্ত হয়ে যায়, ফেটে যায়, আর পুর বেরিয়ে পড়ে।","কাবাব চাটনিতে ডুবিয়ে দেওয়া। ভারসাম্য হারিয়ে যায় আর বান কয়েক মিনিটে ভিজে যায়।","খুব বেশি আঁচে কাবাব ভাজা। বাইরেটা পুড়ে যায় আর ভেতরটা ঠান্ডা থাকে।","বেশি আগে সাজানো। বান আর্দ্রতা শুষে নেয় আর মচমচে কিনারাগুলো খাওয়ার আগেই নরম হয়ে যায়।"],"faq":[["শামি কাবাব কী?","কিমা ও ডাল দিয়ে বানানো নরম কাবাব, রান্না করে, পিষে ও আকৃতি দিয়ে, তারপর ভাজা। এটা বানে চেপে বসার মতো নরম, শক্ত সিক কাবাবের মতো নয়।"],["জমাট শামি কাবাব ব্যবহার করা যাবে?","হ্যাঁ। মাঝারি আঁচে জমাট অবস্থা থেকে সরাসরি ভাজুন, পুরোপুরি গরম হওয়া পর্যন্ত প্রতি পাশে 1 থেকে 2 মিনিট বাড়তি দিয়ে। আগে গলাবেন না, কারণ নরম কাবাব ভেঙে যায়।"],["কোন বান সবচেয়ে ভালো?","নরম, সাধারণ বার্গার বান। তিলের বানও চলে। শক্ত রোল এড়িয়ে চলুন, কারণ সেগুলো ফেটে যায় আর পুর বেরিয়ে পড়ে।"],["তেঁতুলের চাটনি ছাড়া কি বানানো যায়?","হ্যাঁ। টকের জন্য বাড়তি সবুজ চাটনি ও এক চিমটি লেবু ব্যবহার করুন। স্বাদ আলাদা, তবে তবু ভালো হয়।"]]},"gulabjamun":{"intro":"গুলাব জামুন সেই মিষ্টি যা বেশিরভাগ উৎসব শেষ করে, নরম, গরম, আর গোলাপের গন্ধযুক্ত সিরাপে ভেজানো যতক্ষণ না সেটা ভারী হয়ে যায়। গোপন কথা লম্বা উপকরণের তালিকা নয়। এটা টাটকা ও নরম খোয়া, আলতো করে সামলানো ময়দা, কম আঁচে ভাজা যাতে জামুন বেশি দ্রুত কালো না হয়ে ভেতর পর্যন্ত রান্না হয়, আর সিরাপ যা গরম, ফুটন্ত নয়, যখন সেগুলো যায়। যেকোনো অংশে তাড়াহুড়ো করলে জামুন শক্ত, ফাটা, বা ভেতরে শুকনো হয়ে যায়। সময় নিন, আর সেগুলো ফুলে ওঠে, নরম হয়, আর চকচক করে। গরম পরিবেশন করুন, উপরে সিরাপ ঢেলে, আর দেখুন কীভাবে শেষ হয়ে যায়।","ing":["খোয়া 250 গ্রাম","ময়দা 3 টেবিল চামচ","এলাচ গুঁড়ো 1/2 চা চামচ","চিনি 2 কাপ","জল 2 কাপ","গোলাপ জল 1 চা চামচ","লেবুর 2 ফোঁটা","ভাজার জন্য তেল / ঘি"],"steps":["খোয়া ভেঙে নিন আর ময়দা ও এলাচ দিয়ে মেখে নিন যতক্ষণ না নরম, মসৃণ ময়দা হয়। বেশি মাখবেন না, নইলে জামুন ঘন হয়ে যায়।","ময়দা ঢেকে 15 মিনিট রেখে দিন। ফাটা ছাড়া গোল করার মতো নরম হওয়া উচিত।","চিনি, জল ও লেবুর রস গরম করে সিরাপ বানান যতক্ষণ না চিনি গলে যায়। 5 মিনিট ফোটান, এলাচ ও গোলাপ জল দিন, আর ফুটন্ত নয়, গরম রাখুন।","হাতের তালু ঘি দিয়ে হালকা মাখিয়ে নিন। ছোট, মসৃণ বল গোল করুন, আখরোটের আকারের মতো, পৃষ্ঠে কোনো ফাটা ছাড়া।","তেল বা ঘি কম থেকে মাঝারি কম আঁচে গরম করুন। তেল আলতো চিড়বিড় করার মতো গরম হওয়া উচিত, সঙ্গে সঙ্গে বাদামি হওয়ার মতো গরম নয়।","জামুন ব্যাচে দিন, চামচ দিয়ে আলতো নেড়ে যাতে সেগুলো গড়িয়ে সমানভাবে বাদামি হয়, হালকা সোনালি হওয়া পর্যন্ত 6 থেকে 8 মিনিট।","জামুন তুলে সরাসরি গরম সিরাপে রাখুন। সেগুলো আলতো চিড়বিড় করবে আর ফুলতে শুরু করবে।","অন্তত 1 ঘণ্টা রেখে দিন, একবার উল্টে, যাতে জামুন সমানভাবে সিরাপ শুষে নেয়। গরম পরিবেশন করুন, উপরে সিরাপ ঢেলে।"],"tip":"জামুনে কোনো ফাটা থাকা উচিত নয়। বল আকৃতি দেওয়ার সময় হাত ঘি দিয়ে হালকা মাখিয়ে নিন। সিরাপ খুব গরম হওয়া উচিত নয়, নইলে জামুন ভেজার বদলে শক্ত হয়ে যাবে, আর ঠান্ডা হওয়া উচিত নয়, নইলে সেটা শুষবে না।","notes":["টাটকা, নরম খোয়ায় নরম জামুন হয়। শুকনো, ঝুরঝুরে খোয়ায় ময়দা একত্র করতে এক চামচ দুধ লাগে।","ময়দা শুধু বাঁধাইয়ের জন্য। বেশি ময়দায় শক্ত জামুন হয়, তাই মেপে দিন আর আঠালো ময়দা ঠিক করতে বাড়তি দেবেন না, তার বদলে রেখে দিন।","সিরাপে লেবুর রস ঠান্ডা হলে স্ফটিক হতে বাধা দেয়, তাই সিরাপ পরিষ্কার ও মসৃণ থাকে।","গোলাপ জল আঁচ থেকে নামিয়ে দেওয়া হয়, যাতে এর গন্ধ ফুটে যাওয়ার বদলে উজ্জ্বল থাকে।"],"variations":["কেশর জামুন: এক চিমটি জাফরান গরম দুধে ভিজিয়ে নিন, সিরাপে দিন, আর পেস্তা দিয়ে সাজান।","ভরা জামুন: ভাজার আগে প্রতিটি বলের মাঝখানে ছোট এক টুকরো শুকনো ফল ও বাদামের মিশ্রণ চেপে দিন।","আইসক্রিমসহ জামুন: ভ্যানিলা আইসক্রিমের উপর গরম জামুন পরিবেশন করুন, উপরে গরম সিরাপ ঢেলে, গরম ও ঠান্ডা ডেজার্টের জন্য।"],"serving":"ছোট বাটিতে প্রতিজনকে 3 থেকে 4টি জামুন, প্রচুর সিরাপ দিয়ে 6 জনের জন্য যথেষ্ট। গরম পরিবেশন করুন, পছন্দ হলে কাটা পেস্তা দিয়ে সাজান, আর দ্বিতীয়বারের জন্য বাড়তি সিরাপ জগে রাখুন। গুলাব জামুন ঈদ, বিয়ে ও ডিনার পার্টির উপযুক্ত, আর সবচেয়ে ভালো চামচ দিয়ে, সরাসরি বাটি থেকে খাওয়া হয়। এর পর এক কাপ চা ক্লাসিক শেষ।","storage":"সিরাপের মধ্যে ঢাকা পাত্রে ফ্রিজে 4 দিন পর্যন্ত রাখুন। সিরাপের মধ্যে কম আঁচে আলতো করে গরম করুন, বা মাইক্রোওয়েভে 20 থেকে 30 সেকেন্ড, গরম হওয়া পর্যন্ত, খুব গরম নয়। সিরাপে ফোটাবেন না, কারণ সেগুলো ভেঙে যায়। সিরাপ ছাড়া 1 মাস পর্যন্ত ফ্রিজ করুন, ফ্রিজে গলিয়ে নিন, আর পরিবেশনের আগে টাটকা সিরাপে গরম করুন।","mistakes":["বেশি আঁচে ভাজা। বাইরেটা দ্রুত কালো হয় আর ভেতরটা কাঁচা ও ঘন থাকে।","ফাটাসহ বল আকৃতি দেওয়া। সিরাপ অসমানভাবে ঢোকে আর জামুন ভেঙে যায় বা অমসৃণ হয়।","ফুটন্ত সিরাপে জামুন দেওয়া। পৃষ্ঠ বন্ধ হয়ে যায় আর ভেতরে শক্ত থাকে।","ময়দা বেশি মাখা। শক্ত হয়ে যায় আর জামুন নরম ভাব হারায়।"],"faq":[["আমার গুলাব জামুন শক্ত কেন?","ময়দা বেশি মাখা হয়েছিল, বেশি ময়দা ব্যবহার করা হয়েছিল, বা সিরাপ খুব গরম ছিল। আলতো করে মাখুন, ময়দা মেপে দিন, আর সিরাপ ফুটন্ত নয়, গরম রাখুন।"],["খোয়ার বদলে কি দুধের গুঁড়ো ব্যবহার করা যায়?","হ্যাঁ। 1 কাপ দুধের গুঁড়ো 2 টেবিল চামচ ঘি ও 3 থেকে 4 টেবিল চামচ গরম দুধের সঙ্গে নরম ময়দা বানিয়ে মেশান, তারপর একই ধাপ অনুসরণ করুন। গঠন কাছাকাছি, যদিও খোয়া নরম।"],["আমার জামুন সিরাপে ভেঙে গেল কেন?","খুব কম ভাজা হয়েছিল, ময়দা খুব নরম ছিল, বা সিরাপ ফুটছিল। হালকা সোনালি ও শক্ত হওয়া পর্যন্ত ভাজুন, আর সিরাপ গরম রাখুন।"],["সিরাপ কি কম মিষ্টি করা যায়?","চিনি 1½ কাপে কমানো যায়, তবে সিরাপকে তবু জামুন ঢেকে রাখতে হবে। খুব পাতলা সিরাপ একইভাবে ভেজে না, তাই এর চেয়ে বেশি কমাবেন না।"]]},"gajarhalwa":{"intro":"গাজর কা হালুয়া হলো বাটিতে শীতকাল, লাল গাজর দুধে ধীরে রান্না করা যতক্ষণ না দুধ শেষ হয়, তারপর ঘিয়ে চিনি দিয়ে ভাজা আর খোয়া, এলাচ ও বাদাম দিয়ে শেষ করা। এটা দ্রুত ডেজার্ট নয়, আর সেটাই আসল কথা। লম্বা, নরম রান্না কাটা গাজরকে নরম, সমৃদ্ধ ও গভীর স্বাদের কিছুতে বদলে দেয়, কোনো শর্টকাটে একই স্বাদ আসে না। পেলে লাল গাজর ব্যবহার করুন, মিহি করে কাটুন, আর আঁচ কম রাখুন। গরম পরিবেশন করুন, উপরে এক চামচ খোয়া দিন, আর পরের দিনের জন্য কিছু রেখে দিন, কারণ তখন আরও ভালো লাগে।","ing":["লাল গাজর 1 কেজি (কাটা)","দুধ 1 লিটার","চিনি 1 কাপ","ঘি 4 টেবিল চামচ","খোয়া 150 গ্রাম","এলাচ 4টি","বাদাম / পেস্তা"],"steps":["গাজর ধুয়ে, খোসা ছাড়িয়ে মিহি করে কাটুন। মিহি করে কাটা জরুরি, কারণ মোটা ফালি বেশি সময় নেয় আর মোটা থাকে।","গাজর ও দুধ ভারী কড়াইয়ে রাখুন। ফুটতে দিন, তারপর কম আঁচে নামিয়ে দিন।","দুধ প্রায় শুকিয়ে যাওয়া পর্যন্ত ঢাকা ছাড়া কম আঁচে 35 থেকে 45 মিনিট রান্না করুন, কয়েক মিনিট পর পর নেড়ে।","ঘি দিন আর গাজর নেড়ে 8 থেকে 10 মিনিট ভাজুন, মিশ্রণ চকচকে হয়ে পাশ ছেড়ে যাওয়া পর্যন্ত।","চিনি দিন আর চিনি গলে হালুয়া আবার ঘন হওয়া পর্যন্ত নেড়ে আরও 8 থেকে 10 মিনিট রান্না করুন।","এলাচ থেঁতো করুন আর খোয়ার সঙ্গে দিন। খোয়া হালুয়ায় গলে যাওয়া পর্যন্ত নেড়ে 5 মিনিট রান্না করুন।","স্বাদ দেখে ঠিক করুন। বেশি মিষ্টি হলে এক চিমটি লেবু ঐতিহ্যবাহী নয়, তাই তার বদলে মিষ্টিহীন চায়ের সঙ্গে ছোট ভাগ পরিবেশন করুন।","গরম পরিবেশন করুন, উপরে কাটা বাদাম ও পেস্তা আর একটু বাড়তি খোয়া দিয়ে।"],"tip":"গাজর মিহি করে কাটুন। মোটা গাজর রান্না হতে বেশি সময় নেয় আর যতক্ষণ নাড়ুন না কেন হালুয়া মোটা থাকে, তাই শুরুতে ভালো করে কাটার জন্য সময় নিন।","notes":["লাল গাজর বেশি মিষ্টি আর গাঢ় রং দেয়। কমলা গাজরও চলে, তবে হালুয়া ফ্যাকাসে হয় আর একটু বেশি চিনি লাগে।","পুরো চর্বির দুধে আরও সমৃদ্ধ ফল হয়। কম চর্বির দুধ কমতে বেশি সময় নেয় আর পাতলা স্বাদ দেয়।","শেষে খোয়া সমৃদ্ধি ও শরীর দেয়। ভালো খোয়া কেনা উচিত, বা ঠেকায় বদলি হিসেবে পনির ভেঙে দেওয়া যায়।","এলাচ টাটকা থেঁতো করা উচিত। আগে গুঁড়ো করা এলাচ দ্রুত সুগন্ধ হারায়।"],"variations":["দুধের গুঁড়োর হালুয়া: দ্রুত, আরও সমৃদ্ধ সংস্করণের জন্য অর্ধেক দুধের বদলে গাজরে মেশানো 1 কাপ দুধের গুঁড়ো ব্যবহার করুন।","বাদামের হালুয়া: খোয়ার সঙ্গে কাটা কাজু ও কিশমিশ দিন, আর বাদাম আগে ঘিয়ে ভেজে নিন।","কম মিষ্টি হালুয়া: চিনি 3/4 কাপে কমিয়ে দিন। হালুয়া গাজর থেকে তবু মিষ্টি থাকে, আর আইসক্রিম দিয়ে পরিবেশনের উপযুক্ত।"],"serving":"ছোট বাটিতে, গরম, উপরে কাটা বাদাম ও এক চামচ খোয়া দিয়ে 5 জনের জন্য যথেষ্ট। গাজর কা হালুয়া শীতের ডেজার্ট, রাতের খাবারের পর বা বিকেলের চায়ের সঙ্গে পরিবেশন করা হয়। গরম হালুয়ার উপর এক স্কুপ ভ্যানিলা আইসক্রিম জনপ্রিয় আধুনিক পরিবেশন, আর গরম ও ঠান্ডার বৈপরীত্য সুন্দরভাবে কাজ করে। ভাগ ছোট রাখুন, কারণ এটা সমৃদ্ধ।","storage":"ঠান্ডা করুন আর বায়ুরোধী পাত্রে ফ্রিজে 4 দিন পর্যন্ত রাখুন। প্যানে কম আঁচে একটু দুধ দিয়ে নেড়ে, পুরোপুরি গরম হওয়া পর্যন্ত গরম করুন। মাইক্রোওয়েভেও অল্প অল্প করে ভালো গরম হয়। ভাগে ভাগে 1 মাস পর্যন্ত ফ্রিজ করুন, ফ্রিজে গলিয়ে নিন, আর একটু দুধ দিয়ে গরম করুন। পরিবেশনের সময় টাটকা বাদাম দিন, কারণ রাখা বাদাম নরম হয়ে যায়।","mistakes":["বেশি আঁচে রান্না করা। দুধ ধরে যায় আর পুড়ে যায়, আর হালুয়ায় পোড়া স্বাদ আসে।","চিনি খুব তাড়াতাড়ি দেওয়া। জল বেরিয়ে আসে আর গাজর কমার বদলে সেদ্ধ হয়, তাই দুধ শুকানোর পর দিন।","মোটা করে কাটা। হালুয়া যতক্ষণ রান্না হোক সুতোর মতো ও মোটা থাকে।","ঘিয়ে ভাজার ধাপ বাদ দেওয়া। সেটা ছাড়া হালুয়া সমৃদ্ধ ও চকচকে নয়, সেদ্ধ স্বাদের হয়।"],"faq":[["কমলা গাজর ব্যবহার করা যাবে?","হ্যাঁ। হালুয়া ফ্যাকাসে ও একটু কম মিষ্টি হয়, তাই স্বাদ দেখে দরকার হলে 1 থেকে 2 টেবিল চামচ বাড়তি চিনি দিন। লাল গাজর শীতের হালুয়ার জন্য ঐতিহ্যবাহী।"],["দুধ যথেষ্ট কমেছে বুঝব কীভাবে?","মিশ্রণ শুকনো দেখায়, গাজর একসঙ্গে থাকে, আর নাড়ার সময় কিনারায় ঘি আলাদা হতে শুরু করেছে দেখা যায়। তখনই ঘি দিয়ে ভাজার সময়।"],["খোয়া ছাড়া কি বানানো যায়?","হ্যাঁ। তবু ভালো হয়, শুধু কম সমৃদ্ধ। শেষে 2 টেবিল চামচ বাড়তি ঘি ও 2 টেবিল চামচ দুধের গুঁড়ো দিন, বা নরম পনির ভেঙে দিন।"],["গাজর কা হালুয়া কি গরম না ঠান্ডা পরিবেশন করা হয়?","গরমই সেরা, সরাসরি কড়াই থেকে বা আলতো করে গরম করে। ফ্রিজের ঠান্ডা হালুয়া শক্ত ও কম সুগন্ধি, তাই পরিবেশনের আগে গরম করুন।"]]},"lassi":{"intro":"আমের লস্যি হলো গ্লাসে গ্রীষ্ম, পাকা আম ঠান্ডা দই, একটু দুধ, আর এলাচ দিয়ে মেশানো যতক্ষণ না ঘন, মসৃণ ও ঠান্ডা হয়ে আপনাকে ঠান্ডা করে দেয়। 15 মিনিট লাগে, তার বেশিরভাগটাই আমের খোসা ছাড়ানো, আর কোনো রান্নাই লাগে না। আমের মানই সব ঠিক করে, তাই এমন ফল বেছে নিন যার বোঁটায় মিষ্টি গন্ধ আসে, চাপ দিলে একটু বসে যায়, আর সবুজ, শক্ত দাগ নেই। সঙ্গে সঙ্গে, ঠান্ডা গ্লাসে, উপরে একটু কাটা আম দিয়ে পরিবেশন করুন, আর ব্লেন্ডারের ফেনা এখনও উপরে থাকতে পান করুন।","ing":["পাকা আম 2টি","দই 1½ কাপ","দুধ 1/2 কাপ","চিনি 2 টেবিল চামচ (স্বাদমতো)","এলাচ গুঁড়ো 1/4 চা চামচ","বরফের টুকরো","সাজানোর জন্য পুদিনা"],"steps":["গ্লাস ফ্রিজে 15 মিনিট ঠান্ডা করুন, যাতে পান করার সময় লস্যি ঠান্ডা থাকে।","আমের খোসা ছাড়ান, শাঁস আঁটি থেকে কেটে নিন, আর মোটামুটি কেটে নিন। এক টুকরোর স্বাদ দেখুন আর কতটা চিনি লাগবে ঠিক করুন।","আম, দই, দুধ, চিনি ও এলাচ ব্লেন্ডারে রাখুন। এখনও বরফ দেবেন না।","30 সেকেন্ড মেশান, থামুন, পাশগুলো চেঁছে নিন, আর পুরোপুরি মসৃণ হওয়া পর্যন্ত আরও 30 সেকেন্ড মেশান।","এক মুঠো বরফের টুকরো দিন আর আরও 15 থেকে 20 সেকেন্ড মেশান, শুধু বরফ ভেঙে লস্যি ঘন ও ঠান্ডা হওয়া পর্যন্ত।","স্বাদ দেখে ঠিক করুন। আম টক হলে একটু বাড়তি চিনি দিন, বা ঢালার মতো পাতলা না হলে একটু দুধ দিন।","সঙ্গে সঙ্গে ঠান্ডা গ্লাসে ঢালুন, ফেনা উপরে রেখে।","কাটা আম ও পুদিনা পাতা দিয়ে সাজান, আর স্ট্র বা চামচ দিয়ে সঙ্গে সঙ্গে পরিবেশন করুন।"],"tip":"আম যত মিষ্টি, চিনি তত কম লাগে। লস্যি আগে বানাবেন না। টাটকা মেশানোই সেরা, কারণ বসে থাকলে সেটা আলাদা হয়ে যায় আর ফেনা হারায়, আর বরফ গলে পাতলা করে দেয়।","notes":["ঋতুতে সিন্ধ্রি, চৌসা বা আলফানসোর মতো পাকা, মিষ্টি আম ব্যবহার করুন। আঁশযুক্ত আম সুতোর মতো লস্যি বানায়, তাই দরকার হলে ছেঁকে নিন।","পুরো চর্বির দই ঘন, ক্রিমের মতো লস্যি দেয়। কম চর্বির দইও চলে, তবে লস্যি পাতলা হয় আর কম দুধ লাগে।","এলাচ পেছনের সুর হওয়া উচিত, প্রধান স্বাদ নয়। 3 গ্লাসের জন্য এক চতুর্থাংশ চা চামচ যথেষ্ট।","আগে সবকিছু ঠান্ডা করুন। ঠান্ডা আম, ঠান্ডা দই ও ঠান্ডা দুধ মানে কম বরফ লাগে, আর স্বাদ জোরালো থাকে।"],"variations":["আম কলার লস্যি: ঘন, মিষ্টি লস্যির জন্য 1টি পাকা কলা দিন যা বাচ্চাদের উপযুক্ত।","আম গোলাপ লস্যি: 1 চা চামচ গোলাপ জল ও এক চিমটি জাফরান দিন, আর গোলাপের পাপড়ি দিয়ে সাজান।","ভেগান লস্যি: নারকেলের দই ও ওটের দুধ ব্যবহার করুন, আর স্বাদমতো ম্যাপেল সিরাপ বা চিনি দিয়ে মিষ্টি করুন।"],"serving":"লম্বা ঠান্ডা গ্লাসে, উপরে কাটা আম ও পুদিনা দিয়ে 3 জনের জন্য যথেষ্ট। আমের লস্যি গরম বিকেল, ঝাল খাবার, আর গ্রীষ্মের সপ্তাহান্তের সকালের খাবারের উপযুক্ত। পরোটা ও আচারের সঙ্গে পানীয় হিসেবে, বা ঝাল ঝোলের পর হালকা ডেজার্ট হিসেবে পরিবেশন করুন। ঢালার মুহূর্ত পর্যন্ত ঠান্ডা রাখুন, আর টাটকা পান করুন।","storage":"সেরা গঠনের জন্য টাটকা পান করুন। লস্যি বন্ধ জারে ফ্রিজে 1 দিন পর্যন্ত থাকে, তবে আলাদা হয়ে যায়, তাই পরিবেশনের আগে ভালো করে নাড়ুন বা ঝাঁকান, আর ফেনা ফিরে আসার আশা করবেন না। লস্যি ফ্রিজ করবেন না, কারণ দই গলার পর দানাদার হয়। আগে বানাতেই হলে বরফ ছাড়া আম ও দই মেশান, ফ্রিজে রাখুন, আর পরিবেশনের ঠিক আগে বরফ দিয়ে আবার মেশান।","mistakes":["কাঁচা আম ব্যবহার করা। কোনো পরিমাণ চিনিই টক, শক্ত স্বাদ ঠিক করে না, তাই পাকা ফলের জন্য অপেক্ষা করুন।","বরফ দিয়ে বেশি মেশানো। লস্যি ঘন ও ক্রিমের মতো হওয়ার বদলে জলীয় ও পাতলা ফেনাযুক্ত হয়।","শুরুতে বেশি দুধ দেওয়া। বিচার করার আগেই লস্যি পাতলা করে দেয়, তাই দুধ অল্প অল্প করে দিন।","ঘণ্টাখানেক আগে বানানো। আলাদা হয়ে যায়, রং ম্লান হয়, আর টাটকা আমের স্বাদ মিলিয়ে যায়।"],"faq":[["জমাট আম ব্যবহার করা যাবে?","হ্যাঁ। অর্ধেক গলিয়ে নিন, যাতে মেশানোর মতো নরম কিন্তু তবু ঠান্ডা থাকে, আর বরফ অর্ধেক কমিয়ে দিন। জমাট আম খুব ঘন লস্যি বানায়, তাই দুধ অল্প অল্প করে দিন।"],["আমের লস্যি কি স্বাস্থ্যকর?","এটা ফল ও দই দিয়ে বানানো, আর এখানে কোনো সংখ্যা দেওয়া হয়নি। চিনিই দেখার অংশ, তাই পাকা আম ব্যবহার করুন আর ফলের যতটা দরকার তত কম চিনি দিন।"],["ব্লেন্ডার ছাড়া কি লস্যি বানানো যায়?","হ্যাঁ, আম খুব নরম হলে। আম কাঁটাচামচ দিয়ে চটকে নিন, দই ও দুধ ফেটিয়ে নিন, আর ছাঁকনি দিয়ে ছেঁকে নিন। কম মসৃণ, তবে তবু সুস্বাদু।"],["আমার লস্যি সুতোর মতো হলো কেন?","আম আঁশযুক্ত ছিল। বেশি সময় মেশান, বা পরিবেশনের আগে মিহি ছাঁকনি দিয়ে ছেঁকে নিন। পরের বার কম আঁশযুক্ত আমের জাত বেছে নিন।"]]},"pizza":{"intro":"মার্গারিটা পিৎজা প্রমাণ যে সাধারণ খাবার অসাধারণ হতে পারে। এটা নেপলসে বিখ্যাত হয়েছিল, যেখানে গরম ওভেন, পাতলা খোলস, উজ্জ্বল টমেটো সস ও ভালো মোজারেলা সব কাজ করে। বলা হয় রংগুলো ইতালির পতাকার প্রতিধ্বনি, লাল টমেটো, সাদা মোজারেলা ও সবুজ তুলসি, আর স্বাদ ভারী নয়, পরিষ্কার ও টাটকা। এই সংস্করণে এমন ময়দা ব্যবহার করা হয় যা হালকা ও চিবোনো হওয়ার মতো যথেষ্ট বিশ্রাম পায়, সস যা সবে রান্না করা হয়, আর খুব গরম ওভেন যাতে খোলস কয়েক মিনিটে ফোসকা পড়ে। ময়দা ও আঁচের সঙ্গে সময় নিন, আর পিৎজার স্বাদ বাড়ির ওভেন থেকেও পিৎজার দোকানের পিৎজার মতো হবে।","ing":["শক্ত রুটির ময়দা 500 গ্রাম","গরম জল 325 মিলি","ইনস্ট্যান্ট ইস্ট 7 গ্রাম","মিহি লবণ 10 গ্রাম","জলপাই তেল 2 টেবিল চামচ","সান মারজানো টমেটো 400 গ্রাম (থেঁতো করা)","ফিওর ডি লাত্তে মোজারেলা 250 গ্রাম (ছেঁড়া)","টাটকা তুলসি পাতা 1 মুঠো","রসুন 1 কোয়া","সসের জন্য জলপাই তেল","লবণ","ছিটানোর জন্য সুজি বা ময়দা"],"steps":["ময়দা, জল, ইস্ট ও লবণ মেশান, মসৃণ হওয়া পর্যন্ত 8 থেকে 10 মিনিট মাখুন, তারপর ময়দা ঢেকে 1 ঘণ্টা রেখে দিন, বা ভালো স্বাদের জন্য ফ্রিজে সারারাত রাখুন।","টমেটো রসুন, এক চিমটি লবণ ও 1 টেবিল চামচ জলপাই তেল দিয়ে থেঁতো করুন। সস রান্না করবেন না, এটা পিৎজার উপর রান্না হয়।","ময়দা 4টি বলে ভাগ করুন, 20 মিনিট রেখে দিন, তারপর প্রতিটা মাঝখান থেকে বাইরের দিকে হাত দিয়ে টেনে বড় করুন, মোটা কিনারা রেখে।","ওভেন যত গরম যায় তত গরম করুন, অন্তত 250C, ভেতরে 30 মিনিটের জন্য পিৎজার পাথর বা উল্টানো বেকিং ট্রে রেখে।","প্রতিটি বেসে কিনারা পরিষ্কার রেখে 3 থেকে 4 টেবিল চামচ সস ছড়িয়ে দিন, আর উপরে ছেঁড়া মোজারেলা ছড়িয়ে দিন।","খোলস ফোসকা পড়ে সোনালি হওয়া পর্যন্ত আর পনির টগবগ করা পর্যন্ত 6 থেকে 8 মিনিট বেক করুন।","পিৎজা বেরোনোর সঙ্গে সঙ্গে তুলসি পাতা দিন, যাতে পুড়ে না গিয়ে আলতো করে নেতিয়ে যায়।","একটু জলপাই তেল ছিটিয়ে দিন, কাটুন, আর খোলস মচমচে থাকতে সঙ্গে সঙ্গে পরিবেশন করুন।"],"tip":"পিৎজা বেশি ভরবেন না। সসের পাতলা স্তর ও পরিমিত পনির খোলসকে ভেতর পর্যন্ত রান্না হতে ও মচমচে থাকতে দেয়।","notes":["রুটির ময়দা সেই চিবোনো ভাব দেয় যা সাধারণ ময়দা দিতে পারে না, তাই পেলে ব্যবহার করুন, আর নির্ভরযোগ্য ময়দার জন্য ময়দা ওজন করুন।","ফিওর ডি লাত্তে হলো জলে বিক্রি হওয়া নরম মোজারেলা। ছেঁকে ছিঁড়ে নিন, আর মুছে শুকিয়ে নিন, যাতে পিৎজা ভেজা না হয়।","সান মারজানো টমেটো মিষ্টি ও কম অম্লযুক্ত। অন্য টিন ব্যবহার করলে ভালো করে থেঁতো করুন আর শুধু তীক্ষ্ণ স্বাদ হলে এক চিমটি চিনি দিন।","বেলচায় সুজি ময়দা আটকাতে বাধা দেয় আর একটু মচমচে ভাব যোগ করে। একা ময়দা বেশি আঁচে পুড়ে তেতো স্বাদ দিতে পারে।"],"variations":["মারিনারা: পনির বাদ দিন, বাড়তি রসুন ও ওরেগানো দিন, আর জলপাই তেল দিয়ে শেষ করুন, দুগ্ধমুক্ত পিৎজার জন্য।","চার পনির: টমেটো সসের বদলে জলপাই তেলের পাতলা স্তর ব্যবহার করুন, তারপর মোজারেলা, গর্গনজোলা, ফন্টিনা ও পারমেসান ব্যবহার করুন।","চেরি টমেটো দিয়ে: অর্ধেক করা চেরি টমেটো আগে জলপাই তেল দিয়ে ভেজে নিন, তারপর থেঁতো করা টমেটো সসের বদলে ব্যবহার করুন।"],"serving":"প্রতিজনকে একটি পিৎজা দিয়ে 4 জনের জন্য যথেষ্ট, বা সবুজ সালাদ দিয়ে ভাগ করে খাওয়ার জন্য ফালি করে কাটুন। ওভেন থেকে সরাসরি পরিবেশন করুন, টেবিলে বাড়তি তুলসি, লঙ্কার তেল বা পারমেসান দিয়ে, আর সবাইকে নিজেরটা দিতে দিন। পিৎজা প্রথম 10 মিনিটে সেরা, যখন বেস মচমচে আর পনির এখনও নরম ও টানা যায়।","storage":"বেঁচে যাওয়া ফালি বায়ুরোধী পাত্রে ফ্রিজে 2 দিন পর্যন্ত থাকে। গরম ওভেনে বা ঢাকা শুকনো ফ্রাইং প্যানে গরম করুন, যাতে বেস আবার মচমচে হয়। মাইক্রোওয়েভ এড়িয়ে চলুন, এটা খোলস নরম ও চিবোনো করে। কাঁচা ময়দা ফ্রিজে 3 দিন পর্যন্ত থাকে, আর 1 মাস পর্যন্ত ভালো ফ্রিজ হয়, ফ্রিজে সারারাত গলিয়ে নিন।","mistakes":["ঠান্ডা ওভেন ব্যবহার করা। খোলস ফোসকা পড়ার বদলে ভাপে সেদ্ধ হয়, তাই পাথর বা ট্রে পুরোপুরি আগে গরম করুন।","বেলন দিয়ে ময়দা বেলা। বাতাস বেরিয়ে যায়, তাই তার বদলে হাত দিয়ে টানুন।","বেশি সস বা পনির দেওয়া। মাঝখান ভেজা থাকে আর বেস কখনও মচমচে হয় না।","খুব বেশি আঁচে বেক করার আগে তুলসি দেওয়া। কালো হয়ে যায়, তাই বেক করার পর দিন।"],"faq":[["আমার পিৎজার বেস মাঝখানে ভেজা কেন?","ওভেন বা পাথর যথেষ্ট গরম ছিল না, বা বেশি সস ও পনির ছিল। পুরোপুরি আগে গরম করুন, কম টপিং ব্যবহার করুন, আর সবচেয়ে নিচের তাকে বেক করুন।"],["ময়দা কি আগে বানানো যায়?","হ্যাঁ। মাখার পর 3 দিন পর্যন্ত ফ্রিজে রাখুন। টানার আগে 30 থেকে 45 মিনিট ঘরের তাপমাত্রায় ফিরিয়ে আনুন।"],["পিৎজার পাথর কি দরকার?","না। ওভেনে আগে গরম করা উল্টানো ভারী বেকিং ট্রে ভালো কাজ করে। ঢালাই লোহার প্যানও মচমচে বেস দেয়।"],["শুকনো তুলসি ব্যবহার করা যাবে?","টাটকা তুলসি এখানে অনেক ভালো, কারণ এটাই প্রধান স্বাদ। সসে শুকনো তুলসি চলে, তবে শেষ করতে টাটকা পাতা দিন।"]]},"carbonara":{"intro":"আসল কার্বোনারায় ক্রিম থাকে না। এটা রোম থেকে এসেছে, আর এর সস বানানো হয় শুধু ডিম, পেকোরিনো পনির, কালো গোলমরিচ আর গুয়ানচালে বা প্যানচেত্তার চর্বি দিয়ে, গরম পাস্তার সঙ্গে মেশানো যতক্ষণ না চকচকে ও রেশমের মতো হয়। কৌশল হলো আঁচ নিয়ন্ত্রণ। প্যান যথেষ্ট গরম হতে হবে যাতে ডিম আলতো করে সসে রান্না হয়, তবে কখনও এত গরম নয় যে সেগুলো স্ক্র্যাম্বল হয়ে যায়। দ্রুত কাজ করুন, সস পাতলা করতে পাস্তার জল ব্যবহার করুন, আর সঙ্গে সঙ্গে পরিবেশন করুন। সময়টা শিখে গেলে এটা সবচেয়ে দ্রুত ও সবচেয়ে আরামদায়ক পাস্তার পদগুলোর একটা হয়ে যায়, মাত্র কয়েকটা উপকরণ আর স্বাদের গভীরতা যা দেখতে যতটা জটিল তার চেয়ে অনেক বেশি জটিল স্বাদ দেয়।","ing":["স্প্যাগেটি 400 গ্রাম","গুয়ানচালে বা প্যানচেত্তা 150 গ্রাম (কুচি করা)","ডিমের কুসুম 4টি","সঙ্গে 1টি গোটা ডিম","পেকোরিনো রোমানো 60 গ্রাম (মিহি করে কাটা)","কালো গোলমরিচ 2 চা চামচ (টাটকা ভাঙা)","পাস্তার জলের জন্য লবণ","পরিবেশনের জন্য বাড়তি পেকোরিনো","গোলমরিচ"],"steps":["ভালো করে লবণ দেওয়া জলে স্প্যাগেটি প্রায় আল ডেন্তে হওয়া পর্যন্ত সেদ্ধ করুন, আর ছাঁকার আগে 1 কাপ পাস্তার জল রেখে দিন।","গুয়ানচালে বা প্যানচেত্তা শুকনো প্যানে মাঝারি আঁচে 6 থেকে 8 মিনিট ভাজুন যতক্ষণ না কিনারাগুলো মচমচে হয় আর চর্বি গলে বেরোয়।","কুসুম, গোটা ডিম, পেকোরিনো ও বেশিরভাগ কালো গোলমরিচ ঘন বাটা বানিয়ে ফেটিয়ে নিন। বেশি শক্ত হলে এক চামচ পাস্তার জল দিন।","প্যান আঁচ থেকে নামিয়ে নিন আর 1 মিনিট ঠান্ডা হতে দিন, যাতে ডিম প্যানের সংস্পর্শে এলে স্ক্র্যাম্বল না হয়।","ছাঁকা স্প্যাগেটি প্যানে দিন আর গলা চর্বিতে 30 সেকেন্ড ভালো করে নাড়ুন।","ডিম ও পনিরের মিশ্রণ ঢেলে দিন আর দ্রুত ও অনবরত নাড়ুন, সস চকচকে হয়ে প্রতিটি সুতো ঢেকে ফেলা পর্যন্ত অল্প অল্প করে পাস্তার জল দিন।","স্বাদ দেখুন, আরও গোলমরিচ দিন, আর শুধু দরকার হলে লবণ দিন, কারণ পেকোরিনো ও প্যানচেত্তা ইতিমধ্যে নোনতা।","সঙ্গে সঙ্গে গরম বাটিতে পরিবেশন করুন, উপরে বাড়তি পেকোরিনো ও কালো গোলমরিচ দিয়ে।"],"tip":"ডিম দেওয়ার আগে প্যান আঁচ থেকে নামিয়ে নিন। অবশিষ্ট তাপ সস বানায়, সরাসরি তাপ স্ক্র্যাম্বল ডিম বানায়।","notes":["পেকোরিনো রোমানো তীক্ষ্ণ ও নোনতা, আর এটাই ঐতিহ্যবাহী পনির। পারমেসানও চলে, তবে মৃদু, তাই একটু বেশি ব্যবহার করুন আর লবণ দেওয়ার আগে স্বাদ দেখুন।","গুয়ানচালে হলো নিরাময় করা শূকরের গাল আর ক্লাসিক স্বাদ দেয়। প্যানচেত্তা সবচেয়ে কাছের সহজ বদলি, আর বেকনও গ্রহণযোগ্য, যদিও আরও ধোঁয়াটে।","পাস্তার জল স্টার্চে ভরা। এটা ডিমের সসকে পিছলে যাওয়ার বদলে স্প্যাগেটিতে লেগে থাকতে সাহায্য করে।","টাটকা ভাঙা কালো গোলমরিচ এখানে গুরুত্বপূর্ণ। এটা প্রধান স্বাদ, শুধু সাজানো নয়, তাই মোটা করে ভাঙুন আর প্রচুর ব্যবহার করুন।"],"variations":["মটর দিয়ে: রং ও মিষ্টির জন্য শেষ মিনিটে পাস্তার জলে এক মুঠো মটর দিন।","নিরামিষ ধাঁচে: শূকরের বদলে মাখন ও জলপাই তেলে ভাজা মাশরুম ব্যবহার করুন, আর একটু ধোঁয়াটে পাপরিকা দিন, যদিও ফলাফল অন্য পদ হয়।","হালকা সংস্করণ: 4টি কুসুমের বদলে 2টি গোটা ডিম ও 2টি কুসুম ব্যবহার করুন, আর একটু কম পনির, তবু রেশমের মতো সসের জন্য।"],"serving":"প্রধান পদ হিসেবে, গরম বাটিতে, পাশে সাধারণ সবুজ সালাদ ও শক্ত রুটি দিয়ে 4 জনের জন্য যথেষ্ট। কার্বোনারা এক বাটির খাবার, তাই পাশের পদ হালকা রাখুন আর পাস্তাকে প্রধান হতে দিন। নাড়ার মুহূর্তেই পরিবেশন করুন, কারণ সস ঠান্ডা হলে ঘন হয় আর রেশম ভাব হারায়।","storage":"কার্বোনারা টাটকা খাওয়াই সেরা আর ভালো করে গরম করা যায় না, কারণ ডিমের সস ঘন হয় আর আলাদা হয়ে যেতে পারে। রাখতেই হলে 1 দিন পর্যন্ত ফ্রিজে রাখুন আর একটু জল দিয়ে প্যানে খুব আলতো করে, অনবরত নেড়ে গরম করুন। ফ্রিজ করবেন না। একা রান্না করা পাস্তা 2 দিন থাকে, তবে সস টাটকা বানান।","mistakes":["ডিম এমন প্যানে দেওয়া যা এখনও আঁচে আছে। ডিম স্ক্র্যাম্বল হয়ে যায় আর সস ডেলাযুক্ত হয়।","ক্রিম ব্যবহার করা। এটা অন্য, ভারী সস বানায় আর পেকোরিনোর স্বাদ ঢেকে দেয়।","সব পাস্তার জল ছেঁকে ফেলা। সেটা ছাড়া সস খুব ঘন হয় আর পাস্তা ঢাকবে না।","স্বাদ দেখার আগে লবণ দেওয়া। পেকোরিনো ও নিরাময় করা শূকর নোনতা, তাই আগে স্বাদ দেখুন।"],"faq":[["গুয়ানচালের বদলে কি বেকন ব্যবহার করা যায়?","হ্যাঁ। মচমচে হওয়া পর্যন্ত ভাজুন, আর অনেক চর্বি থাকলে একটু ছেঁকে নিন। স্বাদ আরও ধোঁয়াটে, তবে পদ্ধতি একই।"],["আমার সস স্ক্র্যাম্বল হলো কেন?","প্যান খুব গরম ছিল। আঁচ থেকে নামিয়ে নিন, এক মিনিট ঠান্ডা করুন, আর পরের বার পাস্তার জল দিয়ে দ্রুত নাড়ুন।"],["শূকর ছাড়া কি কার্বোনারা বানানো যায়?","হ্যাঁ, মাশরুম বা মটর দিয়ে, তবে ক্লাসিক কার্বোনারার মতো স্বাদ হবে না। ডিম ও পেকোরিনোর সস একই রাখুন।"],["পাস্তার জলের পরিমাণ কীভাবে বুঝব?","অল্প দিয়ে শুরু করুন আর নাড়ার সঙ্গে সঙ্গে আরও দিন। সস চকচকে ও পাতলা দেখানো উচিত, ঘন ও আঠালো নয়।"]]},"sushi":{"intro":"সুশি প্রথমে ভাত, তারপর মাছ। জাপানে ভাত ভিনেগার, চিনি ও লবণ দিয়ে মসলা দেওয়া হয়, পাখা দিয়ে ঠান্ডা করা হয়, আর আলতো করে সামলানো হয় যাতে প্রতিটি দানা আলাদা ও চকচকে থাকে। এই বাড়িতে বানানো সংস্করণে স্যামন ও শসার রোল হয়, যা শেখা সবচেয়ে সহজ, নোরি বাইরে, ভাত মাঝখানে, আর ভরাটের পরিচ্ছন্ন লাইন। সুশি মানের স্যামন ব্যবহার করুন, হাত ভেজা রাখুন, আর শক্ত কিন্তু আলতো করে গোল করুন। প্রথম রোল অসম দেখাতে পারে, আর সেটা স্বাভাবিক। তৃতীয় রোলের মধ্যে আকৃতি, কাটা ও আত্মবিশ্বাস সব একত্র হয়, আর ফলাফল টাটকা, পরিষ্কার ও ফ্রিজে রাখা দোকানের সুশির চেয়ে অনেক ভালো স্বাদ দেয়।","ing":["সুশি ভাত 2 কাপ (রান্না না করা)","ভাতের ভিনেগার 4 টেবিল চামচ","চিনি 2 টেবিল চামচ","লবণ 1 চা চামচ","নোরির শিট 4টি","সুশি মানের স্যামন 300 গ্রাম (ফালি করে কাটা)","শসা 1টি (পাতলা কাঠি করে কাটা)","মেয়োনিজ 3 টেবিল চামচ","শ্রীরাচা 1 চা চামচ (ঝাল মেয়োর জন্য)","পরিবেশনের জন্য সয়া সস","আচারি আদা","ওয়াসাবি","তিলের বীজ 1 টেবিল চামচ (ঐচ্ছিক)"],"steps":["ভাত ধুয়ে নিন যতক্ষণ না জল পরিষ্কার আসে, রান্না করুন, তারপর ঢেকে 10 মিনিট রেখে দিন।","ভিনেগার, চিনি ও লবণ গরম করুন যতক্ষণ না গলে যায়, কাটার ভঙ্গিতে গরম ভাতে মিশিয়ে নিন, আর ভাত সবে গরম ও চকচকে হওয়া পর্যন্ত পাখা দিয়ে ঠান্ডা করুন।","বাঁশের মাদুরে চকচকে পাশ নিচে করে নোরির শিট রাখুন, হাত ভিজিয়ে নিন, আর দূরের কিনারায় 2 সেমি খালি রেখে ভাতের পাতলা সমান স্তর ছড়িয়ে দিন।","মাঝখান জুড়ে ঝাল মেয়োর পাতলা লাইন দিন, স্যামন ও শসার কাঠি পরিচ্ছন্ন সারিতে দিন, আর তিলের বীজ ছড়িয়ে দিন।","মাদুরের কাছের কিনারা তুলুন আর ভরাট ভেতরে গুঁজে নিজের থেকে দূরে শক্ত করে গোল করুন, আর খালি কিনারা একটু জল দিয়ে বন্ধ করতে আলতো চাপ দিন।","রোল 2 মিনিট রেখে দিন, তারপর ভেজা ধারালো ছুরি দিয়ে 8 টুকরো করুন, কাটার মাঝে ব্লেড মুছে নিন।","বাকি ভাত ও ভরাট দিয়ে আবার করুন, হাত পুরো সময় ভেজা রাখুন।","টুকরোগুলো কাটা পাশ উপরে করে সাজান, আর সয়া সস, আচারি আদা ও অল্প ওয়াসাবি দিয়ে পরিবেশন করুন।"],"tip":"কাছে এক বাটি জল রাখুন আর হাত ও ছুরি ঘন ঘন ভেজান। ভেজা হাত ভাত আটকাতে বাধা দেয়, আর ভেজা ব্লেড রোল চেপে না দিয়ে পরিষ্কারভাবে কাটে।","notes":["সুশি ভাত ছোট দানার ভাত। লম্বা দানার ভাত একইভাবে আটকায় না, তাই পরিচ্ছন্ন রোল চাইলে সেটা দিয়ে বদলাবেন না।","সুশি মান মানে কাঁচা খাওয়ার জন্য বিক্রি হওয়া মাছ, ধরা থেকে বিক্রি পর্যন্ত ঠান্ডা রাখা। আপনার মাছ বিক্রেতাকে জিজ্ঞাসা করুন, আর রান্নার জন্য নির্ধারিত সাধারণ মাছ ব্যবহার করবেন না।","ভাতের ভিনেগার মৃদু ও মিষ্টি। শক্ত মল্ট ভিনেগার দিয়ে বদলাবেন না, যা ভাতকে ছাপিয়ে যাবে।","নোরি মচমচে ও গাঢ় হওয়া উচিত। বন্ধ ও শুকনো রাখুন, কারণ ভেজা নোরি ছিঁড়ে যায় আর পরিচ্ছন্নভাবে গোল হবে না।"],"variations":["টুনার রোল: স্যামনের বদলে সুশি মানের টুনা ব্যবহার করুন, আর শসার বদলে অ্যাভোকাডো দিন।","রান্না করা চিংড়ির রোল: রান্না করা চিংড়ি, শসা ও একটু মেয়ো ব্যবহার করুন, কাঁচা মাছ পছন্দ না হলে ভালো পছন্দ।","সবজির রোল: সম্পূর্ণ নিরামিষ রোলের জন্য তিলের বীজ দিয়ে শসা, অ্যাভোকাডো, গাজরের কাঠি ও আচারি মুলা ব্যবহার করুন।"],"serving":"হালকা খাবার হিসেবে, প্রতিজনকে 2টি রোল দিয়ে 4 জনের জন্য যথেষ্ট, বা মিসো স্যুপ ও সালাদ দিয়ে বড় জাপানি খাবারের অংশ হিসেবে। কাটার পরপরই ঘরের তাপমাত্রায় পরিবেশন করুন, ডোবানোর জন্য সয়া সস, টুকরোর মাঝে মুখ পরিষ্কার করতে আচারি আদা, আর অল্প করে ব্যবহার করা ওয়াসাবি দিয়ে। সুশি হাতের খাবার, তাই চপস্টিক ও ছোট পাত্র সাজিয়ে রাখুন, আর সবাইকে নিজে নিজে পরিবেশন করতে দিন।","storage":"সুশি যেদিন বানানো হয় সেদিনই, গোল করার কয়েক ঘণ্টার মধ্যে খাওয়াই সেরা। ফ্রিজে রাখলে ভাত শুকিয়ে যায় আর মাছ ম্লান হয়, তাই এক দিন আগে বানাবেন না। রাখতেই হলে শক্ত করে ঢেকে 6 ঘণ্টা পর্যন্ত ফ্রিজে রাখুন, তারপর পরিবেশনের আগে 20 মিনিট ঘরের তাপমাত্রায় ফিরিয়ে আনুন। সুশি ফ্রিজ করবেন না। একা রান্না করা সুশি ভাত ফ্রিজে 1 দিন থাকে।","mistakes":["গরম ভাত ব্যবহার করা। এটা নোরিকে নরম করে বাষ্প দেয় আর রোল ভেঙে ফেলে, তাই ভাত সবে গরম হওয়া পর্যন্ত ঠান্ডা করুন।","রোল বেশি ভরা। বেশি ভরাট রোল বন্ধ হতে বাধা দেয়, তাই ভরাট এক পরিচ্ছন্ন সারিতে রাখুন।","শুকনো ছুরি দিয়ে কাটা। ভাত আটকে টানে, তাই প্রতিটি কাটার আগে ব্লেড ভিজিয়ে নিন।","গোল করার সময় খুব জোরে চাপ দেওয়া। ভাত চেপে যায় আর ভরাট বেরিয়ে যায়, তাই শক্ত কিন্তু আলতো করে গোল করুন।"],"faq":[["বাড়িতে কাঁচা স্যামন খাওয়া কি নিরাপদ?","শুধু বিশ্বস্ত বিক্রেতার কাছ থেকে সুশি মানের স্যামন হলে, ঠান্ডা রাখা হলে, আর একই দিনে খাওয়া হলে। সন্দেহ হলে তার বদলে রান্না করা চিংড়ি বা সবজি ব্যবহার করুন।"],["বাঁশের মাদুর ছাড়া কি সুশি বানানো যায়?","হ্যাঁ। ক্লিং ফিল্মের নিচে চায়ের তোয়ালে, বা বেকিং কাগজের শিট ব্যবহার করুন। মাদুর সহজ করে, তবে অপরিহার্য নয়।"],["আমার ভাত আঠালো ও নরম হলো কেন?","যথেষ্ট ধোয়া হয়নি, বা মসলা দেওয়ার সময় জোরে নাড়া হয়েছিল। ভালো করে ধুয়ে নিন আর মসলা আলতো করে মিশিয়ে নিন।"],["ভাত কি আগে তৈরি করা যায়?","হ্যাঁ, কয়েক ঘণ্টা আগে। ফ্রিজে নয়, ঘরের তাপমাত্রায় ঢেকে রাখুন, আর পরিবেশনের ঠিক আগে গোল করুন।"]]},"ramen":{"intro":"রামেন হলো বাটিতে আরাম, আর ভালো বাড়িতে বানানো সংস্করণের জন্য সারাদিন ফোটানো ঝোল দরকার হয় না। এই মুরগির রামেন দ্রুত স্বাদ তৈরি করে, তিলের তেলে ভাজা রসুন, আদা ও পেঁয়াজকলি দিয়ে, সয়া ও মিসো দিয়ে সমৃদ্ধ মুরগির স্টক দিয়ে, আর নুডলস আলাদা রান্না করা যাতে ঝোল পরিষ্কার থাকে আর নুডলস প্রাণবন্ত থাকে। ডিম হলো শেষ ছোঁয়া, মাঝখানে নরম আর খাওয়ার সময় ঝোল দিয়ে মসলা দেওয়া। টপিং ছোট বাটিতে সাজিয়ে রাখুন আর সবাইকে নিজের বাটি বানাতে দিন, গরম ঝোল সবার শেষে, যাতে নুডলস বসে নরম না হয়। এটা দ্রুত, উষ্ণ ও গভীরভাবে তৃপ্তিদায়ক, আর শর্টকাটের মতো নয়, যত্নের মতো স্বাদ দেয়।","ing":["মুরগির বুক বা থাই 500 গ্রাম","মুরগির স্টক 1.5 লিটার","রামেন নুডলস 4 ভাগ","রসুন 4 কোয়া","আদা 3 সেমি টুকরো","সয়া সস 3 টেবিল চামচ","মিসো পেস্ট 2 টেবিল চামচ","তিলের তেল 1 টেবিল চামচ","পেঁয়াজকলি 4টি","ডিম 4টি (নরম সেদ্ধ)","পরিবেশনের জন্য লঙ্কার তেল","তিলের বীজ","নোরি"],"steps":["ডিম 6.5 মিনিট সেদ্ধ করুন, ঠান্ডা জলে ঠান্ডা করুন, খোসা ছাড়ান, আর পরিবেশনের ঠিক আগে অর্ধেক করুন।","বড় হাঁড়িতে তিলের তেল গরম করুন, রসুন, আদা ও পেঁয়াজকলির সাদা অংশ সুগন্ধ আসা পর্যন্ত 2 মিনিট ভাজুন।","মুরগির স্টক ঢালুন, সয়া সস দিন, আর স্বাদগুলো একত্র হওয়ার জন্য 15 মিনিট আলতো করে ফোটান।","মুরগি ফোটানো ঝোলে 12 থেকে 15 মিনিট রান্না করুন যতক্ষণ না পুরোপুরি রান্না হয়, তারপর তুলে নিন, কেটে নিন, আর গরম রাখুন।","মিসো এক হাতা গরম ঝোলের সঙ্গে মসৃণ হওয়া পর্যন্ত ফেটিয়ে নিন, তারপর হাঁড়িতে ফিরিয়ে নাড়ুন। মিসো দেওয়ার পর জোরে ফোটাবেন না।","নুডলস প্যাকেট অনুযায়ী আলাদা রান্না করুন, ভালো করে ছেঁকে নিন, আর 4টি গরম বাটিতে ভাগ করুন।","নুডলসের উপর গরম ঝোল ঢালুন, উপরে কাটা মুরগি, ডিমের অর্ধেক, পেঁয়াজকলির সবুজ অংশ ও তিলের বীজ দিন।","পাশে লঙ্কার তেল ও নোরি দিয়ে সঙ্গে সঙ্গে পরিবেশন করুন, আর ঝোল বাষ্প উঠতে উঠতে খান।"],"tip":"নুডলস আলাদা রান্না করুন। ঝোলে রান্না করা নুডলস সেটা শুষে নেয়, ঝোল ঘোলাটে করে, আর পরিবেশনের আগেই নরম হয়ে যায়।","notes":["মিসো গভীরতা ও লবণ যোগ করে। সাদা মিসো মৃদু ও মিষ্টি, লাল মিসো শক্তিশালী, তাই লাল ব্যবহার করলে কম দিয়ে শুরু করুন।","টাটকা রামেন নুডলস 2 থেকে 3 মিনিটে রান্না হয় আর প্রাণবন্ত থাকে। শুকনো নুডলসও চলে, তবে প্যাকেটের সময় দেখে নিন আর বেশি রান্না করবেন না।","আদা কুচি নয়, ফালি করা উচিত, যাতে ঝোল ঘোলাটে বা দানাদার না করে স্বাদ দেয়।","তিলের তেল বেশি আঁচে ভাজার জন্য নয়, স্বাদের জন্য। শুরুতে মাঝারি আঁচে দিন, আর ধোঁয়া উঠতে দেবেন না।"],"variations":["ঝাল রামেন: মিসোর সঙ্গে ঝোলে 1 টেবিল চামচ লঙ্কার পেস্ট বা গোচুজাং নাড়ুন।","সবজির রামেন: মুরগির বদলে মাশরুম ও টোফু ব্যবহার করুন, আর সবজির স্টক ব্যবহার করুন, একই সুগন্ধি রেখে।","শূকরের রামেন: মুরগির বদলে পাতলা কাটা রান্না করা শূকর ব্যবহার করুন, আর উপরে মিষ্টি ভুট্টা ও বিন স্প্রাউট দিন।"],"serving":"গভীর বাটিতে, চপস্টিক ও স্যুপের চামচ দিয়ে, আর টপিং টেবিলের মাঝখানে 4 জনের জন্য যথেষ্ট। ঝোল বাষ্প উঠতে উঠতে পরিবেশন করুন, হাতের কাছে বাড়তি লঙ্কার তেল, সয়া সস ও তিলের বীজ রেখে, যাতে প্রত্যেকে নিজের বাটি মসলা দিতে পারে। রামেন সঙ্গে সঙ্গে খাওয়া হয়, নুডলস প্রাণবন্ত ও ডিম এখনও গরম থাকতে, তাই ঝোল ঢালার আগে সবাইকে টেবিলে ডাকুন।","storage":"ঝোল ফ্রিজে 3 দিন পর্যন্ত থাকে, আর 1 মাস পর্যন্ত ভালো ফ্রিজ হয়। নুডলস ও টপিং একত্র হওয়ার পর ভালো থাকে না, তাই আলাদা রাখুন আর টাটকা সাজান। ঝোল ফুটতে থাকা পর্যন্ত গরম করুন, টাটকা নুডলস রান্না করুন, আর পরিবেশনের ঠিক আগে টপিং দিন। বেঁচে যাওয়া কাটা মুরগি ফ্রিজে 2 দিন থাকে।","mistakes":["মিসো দেওয়ার পর ঝোল জোরে ফোটানো। স্বাদ ম্লান হয় আর আলাদা হয়ে যেতে পারে, তাই আলতো ফোটানো অবস্থায় রাখুন।","নুডলস বেশি রান্না করা। গরম ঝোলে নরম হয়ে যায়, তাই প্রাণবন্ত হওয়া পর্যন্ত রান্না করুন আর ভালো করে ছেঁকে নিন।","ডিম খুব তাড়াতাড়ি দেওয়া। গরম ঝোলে বেশি রান্না হয়, তাই অর্ধেক করা ডিম একদম শেষে দিন।","ঠান্ডা বাটিতে পরিবেশন করা। ঝোল খুব দ্রুত ঠান্ডা হয়, তাই আগে গরম জল দিয়ে বাটি গরম করুন।"],"faq":[["ইনস্ট্যান্ট নুডলস ব্যবহার করা যাবে?","হ্যাঁ, তবে স্বাদের প্যাকেট ফেলে দিন আর তার বদলে এই ঝোল ব্যবহার করুন। নুডলসের ব্লক আলাদা রান্না করুন আর ভালো করে ছেঁকে নিন।"],["ঝোল কি আগে বানানো যায়?","হ্যাঁ। 3 দিন আগে পর্যন্ত বানিয়ে ফ্রিজে রাখুন। ফুটতে থাকা পর্যন্ত গরম করুন, তারপর মিসো টাটকা দিন আর বাটি সাজান।"],["জ্যামি ডিম পাব কীভাবে?","ফ্রিজের ঠান্ডা ডিম 6.5 মিনিট সেদ্ধ করুন, সঙ্গে সঙ্গে ঠান্ডা জলে ঠান্ডা করুন, আর আলতো করে খোসা ছাড়ান। কুসুম নরম ও সবে জমাট হওয়া উচিত।"],["রামেন কি খুব নোনতা?","হতে পারে। বাড়তি সয়া সস দেওয়ার আগে স্বাদ দেখুন, কারণ স্টক, সয়া ও মিসো সবই লবণ যোগ করে।"]]},"tacos":{"intro":"টাকোস আল পাস্তর মেক্সিকো সিটিতে রান্না করা লেবাননের শাওয়ারমা দিয়ে শুরু হয়েছিল, আর এটা পুরোপুরি মেক্সিকান কিছুতে পরিণত হয়েছিল, শুকনো লঙ্কা ও আচিওটে মেরিনেট করা শূকর, কিনারা পোড়া পর্যন্ত রান্না করা, আর গরম ভুট্টার টরটিয়ায় আনারস, পেঁয়াজ ও ধনেপাতা দিয়ে পরিবেশন করা। মেরিনেড ভারী কাজ করে, তাই সময় দিন, 30 মিনিটও পার্থক্য গড়ে, আর সারারাত আরও ভালো। শূকর গরম ও দ্রুত রান্না করুন যাতে শুকিয়ে না গিয়ে পোড়ে, টরটিয়া খোলা আগুনে বা শুকনো প্যানে গরম করুন, আর উপরের জিনিস সাধারণ রাখুন। ধোঁয়াটে, মসলাদার শূকরের বিপরীতে মিষ্টি আনারসই আসল কথা, তাই বাদ দেবেন না, আর পাশে লেবু ও সালসা দিয়ে পরিবেশন করুন।","ing":["শূকরের কাঁধ 700 গ্রাম (পাতলা করে কাটা)","শুকনো গুয়াহিয়ো লঙ্কা 3টি","আনচো লঙ্কা 1টি","আচিওটে বাটা 2 টেবিল চামচ","রসুন 3 কোয়া","সাদা ভিনেগার 3 টেবিল চামচ","কমলার রস 60 মিলি","জিরা 1 চা চামচ","ওরেগানো 1 চা চামচ","লবণ","আনারস 300 গ্রাম (টুকরো করে কাটা)","ভুট্টার টরটিয়া 12টি","সাদা পেঁয়াজ 1টি","ধনেপাতা","লেবু 2টি","আপনার পছন্দের সালসা"],"steps":["শুকনো লঙ্কা গরম জলে 15 মিনিট নরম হওয়া পর্যন্ত ভিজিয়ে রাখুন, তারপর ছেঁকে নিন, ভেজানো জলের একটু রেখে।","লঙ্কা, আচিওটে, রসুন, ভিনেগার, কমলার রস, জিরা, ওরেগানো ও লবণ মসৃণ মেরিনেড বানিয়ে মেশান, দরকার হলে ভেজানো জল দিন।","শূকর মেরিনেডে মাখান, ঢেকে দিন, আর অন্তত 30 মিনিট, বা সেরা স্বাদের জন্য সারারাত ফ্রিজে রাখুন।","অল্প তেল দিয়ে বড় প্যান বা গ্রিডল বেশি আঁচে গরম করুন, আর শূকর ব্যাচে প্রতি পাশ 3 থেকে 4 মিনিট রান্না করুন যতক্ষণ না পোড়া ও পুরোপুরি রান্না হয়।","একই গরম প্যানে আনারসের টুকরো প্রতি পাশ 1 থেকে 2 মিনিট সেঁকে নিন যতক্ষণ না কিনারাগুলো সোনালি হয়।","শূকর ছোট টুকরো করে কাটুন আর আনারস ও এক চামচ প্যানের রসের সঙ্গে মেশান।","টরটিয়া শুকনো প্যানে বা আগুনের উপর নরম ও হালকা দাগযুক্ত হওয়া পর্যন্ত গরম করুন, আর কাপড়ে মুড়ে রাখুন।","প্রতিটি টরটিয়া শূকর ও আনারস দিয়ে ভরুন, উপরে কাটা পেঁয়াজ ও ধনেপাতা দিন, আর লেবুর ফালি ও সালসা দিয়ে পরিবেশন করুন।"],"tip":"ব্যাচে রান্না করুন আর প্যান ভরে ফেলবেন না। ভরা শূকর পোড়ার বদলে ভাপে সেদ্ধ হয়, আর আল পাস্তরকে বিশেষ করা মচমচে কিনারাগুলো হারিয়ে যায়।","notes":["আচিওটে বাটা লাল রং ও মাটির স্বাদ দেয়। মেক্সিকান দোকানে বা অনলাইনে পাবেন, আর শুধু খাবারের রং দিয়ে বদলাবেন না।","গুয়াহিয়ো লঙ্কা মৃদু ও ফলের মতো। আনচো গভীরতা যোগ করে। কম ঝাল চাইলে বীজ সরিয়ে দিন, আর শুকনো লঙ্কা ধরার সময় গ্লাভস পরুন।","শূকরের কাঁধ গরম ও দ্রুত রান্না করলে রসালো থাকে। চর্বিহীন শূকরের কোমর সহজে শুকিয়ে যায়, তাই পাতলা করে কাটুন আর কম সময় রান্না করুন।","ভুট্টার টরটিয়া ঐতিহ্যবাহী। ময়দার টরটিয়াও চলে, তবে নরম আর রসালো পুর ধরে রাখতে কম সক্ষম।"],"variations":["মুরগির আল পাস্তর: একই মেরিনেড দিয়ে মুরগির থাই ব্যবহার করুন, আর হালকা সংস্করণের জন্য পোড়া পর্যন্ত রান্না করুন।","অ্যাভোকাডো দিয়ে: ক্রিমের ভাবের জন্য কাটা অ্যাভোকাডো ও এক চিমটি লেবু দিন, আনারসও রেখে।","বেশি ঝাল সংস্করণ: মেরিনেডে 1টি চিপোটলে ইন অ্যাডোবো দিন, আর পাশে গরম সালসা দিয়ে পরিবেশন করুন।"],"serving":"প্রতিজনকে 3টি টাকো, সঙ্গে টেবিলে লেবু, সালসা, বাড়তি পেঁয়াজ ও ধনেপাতা দিয়ে 4 জনের জন্য যথেষ্ট। টরটিয়া গরম ও শূকর এখনও চিড়বিড় করার সময়, ভরার সঙ্গে সঙ্গে টাকো পরিবেশন করুন, আর সবাইকে নিজের লেবু ও সালসা দিতে দিন। ভাত ও শিমের সাধারণ পাশের পদ, বা মচমচে বাঁধাকপির সালাদ, টাকো থেকে মনোযোগ না সরিয়ে পুরো খাবার বানিয়ে দেয়।","storage":"মেরিনেট করা কাঁচা শূকর ফ্রিজে 1 দিন পর্যন্ত থাকে। রান্না করা শূকর ফ্রিজে 3 দিন পর্যন্ত থাকে, আর একটু জল দিয়ে গরম প্যানে সবচেয়ে ভালো গরম হয়, যাতে আবার মচমচে হয়। টরটিয়া ঘরের তাপমাত্রায় মুড়ে 1 দিন, বা ফ্রিজে 3 দিন থাকে, আর শুকনো প্যানে গরম হয়। সাজানো টাকো জমিয়ে রাখবেন না, সেগুলো ভিজে যায়। আনারস আলাদাভাবে 2 দিন থাকে।","mistakes":["ঠান্ডা প্যান ব্যবহার করা। শূকর পোড়ার বদলে মেরিনেডে সেদ্ধ হয়, তাই আগে প্যান ধোঁয়া ওঠা গরম করুন।","মেরিনেডের সময় বাদ দেওয়া। 30 মিনিটও গুরুত্বপূর্ণ, আর শুধু 5 মিনিট মেরিনেট করা শূকর স্বাদহীন লাগে।","টরটিয়া বেশি ভরা। সেগুলো ফেটে যায় আর পুর বেরিয়ে পড়ে, তাই প্রতি টাকোয় 2 থেকে 3 টেবিল চামচ শূকর ব্যবহার করুন।","লেবু ভুলে যাওয়া। টক সমৃদ্ধ শূকরকে তোলে, তাই সবসময় লেবুর ফালি পরিবেশন করুন।"],"faq":[["শূকর কি গ্রিলে রান্না করা যায়?","হ্যাঁ। বেশি আঁচে প্রতি পাশ 3 থেকে 4 মিনিট গ্রিল করুন, তারপর কেটে আনারসের সঙ্গে মেশান। গ্রিডল প্যান বাড়ির ভেতরে সবচেয়ে কাছের ফল দেয়।"],["আচিওটে বাটা না পেলে কী হবে?","রঙের জন্য 1 টেবিল চামচ ধোঁয়াটে পাপরিকা, 1 চা চামচ গুঁড়ো জিরা ও এক চিমটি হলুদ ব্যবহার করুন। স্বাদ আলাদা, তবে তবু কাজ করে।"],["ভুট্টার টরটিয়া কি গ্লুটেনমুক্ত?","শুধু ভুট্টা, জল ও চুন দিয়ে বানানো খাঁটি ভুট্টার টরটিয়া স্বাভাবিকভাবে গ্লুটেনমুক্ত, তবে আপনার জন্য গুরুত্বপূর্ণ হলে ক্রস দূষণের জন্য প্যাকেট দেখে নিন।"],["মেরিনেড কি আগে বানানো যায়?","হ্যাঁ। মিশিয়ে 3 দিন পর্যন্ত ফ্রিজে রাখুন, বা 1 মাস ফ্রিজ করুন। রান্নার দিন শূকর মেরিনেট করুন।"]]},"pozole":{"intro":"পোজোলে মেক্সিকোর উৎসবের স্যুপ, হোমিনি দিয়ে বানানো, বড় সাদা ভুট্টার দানা যা লম্বা ফোটানোয় ফুলে নরম হয়, আর শূকরের মাংস যা চামচ দিয়ে ছিঁড়ে যাওয়া পর্যন্ত রান্না হয়। লাল সংস্করণ রং ও গভীরতা পায় শুকনো গুয়াহিয়ো ও আনচো লঙ্কা থেকে, মসৃণ করে মিশিয়ে ঝোলে নাড়া হয়, আর উপরের জিনিস টাটকা ও মচমচে থাকে, কাটা বাঁধাকপি, মুলা, পেঁয়াজ, ওরেগানো ও লেবু। সময় লাগে, তবে সেই সময়ের বেশিরভাগটাই নজর ছাড়া, আর হাঁড়ি অনেক লোককে খাওয়ায়। সপ্তাহান্তে রান্না করুন, ঝোল সমৃদ্ধ ও উপরের জিনিস আলাদা রাখুন, আর সবাইকে টেবিলে নিজের বাটি শেষ করতে দিন।","ing":["শূকরের কাঁধ 1 কেজি (বড় টুকরো করে কাটা)","সাদা হোমিনি 800 গ্রাম (ছেঁকে ধোয়া)","শুকনো গুয়াহিয়ো লঙ্কা 4টি","আনচো লঙ্কা 2টি","পেঁয়াজ 1টি","রসুন 6 কোয়া","তেজপাতা 2টি","ওরেগানো 2 চা চামচ","জিরা 1 চা চামচ","লবণ","জল বা হালকা স্টক 3 লিটার","পরিবেশনের জন্য কাটা বাঁধাকপি","মুলা","পেঁয়াজ","লেবু","পরিবেশনের জন্য শুকনো ওরেগানো","লঙ্কার গুঁড়ো"],"steps":["শুকনো লঙ্কা গরম জলে 15 মিনিট ভিজিয়ে রাখুন, ছেঁকে নিন, আর রসুন ও একটু ভেজানো জল দিয়ে মসৃণ হওয়া পর্যন্ত মেশান।","শূকর, হোমিনি, পেঁয়াজ, তেজপাতা ও জল বড় হাঁড়িতে রাখুন, ফুটতে দিন, আর উপরের ফেনা তুলে ফেলুন।","আলতো ফোটানো অবস্থায় নামিয়ে আনুন, আংশিক ঢেকে দিন, আর স্তর খুব নিচে নেমে গেলে গরম জল দিয়ে 90 মিনিট রান্না করুন।","মেশানো লঙ্কার সস ছাঁকনি দিয়ে হাঁড়িতে ছেঁকে নিন, ভালো করে নাড়ুন, আর লবণ, জিরা ও ওরেগানো দিয়ে মসলা দিন।","শূকর ছিঁড়ে যাওয়ার মতো নরম হয়ে ঝোল সমৃদ্ধ ও লাল হওয়া পর্যন্ত আরও 30 মিনিট ফোটান।","শূকর তুলে নিন, দুটি কাঁটাচামচ দিয়ে ছিঁড়ে নিন, আর হাঁড়িতে ফিরিয়ে দিন। স্বাদ দেখুন আর লবণ ও লঙ্কা ঠিক করুন।","পোজোলে শেষ হওয়ার সময় উপরের জিনিস তৈরি করুন, কাটা বাঁধাকপি, পাতলা মুলার ফালি, কাটা পেঁয়াজ, লেবুর ফালি ও ওরেগানো।","গভীর বাটিতে ঢালুন, উদারভাবে উপরের জিনিস দিন, আর পাশে গরম টরটিয়া দিয়ে পরিবেশন করুন।"],"tip":"লঙ্কার সস দেওয়ার আগে ছেঁকে নিন। ছাঁকনি খোসা ও বীজ ধরে ফেলে, আর ঝোল দানাদার হওয়ার বদলে মসৃণ ও রেশমের মতো থাকে।","notes":["হোমিনি হলো চুন দিয়ে শোধন করা ভুট্টা, যা দানাগুলোকে বড়, নরম ও হজমে সহজ করে। কৌটোর হোমিনি ব্যবহারের জন্য তৈরি, শুকনো হোমিনিতে সারারাত ভেজানো ও বেশি রান্না লাগে।","গুয়াহিয়ো লঙ্কা রং ও হালকা ফলের ঝাল দেয়। আনচো গাঢ়, কিশমিশের মতো গভীরতা যোগ করে। একসঙ্গে সেগুলো ক্লাসিক লাল ঝোল বানায়।","শূকরের কাঁধে লম্বা ফোটানোয় রসালো থাকার মতো যথেষ্ট চর্বি থাকে। চর্বিহীন শূকর শুকিয়ে যায়, তাই টুকরো বড় রাখুন আর ফোটানো আলতো রাখুন।","শুরুতে ফেনা তুলে ফেলুন। এটা ঝোল পরিষ্কার ও স্বাদ পরিচ্ছন্ন রাখে।"],"variations":["সবুজ পোজোলে: লাল লঙ্কার বদলে টোমাটিলো, সবুজ লঙ্কা ও ধনেপাতা ব্যবহার করুন, মিশিয়ে একইভাবে দিন।","মুরগির পোজোলে: শূকরের বদলে হাড়সহ মুরগির থাই ব্যবহার করুন, আর ফোটানোর সময় প্রায় 45 মিনিটে কমিয়ে দিন।","নিরামিষ পোজোলে: সবজির স্টক দিয়ে মাশরুম ও শিম ব্যবহার করুন, আর একই লঙ্কার সস ও উপরের জিনিস দিন।"],"serving":"গভীর বাটিতে, উপরের জিনিস টেবিলের মাঝখানে আলাদা বাটিতে 6 জনের জন্য যথেষ্ট। প্রত্যেকে মচমচে ভাবের জন্য বাঁধাকপি, কামড়ের জন্য মুলা, পেঁয়াজ, ওরেগানো ও লেবুর ভালো চাপ দেয়, যা সমৃদ্ধ ঝোলকে তোলে। তুলে খাওয়ার জন্য গরম ভুট্টার টরটিয়া দিয়ে পরিবেশন করুন, আর বেশি ঝাল চাইলে পাশে বাড়তি লঙ্কার গুঁড়ো রাখুন।","storage":"পোজোলে ফ্রিজে 4 দিন পর্যন্ত থাকে, আর স্বাদ সারারাত থাকলে আরও ভালো হয়। ঝোল ও শূকর একসঙ্গে রাখুন, আর উপরের জিনিস আলাদা। ঘন হয়ে গেলে একটু জল দিয়ে ফুটতে থাকা পর্যন্ত আলতো করে গরম করুন। 3 মাস পর্যন্ত ভালো ফ্রিজ হয়, ফ্রিজে সারারাত গলিয়ে নিন। টাটকা উপরের জিনিস ফ্রিজ করবেন না।","mistakes":["সারাক্ষণ জোরে ফোটানো। শূকর শক্ত হয় আর ঝোল ঘোলাটে হয়, তাই আলতো ফোটানো রাখুন।","লঙ্কার সস ছাঁকা ছাড়া দেওয়া। খোসা ও বীজ ঝোল দানাদার করে।","টাটকা উপরের জিনিস ছাড়া পরিবেশন করা। সেগুলো সাজানো নয়, মচমচে ভাব ও টক দিয়ে সমৃদ্ধ ঝোলের ভারসাম্য আনে।","ঝোলে কম লবণ দেওয়া। শেষে স্বাদ দেখুন, কারণ হোমিনি ও শূকরের উজ্জ্বল হতে ভালো পরিমাণ লবণ দরকার।"],"faq":[["প্রেসার কুকার ব্যবহার করা যাবে?","হ্যাঁ। চাপে শূকর ও হোমিনি 35 থেকে 40 মিনিট রান্না করুন, তারপর লঙ্কার সস দিয়ে খোলা হাঁড়িতে 10 মিনিট শেষ করুন।"],["পোজোলে কি খুব ঝাল?","লাল সংস্করণ উষ্ণ, প্রচণ্ড ঝাল নয়। মৃদু ঝোলের জন্য লঙ্কার বীজ সরিয়ে দিন, আর টেবিলে লঙ্কার গুঁড়োকে ঝাল যোগ করতে দিন।"],["শুকনো হোমিনি ব্যবহার করা যাবে?","হ্যাঁ, তবে সারারাত ভিজিয়ে রাখুন আর শূকর দেওয়ার আগে নরম হওয়া পর্যন্ত ফোটান, যাতে বাড়তি এক ঘণ্টা লাগতে পারে।"],["পোজোলের সঙ্গে কী পরিবেশন করব?","গরম ভুট্টার টরটিয়া, আর এখানে তালিকাভুক্ত টাটকা উপরের জিনিস। সাধারণ সালাদ দরকার নেই, উপরের জিনিসই সালাদ।"]]},"padthai":{"intro":"প্যাড থাই থাইল্যান্ডের সবচেয়ে বিখ্যাত নুডলসের পদ, আর এর জাদু হলো ভারসাম্য, মিষ্টি, টক, নোনতা আর একটু ঝাল, সব এক গরম কড়াইয়ে। সস বানানো হয় তেঁতুল, মাছের সস, তালের চিনি ও লঙ্কা দিয়ে, আর এটা চালের নুডলস ঢেকে দেয় যা সেদ্ধ নয়, ভেজানো, তাই নরম হওয়ার বদলে প্রাণবন্ত থাকে। চিংড়ি, ডিম, বিন স্প্রাউট ও চিভস বেশি আঁচে দ্রুত যায়, আর পদটি শেষ হয় থেঁতো করা বাদাম, লেবু ও পাশে বাড়তি স্প্রাউট দিয়ে। শুরু করার আগে সবকিছু তৈরি রাখুন, কারণ কড়াই গরম হলে রান্না মাত্র কয়েক মিনিট লাগে, আর সেই গতিই নুডলসকে নরম পিণ্ড হওয়া থেকে বাঁচায়।","ing":["চ্যাপ্টা চালের নুডলস 250 গ্রাম","চিংড়ি 300 গ্রাম (খোসা ছাড়ানো)","ডিম 2টি (হালকা ফেটানো)","তেঁতুলের বাটা 3 টেবিল চামচ","মাছের সস 3 টেবিল চামচ","তালের চিনি বা বাদামি চিনি 3 টেবিল চামচ","রসুন 3 কোয়া","লঙ্কার গুঁড়ো 1 চা চামচ","বিন স্প্রাউট 2 কাপ","রসুনের চিভস বা পেঁয়াজকলি","ভাজা বাদাম 4 টেবিল চামচ (থেঁতো করা)","লেবু 1টি"],"steps":["চালের নুডলস গরম জলে 20 থেকে 30 মিনিট ভিজিয়ে রাখুন যতক্ষণ না নমনীয় কিন্তু তবু শক্ত হয়, তারপর ভালো করে ছেঁকে নিন।","তেঁতুল, মাছের সস, চিনি ও লঙ্কার গুঁড়ো মিশিয়ে সস বানান, আর স্বাদ দেখুন। একসঙ্গে মিষ্টি, টক ও নোনতা হওয়া উচিত।","কড়াইয়ে বেশি আঁচে তেল গরম করুন, রসুন 20 সেকেন্ড ভাজুন, তারপর চিংড়ি দিন আর সবে গোলাপি হওয়া পর্যন্ত 2 মিনিট রান্না করুন।","চিংড়ি এক পাশে সরিয়ে দিন, ডিম ঢালুন, আর সবে জমাট হওয়া পর্যন্ত আলতো করে নাড়ুন, তারপর চিংড়ির সঙ্গে মেশান।","ছাঁকা নুডলস ও সস দিন, আর নুডলস নরম হয়ে সস শুষে নেওয়া পর্যন্ত 2 থেকে 3 মিনিট অনবরত নাড়ুন।","অর্ধেক বিন স্প্রাউট ও চিভস দিন, 30 সেকেন্ড নাড়ুন, আর কড়াই আঁচ থেকে নামিয়ে নিন।","প্লেটে ভাগ করুন, উপরে বাকি স্প্রাউট, থেঁতো করা বাদাম ও পেঁয়াজকলি দিন।","লেবুর ফালি, বাড়তি লঙ্কার গুঁড়ো ও পাশে মাছের সস দিয়ে সঙ্গে সঙ্গে পরিবেশন করুন, প্রত্যেকে নিজে ঠিক করতে পারে।"],"tip":"নুডলস ভিজিয়ে রাখুন, সেদ্ধ করবেন না। সেদ্ধ নুডলস কড়াইয়ে বেশি রান্না হয়ে নরম ও আঠালো হয়।","notes":["তেঁতুলের বাটা সেই টক সুর দেয় যা প্যাড থাইকে সংজ্ঞায়িত করে। খুব ঘন হলে সস মেশানোর আগে একটু গরম জল দিয়ে পাতলা করুন।","তালের চিনি ক্যারামেলের মতো মিষ্টিতে গলে যায়। বাদামি চিনি ভালো কাজ করে, তবে সাদা চিনি আরও তীক্ষ্ণ, তাই একটু কম ব্যবহার করুন।","মাছের সস নোনতা ও তীব্র। সরাসরি কড়াইয়ে নয়, সসে দিন, যাতে সমানভাবে মেশে।","চ্যাপ্টা চালের নুডলস পুরুত্বে আলাদা হয়। পাতলা নুডলস দ্রুত ভেজে, তাই 15 মিনিট পর দেখে নিন আর এখনও শক্ত থাকতে ছেঁকে নিন।"],"variations":["মুরগির প্যাড থাই: চিংড়ির বদলে পাতলা কাটা মুরগি ব্যবহার করুন, ডিম যাওয়ার আগে পুরোপুরি রান্না করুন।","টোফুর প্যাড থাই: নিরামিষ সংস্করণের জন্য আগে সোনালি হওয়া পর্যন্ত ভাজা শক্ত টোফু ব্যবহার করুন, আর দেখে নিন আপনার মাছের সসের বদলি আপনার উপযুক্ত কিনা।","বাড়তি সবজি: আরও মচমচে ভাব ও রঙের জন্য নুডলসের সঙ্গে কাটা গাজর ও কাটা বাঁধাকপি দিন।"],"serving":"গরম প্লেটে, টেবিলে লেবুর ফালি, থেঁতো করা বাদাম, বাড়তি বিন স্প্রাউট ও লঙ্কার গুঁড়ো দিয়ে 4 জনের জন্য যথেষ্ট। প্যাড থাই স্ট্রিট ফুডের পদ, তাই গরম ও অনানুষ্ঠানিকভাবে পরিবেশন করুন, সবাই নিজের প্লেটে লেবু চিপে দেবে আর ইচ্ছেমতো আরও বাদাম বা ঝাল দেবে। পাশে হালকা শসার সালাদ সতেজ করে, তবে মনোযোগ নুডলসেই রাখুন।","storage":"প্যাড থাই টাটকা খাওয়াই সেরা, সরাসরি কড়াই থেকে। বেঁচে যাওয়া খাবার ফ্রিজে 1 দিন পর্যন্ত থাকে, আর একটু জল দিয়ে গরম কড়াই বা প্যানে অনবরত নেড়ে গরম করা যায়। নুডলস গরম করলে নরম হয়, তাই একই গঠন আশা করবেন না। ফ্রিজ করবেন না। একা সস ফ্রিজে 1 সপ্তাহ পর্যন্ত থাকে।","mistakes":["নুডলস বেশি রান্না করা। ছাঁকার সময় শক্ত হওয়া উচিত, কারণ সসে রান্না শেষ হয়।","যথেষ্ট গরম নয় এমন কড়াই ব্যবহার করা। নুডলস ভাপে সেদ্ধ হয় আর আটকে যায়, তাই কড়াই ধোঁয়া উঠতে শুরু করা পর্যন্ত গরম করুন।","সব স্প্রাউট খুব তাড়াতাড়ি দেওয়া। সেগুলো নেতিয়ে নরম হয়ে যায়, তাই অর্ধেক শেষে দিন আর অর্ধেক উপরে দেওয়ার জন্য কাঁচা রাখুন।","সসের স্বাদ দেখতে ভুলে যাওয়া। রান্নার আগে ভারসাম্য করুন, কারণ নুডলস ঢুকে গেলে মিষ্টি, টক ও নোনতা ঠিক করা যায় না।"],"faq":[["মাছের সস ছাড়া কি প্যাড থাই বানানো যায়?","হ্যাঁ, এক চিমটি লবণ দিয়ে সয়া সস, বা নিরামিষ মাছের সস ব্যবহার করুন। স্বাদ আলাদা, তবে মিষ্টি ও টকের ভারসাম্য থাকে।"],["আমার নুডলস একসঙ্গে আটকে গেলে কী করব?","বেশিক্ষণ ভেজানো হয়েছিল বা কড়াই যথেষ্ট গরম ছিল না। ভালো করে ছেঁকে নিন, একটু তেল দিয়ে নাড়ুন, আর পরের বার আরও গরম কড়াইয়ে রান্না করুন।"],["শুকনো চিংড়ি ব্যবহার করা যাবে?","হ্যাঁ। 2 টেবিল চামচ শুকনো চিংড়ি ভিজিয়ে রসুনের সঙ্গে দিন। সেগুলো ঐতিহ্যবাহী নোনতা গভীরতা যোগ করে।"],["প্যাড থাই কি গ্লুটেনমুক্ত?","চালের নুডলস স্বাভাবিকভাবে গ্লুটেনমুক্ত, তবে মাছের সস ও তেঁতুলের বাটায় সংযোজন থাকতে পারে, তাই লেবেল দেখে নিন।"]]},"pekingduck":{"intro":"পিকিং ডাক চীনের অন্যতম বড় উৎসবের পদ, চামড়া এত মচমচে যে ভেঙে যায়, আর নিচের মাংস রসালো থাকে বলে বিখ্যাত। গোপন কথা হলো ভাজার আগে চামড়া শুকিয়ে গ্লেজ করা, যাতে চর্বি বেরিয়ে যায় আর চামড়া গাঢ় ল্যাকার করা লাল সোনালি হয়ে যায়। এই বাড়িতে বানানো সংস্করণে চামড়া শুকাতে ফ্রিজে সারারাত রাখা, সাধারণ মল্টোজ ও ভিনেগারের গ্লেজ, আর গরম ওভেন ব্যবহার করা হয়, তারপর কাটার আগে বিশ্রাম। ঐতিহ্যবাহীভাবে পরিবেশন করুন, পাতলা ম্যান্ডারিন প্যানকেক, হয়সিন সস, পেঁয়াজকলি ও শসা দিয়ে, আর সবাইকে নিজেরটা সাজাতে দিন। এটা একটা প্রকল্প, সপ্তাহের রাতের খাবার নয়, আর প্রতিটি মিনিটের মূল্য আছে।","ing":["গোটা হাঁস 2 থেকে 2.5 কেজি","মল্টোজ বা মধু 3 টেবিল চামচ","চালের ভিনেগার 2 টেবিল চামচ","শাওশিং ওয়াইন 2 টেবিল চামচ","পাঁচ মসলা 1 চা চামচ","লবণ 1 টেবিল চামচ","ব্লাঞ্চ করার জন্য ফুটন্ত জল","ম্যান্ডারিন প্যানকেক 12টি","হয়সিন সস 120 মিলি","পেঁয়াজকলি 4টি","শসা 1টি","খোলে দেওয়ার জন্য আদা","রসুন (ঐচ্ছিক)"],"steps":["হাঁস পরিষ্কার করুন, খুব ভালো করে মুছে শুকিয়ে নিন, আর মাংস ছিদ্র না করার যত্ন নিয়ে কাঁটাচামচ দিয়ে চামড়া সব জায়গায় হালকা ছিদ্র করুন।","সিঙ্কে হাঁসের উপর ফুটন্ত জল ঢালুন, যা চামড়া টানটান করে, তারপর আবার মুছে শুকিয়ে নিন।","মল্টোজ, ভিনেগার, শাওশিং ওয়াইন, পাঁচ মসলা ও লবণ গরম করুন যতক্ষণ না মল্টোজ গলে যায়, আর হাঁসের সব জায়গায় মাখিয়ে দিন।","হাঁস ফ্রিজে ঢাকা ছাড়া সারারাত রেখে দিন, ট্রের উপর র্যাকে, যাতে চামড়া পুরোপুরি শুকিয়ে যায়।","200C তাপে বুকের দিক উপরে করে 30 মিনিট ভাজুন, তারপর 180C এ নামিয়ে আরও 60 থেকে 75 মিনিট ভাজুন, যতক্ষণ না চামড়া গাঢ় সোনালি ও মচমচে হয়।","মাঝপথে বাকি গ্লেজ দিয়ে একবার মাখান, আর ডানার ডগা খুব দ্রুত বাদামি হলে ফয়েল দিয়ে ঢেকে দিন।","রস বসে যাওয়া ও চামড়া মচমচে থাকার জন্য কাটার আগে হাঁস 20 মিনিট রেখে দিন।","চামড়া ও মাংস পাতলা ফালি করে কাটুন, প্যানকেক গরম করুন, আর হয়সিন, পেঁয়াজকলির লাঠি ও শসার কাঠি দিয়ে পরিবেশন করুন।"],"tip":"চামড়া সারারাত শুকিয়ে নিন। ভেজা চামড়া ওভেনে ভাপে সেদ্ধ হয় আর কখনও মচমচে হয় না, আর শুকনো চামড়া গলে গিয়ে সুন্দরভাবে ল্যাকার হয়।","notes":["মল্টোজ ক্লাসিক চকচকে ভাব ও হালকা মিষ্টি দেয়। মধুও চলে, তবে দ্রুত বাদামি হয়, তাই শেষ 20 মিনিটে হাঁসের দিকে খেয়াল রাখুন।","পাঁচ মসলা শক্তিশালী। মেপে দিন, আর বাড়তি দেবেন না, নইলে হাঁসকে ছাপিয়ে যাবে।","হাঁসের চামড়ার নিচে অনেক চর্বি থাকে। চামড়া ছিদ্র করলে সেটা বেরিয়ে যায়, আর র্যাকে ভাজলে হাঁস নিজের চর্বি থেকে দূরে থাকে।","ম্যান্ডারিন প্যানকেক পাতলা ও নরম। পরিবেশনের ঠিক আগে 2 মিনিট ভাপে গরম করুন, আর শুকিয়ে না যাওয়ার জন্য ঢেকে রাখুন।"],"variations":["দোকান থেকে কেনা হাঁস দিয়ে: চীনা ডেলির ভাজা হাঁস ব্যবহার করুন, চামড়া গরম ওভেনে মচমচে করুন, আর একইভাবে প্যানকেক ও হয়সিন দিয়ে পরিবেশন করুন।","হাঁসের বুকের সংস্করণ: হাঁসের বুক চিরে দিন, চামড়ার দিক নিচে করে মচমচে হওয়া পর্যন্ত সেঁকে নিন, ওভেনে শেষ করুন, আর প্যানকেকের জন্য পাতলা করে কাটুন।","প্লাম সস দিয়ে: মিষ্টি, আরও ফলের শেষের জন্য হয়সিনের বদলে প্লাম সস ব্যবহার করুন।"],"serving":"ভাগ করে খাওয়ার খাবারের কেন্দ্র হিসেবে, কাটা হাঁস প্লেটে, গরম প্যানকেক, হয়সিন, পেঁয়াজকলি ও শসা টেবিলের মাঝখানে 6 জনের জন্য যথেষ্ট। প্রত্যেকে প্যানকেকে হয়সিন মাখায়, কয়েক ফালি হাঁস ও চামড়া, পেঁয়াজকলির লাঠি ও শসা দেয়, আর মুড়ে নেয়। পাশে হালকা স্যুপ বা ভাজা সবুজ শাক দিয়ে পরিবেশন করুন, আর হাঁস থাকতে থাকতে প্যানকেক আসতে থাকুক।","storage":"বেঁচে যাওয়া হাঁস বায়ুরোধী পাত্রে ফ্রিজে 2 দিন পর্যন্ত থাকে। মাংস ঢাকা প্যানে একটু জল দিয়ে আলতো করে গরম করুন, আর চামড়া আলাদাভাবে গরম গ্রিলের নিচে বা গরম ওভেনে কয়েক মিনিট মচমচে করুন। প্যানকেক ফ্রিজে 2 দিন থাকে আর ভাপে গরম করা যায়। কাটা চামড়া ফ্রিজ করবেন না, এটা মচমচে ভাব হারায়।","mistakes":["সারারাত শুকানো বাদ দেওয়া। ওভেন যত গরমই হোক চামড়া নরম ও চর্বিযুক্ত থাকে।","খুব কম তাপমাত্রায় ভাজা। চর্বি গলে না, তাই চামড়া মচমচে হওয়ার বদলে তেলতেলে হয়।","খুব তাড়াতাড়ি কাটা। রস বেরিয়ে যায় আর চামড়া ভাপে সেদ্ধ হয়, তাই পুরো 20 মিনিট রেখে দিন।","মোটা প্যানকেক ব্যবহার করা। সেগুলো হাঁসকে ছাপিয়ে যায়, তাই পাতলা ম্যান্ডারিন প্যানকেক ব্যবহার করুন আর ভালো করে গরম করুন।"],"faq":[["ছোট ওভেনে কি পিকিং ডাক বানানো যায়?","হ্যাঁ, যদি হাঁস চারপাশে বাতাস রেখে ঢুকে যায়। প্রায় 2 কেজির ছোট হাঁস সহজ, আর পদ্ধতি একই।"],["মল্টোজ না পেলে কী হবে?","একটু গরম জল দিয়ে পাতলা করা মধু ব্যবহার করুন। গ্লেজ একটু গাঢ় হবে, তাই ভাজার শেষের দিকে খেয়াল রাখুন।"],["শুধু হাঁসের পা ব্যবহার করা যাবে?","হ্যাঁ। একইভাবে শুকিয়ে গ্লেজ করুন, আর মচমচে হওয়া পর্যন্ত প্রায় 50 থেকে 60 মিনিট ভাজুন। গোটা হাঁসের চেয়ে সামলানো সহজ।"],["আমার হাঁসের চামড়া মচমচে হলো না কেন?","চামড়া যথেষ্ট শুকনো ছিল না, বা ওভেন খুব ঠান্ডা ছিল। সারারাত শুকিয়ে নিন, ভালো করে ছিদ্র করুন, আর গরম ভাজুন।"]]},"dimsum":{"intro":"ডিম সাম মানে হৃদয় ছোঁয়া খাবার, আর এটা ভাগ করে খাওয়ার জন্য, ছোট বাঁশের স্টিমার একের পর এক টেবিলে আসে, প্রতিটার ভেতরে আলাদা কামড়। এই বাড়িতে বানানো সংস্করণে দুটি ক্লাসিক হয়, স্বচ্ছ মোড়কসহ চিংড়ির হার গও, আর খোলা উপরসহ শূকর ও চিংড়ির সিউ মাই, দুটোই সবে রান্না হওয়া পর্যন্ত ভাপে রান্না করা আর গরম পরিবেশন করা। মোড়কে হালকা স্পর্শ ও একটু ধৈর্য লাগে, তবে পুর সহজ, আর ভাপে রান্না দ্রুত। সাহায্য নিয়ে বানান, একজন ভরবে, একজন ভাঁজ করবে, আর তৈরি ডাম্পলিং ঢেকে রাখুন যাতে শুকিয়ে না যায়। ক্যান্টনিজ ইয়াম চায়ের মতো চা দিয়ে পরিবেশন করুন, আর খাবারটা ধীরে ধীরে চলতে দিন।","ing":["চিংড়ি 300 গ্রাম (মিহি করে কাটা)","শূকরের কিমা 200 গ্রাম","হার গওয়ের জন্য গমের স্টার্চ 120 গ্রাম","ট্যাপিওকা স্টার্চ 60 গ্রাম","সিউ মাইয়ের জন্য ওনটন মোড়ক 20টি","আদা 1 টেবিল চামচ (কাটা)","পেঁয়াজকলি 2টি","সয়া সস 2 টেবিল চামচ","তিলের তেল 1 চা চামচ","সাদা গোলমরিচ","চিনি 1 চা চামচ","শাওশিং ওয়াইন 1 টেবিল চামচ","পরিবেশনের জন্য লঙ্কার তেল","সয়া সস","কালো ভিনেগার"],"steps":["চিংড়ি, শূকর, আদা, পেঁয়াজকলি, সয়া, তিলের তেল, চিনি, ওয়াইন ও সাদা গোলমরিচ মিশিয়ে পুর বানান, আর 20 মিনিট ঠান্ডা করুন।","হার গওয়ের মোড়কের জন্য গমের স্টার্চ ও ট্যাপিওকা স্টার্চ সবে ফোটানো 180 মিলি জলের সঙ্গে মেশান, মসৃণ ময়দা মেখে নিন, আর ঢেকে 15 মিনিট রেখে দিন।","হার গওয়ের ময়দা লম্বা করে গড়িয়ে নিন, ছোট টুকরো করুন, আর প্রতিটা ছুরির পাশ বা বেলন দিয়ে পাতলা গোল আকারে চেপে দিন।","প্রতিটি মোড়কে এক চামচ পুর রাখুন, অর্ধচন্দ্রাকারে ভাঁজ করুন, আর কিনারা শক্ত করে প্লিট করুন, উপরটা বন্ধ করে।","সিউ মাইয়ের জন্য প্রতিটি ওনটন মোড়কের মাঝখানে এক চামচ পুর রাখুন, কিনারাগুলো পুরের চারপাশে তুলে নিন, আর আলতো চাপ দিন যাতে উপরটা খোলা থাকে।","বাঁশের স্টিমার ছিদ্রযুক্ত বেকিং কাগজ, বা বাঁধাকপির পাতা দিয়ে সাজান, আর ডাম্পলিং ফাঁক রেখে সাজান।","হার গও 6 থেকে 7 মিনিট আর সিউ মাই 8 মিনিট ভাপে রান্না করুন, যতক্ষণ না মোড়ক স্বচ্ছ বা জমাট হয় আর পুর রান্না হয়।","স্টিমারেই সঙ্গে সঙ্গে পরিবেশন করুন, ডোবানোর জন্য লঙ্কার তেল, সয়া সস ও কালো ভিনেগার দিয়ে, আর পাশে গরম চা দিয়ে।"],"tip":"ডাম্পলিং বেশি ভরবেন না। সমান এক চা চামচ পুর পরিচ্ছন্নভাবে বন্ধ হয়, আর বেশি পুর স্টিমারে মোড়ক ফাটিয়ে দেয়।","notes":["গমের স্টার্চ হার গওয়ের মোড়ক স্বচ্ছ ও নাজুক করে। সাধারণ ময়দা একই ফল দেবে না, তাই এশিয়ান দোকান থেকে গমের স্টার্চ কিনুন।","ময়দা সবসময় ঢেকে রাখুন। কয়েক মিনিটে শুকিয়ে যায় আর ভাঁজ করতে গেলে ফেটে যায়।","আকৃতি দেওয়ার আগে পুর ঠান্ডা করুন। ঠান্ডা পুর ভাগ করা সহজ আর মোড়কের ভেতরে আকৃতি ধরে রাখে।","দরকার হলে ব্যাচে ভাপে রান্না করুন। ভরা স্টিমার একসঙ্গে আটকে যায়, আর ডাম্পলিং তোলার সময় ছিঁড়ে যায়।"],"variations":["সবজির ডিম সাম: মাংসের বদলে মিহি করে কাটা মাশরুম, বাঁধাকপি, গাজর ও টোফু ব্যবহার করুন, একইভাবে মসলা দিয়ে।","মুরগির ডিম সাম: চিংড়িসহ মুরগির কিমা ব্যবহার করুন, আর মচমচে ভাবের জন্য ওয়াটার চেস্টনাট দিন।","দোকান থেকে কেনা মোড়ক দিয়ে: দুই ধরনের জন্যই গোল ডাম্পলিং মোড়ক ব্যবহার করুন, বন্ধ করে প্লিট করা, সহজ সংস্করণের জন্য যা তবু চমৎকার স্বাদ দেয়।"],"serving":"ভাগ করে খাওয়ার খাবারের অংশ হিসেবে, প্রতিজনকে 5 থেকে 6টি ডাম্পলিং, সঙ্গে চা, আর পাশে সাধারণ শসার সালাদ বা ভাজা সবুজ শাক দিয়ে 4 জনের জন্য যথেষ্ট। স্টিমার সরাসরি টেবিলে পরিবেশন করুন, ঢাকনা দিয়ে, যাতে ডাম্পলিং খাওয়ার মুহূর্ত পর্যন্ত গরম ও বাষ্পযুক্ত থাকে। ডিম সাম ছোট কামড়ে ধীর খাবার, তাই চা আবার ভরে দিন, স্টিমার ব্যাচে আনুন, আর তাড়াহুড়ো করবেন না।","storage":"রান্না না করা ডাম্পলিং ট্রেতে 1 মাস পর্যন্ত ভালো ফ্রিজ হয়, তারপর ব্যাগে রাখা হয়। জমাট অবস্থা থেকে 3 থেকে 4 মিনিট বেশি ভাপে রান্না করুন। রান্না করা ডাম্পলিং ফ্রিজে 1 দিন থাকে, আর 3 মিনিট ভাপে গরম করুন, মাইক্রোওয়েভে নয়, যা মোড়ক শক্ত করে। বেঁচে যাওয়া পুর ঢেকে ফ্রিজে 1 দিন থাকে।","mistakes":["খুব মোটা মোড়ক ব্যবহার করা। ভাপে রান্নার পর আটার মতো থাকে, তাই পাতলা করে বেলুন বা চাপুন।","শুকনো স্টিমারে ভাপে রান্না করা। ডাম্পলিং আটকে ছিঁড়ে যায়, তাই স্টিমার সাজিয়ে হালকা তেল দিন।","ঢাকনা বারবার খোলা। বাষ্প বেরিয়ে যায় আর ডাম্পলিং অসমান রান্না হয়, তাই সময় শেষ হওয়া পর্যন্ত ঢাকনা বন্ধ রাখুন।","ডাম্পলিং অনেক আগে বানানো। মোড়ক শুকিয়ে ফেটে যায়, তাই ভাপে রান্নার ঠিক আগে আকৃতি দিন, বা ভেজা কাপড় দিয়ে ঢেকে রাখুন।"],"faq":[["বাঁশের স্টিমার ছাড়া কি ডিম সাম বানানো যায়?","হ্যাঁ। ধাতব স্টিমার, হাঁড়ির উপর ঝাঁঝরি, বা ঢাকা কড়াইয়ে র্যাকে প্লেট ব্যবহার করুন। ভালো করে সাজিয়ে নিন যাতে কিছু আটকে না যায়।"],["আমার হার গওয়ের মোড়ক ফাটছে কেন?","ময়দা শুকিয়ে গেছে, বা বেশি ঠান্ডা হয়ে গেছে। ঢেকে রাখুন, ছোট টুকরো দিয়ে কাজ করুন, আর শক্ত হলে অল্প মেখে নিন।"],["জমাট চিংড়ি ব্যবহার করা যাবে?","হ্যাঁ। পুরোপুরি গলিয়ে নিন, মুছে শুকিয়ে নিন, আর মেশানোর ঠিক আগে কাটুন। ভেজা চিংড়ি ঢিলা পুর বানায়।"],["ডিম সামের সঙ্গে কোন সস যায়?","লঙ্কার তেল, হালকা সয়া সস ও কালো ভিনেগার, স্বাদমতো মেশানো। ভিনেগারে একটু কাটা আদা ঐতিহ্যবাহী।"]]},"coqauvin":{"intro":"কক ও ভাঁ ফরাসি ক্লাসিক আরামের খাবার, মুরগি লাল ওয়াইনে ধীরে সেদ্ধ করা যতক্ষণ না হাড় থেকে পড়ে যায়, মাশরুম, মুক্তো পেঁয়াজ ও বেকন দিয়ে, এমন সসে যা মদ্যপ স্বাদ ছাড়াই ওয়াইনের স্বাদ দেয়। এটা বার্গান্ডি থেকে এসেছে, যেখানে ওয়াইন রান্নার অংশ, শুধু সঙ্গী নয়, আর লম্বা নরম সেদ্ধই মুরগিকে নরম ও সসকে সমৃদ্ধ করে। আগে মুরগি ভালো করে বাদামি করুন, কারণ সেই রং স্বাদে পরিণত হয়, তারপর হাঁড়িকে ওভেনে কাজ করতে দিন। ম্যাশ করা আলু বা শক্ত রুটি দিয়ে পরিবেশন করুন, আর সসে লবণের জন্য শেষ স্বাদ দেখুন আর চকচকে করতে একটু মাখন দিন।","ing":["মুরগির থাই","পা 1 কেজি (হাড়সহ)","লাল ওয়াইন 500 মিলি (পারলে বার্গান্ডি ধাঁচের)","বেকন লার্ডন 150 গ্রাম","মাশরুম 250 গ্রাম","মুক্তো পেঁয়াজ 12টি","গাজর 1টি","রসুন 3 কোয়া","থাইম 3 ডাল","মুরগির স্টক 250 মিলি","টমেটো বাটা 1 টেবিল চামচ","ময়দা 2 টেবিল চামচ","মাখন 2 টেবিল চামচ","পরিবেশনের জন্য পার্সলে","লবণ","গোলমরিচ"],"steps":["মুরগি ভালো করে মসলা দিন, হালকা ময়দা ছড়িয়ে দিন, আর গরম ওভেন-নিরাপদ হাঁড়িতে ব্যাচে দুই পাশ গাঢ় সোনালি হওয়া পর্যন্ত বাদামি করুন। সরিয়ে রাখুন।","একই হাঁড়িতে বেকন মচমচে হওয়া পর্যন্ত ভাজুন, তুলে নিন, আর মাশরুম ও মুক্তো পেঁয়াজ বেকনের চর্বিতে বাদামি করুন।","গাজর, রসুন ও টমেটো বাটা দিন, আর সুগন্ধ আসা পর্যন্ত নেড়ে 2 মিনিট রান্না করুন।","ওয়াইন ঢালুন, হাঁড়ির তলা চেঁছে সব বাদামি স্বাদ তুলে নিন, আর 3 মিনিট ফোটান।","মুরগি ও বেকন হাঁড়িতে ফিরিয়ে দিন, স্টক ও থাইম দিন, আর আলতো ফোটানো অবস্থায় আনুন। তরল মুরগির অর্ধেক পর্যন্ত আসা উচিত।","ঢেকে 160C ওভেনে 75 থেকে 90 মিনিট রান্না করুন, যতক্ষণ না মুরগি খুব নরম হয়।","মুরগি তুলে নিন, আর সস চুলায় 10 মিনিট ফোটান যতক্ষণ না চামচ ঢেকে ফেলে। শেষে মাখন ফেটিয়ে দিন।","মুরগি সসে ফিরিয়ে দিন, গরম করুন, আর পার্সলে ছড়িয়ে পরিবেশন করুন।"],"tip":"সেদ্ধ করার আগে মুরগি ঠিকমতো বাদামি করুন। ফ্যাকাসে মুরগি ফ্যাকাসে সস বানায়, আর গাঢ় সোনালি মুরগি সমৃদ্ধ, পুরো স্বাদের সস বানায়।","notes":["হাড়সহ মুরগি লম্বা সেদ্ধে রসালো থাকে। হাড় ছাড়া মুরগি দ্রুত রান্না হয় আর শুকিয়ে যেতে পারে, তাই ব্যবহার করলে ওভেনের সময় কমিয়ে দিন।","এমন ওয়াইন ব্যবহার করুন যা আপনি পান করবেন। সস্তা রান্নার ওয়াইন কঠোর সস বানায়, আর ফলের লাল ওয়াইন গভীরতা ও রং দেয়।","মুক্তো পেঁয়াজ ছোট ও মিষ্টি। না পেলে চার ভাগ করা শ্যালট ব্যবহার করুন।","শেষে ফেটানো মাখন সসে নরম চকচকে ভাব দেয় আর ওয়াইনকে গোল করে। দেওয়ার পর সস ফোটাবেন না।"],"variations":["সাদা ওয়াইনের সংস্করণ: শুকনো সাদা ওয়াইন ব্যবহার করুন আর শেষে ক্রিম দিন, হালকা কক ও ভাঁ ব্লঁর জন্য।","আলু দিয়ে: শেষ 40 মিনিটের জন্য ছোট নতুন আলু হাঁড়িতে দিন, যাতে সসে রান্না হয়।","স্লো কুকার সংস্করণ: আগে সবকিছু বাদামি করুন, তারপর কম আঁচে 5 থেকে 6 ঘণ্টা রান্না করুন, আর শেষে চুলায় সস কমিয়ে নিন।"],"serving":"অগভীর বাটিতে, সস ধরার জন্য ক্রিমযুক্ত ম্যাশ করা আলু, মাখনযুক্ত নুডলস বা শক্ত রুটি দিয়ে 4 জনের জন্য যথেষ্ট। মুরগি উদারভাবে এক হাতা সস, মাশরুম ও পেঁয়াজ, আর পার্সলে ছড়িয়ে পরিবেশন করা উচিত। এটা রবিবারের পদ, তাই হাঁড়ি থেকে টেবিলে পরিবেশন করুন, পাশে সাধারণ সবুজ সালাদ আর পছন্দ হলে গ্লাসে বাকি ওয়াইন দিয়ে।","storage":"কক ও ভাঁ ফ্রিজে 3 দিন পর্যন্ত থাকে, আর পরের দিন আরও ভালো স্বাদ হয়। সস খুব ঘন হলে একটু স্টক দিয়ে চুলায় টগবগ করা পর্যন্ত আলতো করে গরম করুন। 3 মাস পর্যন্ত ভালো ফ্রিজ হয়, ফ্রিজে সারারাত গলিয়ে নিন। মুরগি সসের মধ্যে রাখুন, যাতে শুকিয়ে না যায়।","mistakes":["বাদামি করা বাদ দেওয়া। সসে রং ও গভীরতা থাকবে না, তাই ব্যাচে বাদামি করতে সময় নিন।","সেদ্ধ জোরে ফোটানো। মুরগি শক্ত হয় আর সস খুব দ্রুত কমে যায়, তাই আলতো ফোটানো ও কম ওভেন রাখুন।","বেশি ওয়াইন ও স্টক ছাড়া ব্যবহার করা। সস তীক্ষ্ণ হয়ে যায়, তাই ওয়াইন স্টকের সঙ্গে ভারসাম্য করুন আর পরিবেশনের আগে স্বাদ দেখুন।","মাখন খুব তাড়াতাড়ি দেওয়া। লম্বা ফোটানোয় আলাদা হয়ে যায়, তাই ফোটানো থেকে দূরে, একদম শেষে ফেটিয়ে দিন।"],"faq":[["মদ ছাড়া কি কক ও ভাঁ বানানো যায়?","হ্যাঁ, ওয়াইনের বদলে বাড়তি স্টক সঙ্গে 2 টেবিল চামচ লাল ওয়াইন ভিনেগার ও একটু আঙুরের রস ব্যবহার করুন। স্বাদ আলাদা, তবে সেদ্ধ তবু কাজ করে।"],["মুরগির বুক ব্যবহার করা যাবে?","যাবে, তবে শুধু শেষ 30 মিনিটের জন্য দিন, নইলে শুকিয়ে যাবে। থাই ও পা এই পদের জন্য অনেক ভালো।"],["কোন ওয়াইন ব্যবহার করব?","শুকনো, ফলের লাল ওয়াইন, আদর্শভাবে বার্গান্ডি থেকে। খুব ট্যানিনযুক্ত বা ওকযুক্ত ওয়াইন এড়িয়ে চলুন, যা লম্বা সেদ্ধে তেতো হতে পারে।"],["আগে কি বানানো যায়?","হ্যাঁ, আর উন্নত হয়। পুরোপুরি রান্না করুন, ঠান্ডা করুন, ফ্রিজে রাখুন, আর পরের দিন আলতো করে গরম করুন।"]]},"bouillabaisse":{"intro":"বুইয়াবেস মার্সেই থেকে এসেছে, যেখানে জেলেরা যে মাছ বিক্রি হয়নি তা দিয়ে স্যুপ বানাত, আর এখন এটা ফ্রান্সের সবচেয়ে প্রিয় উৎসবের পদগুলোর একটা। ঝোলই প্রধান, মাছের স্টক, টমেটো, মৌরি, কমলার খোসা, জাফরান ও জলপাই তেল দিয়ে তৈরি, আর মাছ ও সামুদ্রিক খাবার এতে মাত্র কয়েক মিনিট রান্না হয়, তাই নরম থাকে। পারলে দুই ভাগে পরিবেশন করুন, ঝোল ছেঁকে বাটিতে আর মাছ প্লেটে, রুই, জাফরান রসুনের মেয়োনিজ, সেঁকা রুটিতে মাখিয়ে। শুনতে জমকালো লাগে, তবে পদ্ধতি সহজ, ভালো ঝোল বানান, মাছ সঠিক ক্রমে দিন, আর বেশি রান্না করবেন না।","ing":["মিশ্র শক্ত সাদা মাছ 800 গ্রাম (টুকরো করে কাটা)","চিংড়ি 300 গ্রাম","ঝিনুক 300 গ্রাম (পরিষ্কার করা)","মাছের স্টক 1.5 লিটার","টমেটো 400 গ্রাম (কাটা)","টমেটো বাটা 2 টেবিল চামচ","মৌরি 1টি","পেঁয়াজ 1টি","লিক 1টি","জাফরান 1 বড় চিমটি","কমলার খোসা 1 ফালি","রসুন 4 কোয়া","জলপাই তেল 4 টেবিল চামচ","থাইম","শক্ত রুটি","রুই","পার্সলে","পরিবেশনের জন্য লেবু"],"steps":["বড় হাঁড়িতে জলপাই তেল গরম করুন, পেঁয়াজ, লিক, মৌরি ও রসুন নরম ও মিষ্টি হওয়া পর্যন্ত 8 মিনিট ভাজুন।","টমেটো বাটা ও কাটা টমেটো দিন, আর টমেটো ভাঙতে শুরু করা পর্যন্ত 5 মিনিট রান্না করুন।","মাছের স্টক ঢালুন, জাফরান, কমলার খোসা, থাইম ও এক চিমটি লবণ দিন, আর 20 মিনিট ফোটান।","ঝোল ছাঁকনি দিয়ে ছেঁকে নিন, সব স্বাদ পেতে সবজি চেপে দিন, তারপর ঝোল হাঁড়িতে ফিরিয়ে দিন।","ঝোল আবার আলতো ফোটানো অবস্থায় আনুন, আর সবচেয়ে শক্ত মাছ আগে দিন, 3 মিনিট রান্না করুন।","বাকি মাছ ও চিংড়ি দিন, আর পুরোপুরি রান্না হওয়া পর্যন্ত আরও 3 থেকে 4 মিনিট রান্না করুন।","ঝিনুক দিন, ঢেকে দিন, আর খুলে যাওয়া পর্যন্ত 3 মিনিট রান্না করুন। বন্ধ থাকা যেকোনোটি ফেলে দিন।","ঝোল ও সামুদ্রিক খাবার গরম বাটিতে ঢালুন, আর রুই মাখানো সেঁকা রুটি, পার্সলে ও লেবু দিয়ে পরিবেশন করুন।"],"tip":"মাছ বেশি রান্না করবেন না। সবচেয়ে শক্ত টুকরো আগে দিন আর নাজুক টুকরো শেষে, আর মাছ আঁশ ছাড়ার সঙ্গে সঙ্গেই হাঁড়ি আঁচ থেকে নামিয়ে নিন।","notes":["জাফরান দামি, তবে এক চিমটি ঝোলকে রং ও সুগন্ধ দিয়ে বদলে দেয়। দেওয়ার আগে 10 মিনিট এক চামচ গরম স্টকে ভিজিয়ে রাখুন।","সন্ন্যাসী মাছ, সি বাস ও লাল মুলেটের মতো মাছের মিশ্রণ ব্যবহার করুন, পেলে। একা এক মাছে পাতলা স্যুপ হয়।","কমলার খোসা উজ্জ্বল, সুগন্ধি সুর যোগ করে যা মার্সেইয়ে ক্লাসিক। সাদা ভেতরের অংশ ছাড়া চওড়া ফালি ব্যবহার করুন, আর পরিবেশনের আগে সরিয়ে নিন।","রুই বানানো হয় ডিমের কুসুম, রসুন, জাফরান, লেবু ও জলপাই তেল মেয়োনিজে ফেটিয়ে। জাফরানসহ দোকান থেকে কেনা আইওলি মোটামুটি শর্টকাট।"],"variations":["ঝিনুকসহ: পরিষ্কার করা ঝিনুক ঝিনুকের সঙ্গে দিন, আর না খোলা যেকোনোটি ফেলে দিন।","সহজ সপ্তাহের রাতের সংস্করণ: একই ঝোল দিয়ে শুধু চিংড়ি ও একটি শক্ত সাদা মাছ ব্যবহার করুন, আর রুটি দিয়ে পরিবেশন করুন।","আলু দিয়ে: মাছ দেওয়ার আগে কাটা আলু ঝোলে দিন আর নরম হওয়া পর্যন্ত ফোটান, আরও ভরাট স্যুপের জন্য।"],"serving":"গভীর গরম বাটিতে, উপরে মাছ ও সামুদ্রিক খাবার সাজিয়ে, আর টেবিলের মাঝখানে রুই দেওয়া টোস্টের প্লেট দিয়ে 6 জনের জন্য যথেষ্ট। প্রত্যেকে ঝোলে রুই চামচ দিয়ে দেয় বা রুটিতে মাখায়, আর মাছের উপর লেবু চিপে দেয়। সবুজ সালাদ ও এক গ্লাস শুকনো সাদা ওয়াইন দিয়ে পরিবেশন করুন, আর রুটি আনতে থাকুন, কারণ ঝোল ফেলে রাখার মতো ভালো নয়।","storage":"বুইয়াবেস টাটকা খাওয়াই সেরা, যেদিন বানানো হয় সেদিন। একা ঝোল ফ্রিজে 2 দিন পর্যন্ত থাকে আর 1 মাস ভালো ফ্রিজ হয়। বেঁচে যাওয়া মাছ ভালো করে গরম করা যায় না আর রাবারের মতো হতে পারে, তাই ঝোল আলাদা রাখুন আর গরম করার সময় টাটকা মাছ দিন। ঝোল ফুটতে থাকা পর্যন্ত গরম করুন, তারপর সামুদ্রিক খাবার এতে টাটকা রান্না করুন।","mistakes":["সামুদ্রিক খাবার বেশি রান্না করা। মাছ ও চিংড়ি এক মিনিটে নরম থেকে শক্ত হয়ে যায়, তাই হাঁড়ির দিকে কাছ থেকে খেয়াল রাখুন।","ছাঁকার ধাপ বাদ দেওয়া। ঝোল টুকরোযুক্ত থাকে আর স্বাদ কম পরিষ্কার হয়, তাই ছেঁকে নিন আর সবজি চেপে দিন।","তেলযুক্ত মাছ ব্যবহার করা। স্যামন ও ম্যাকেরেল নাজুক ঝোলকে ছাপিয়ে যায়, তাই শক্ত সাদা মাছ ব্যবহার করুন।","সব মাছ একসঙ্গে দেওয়া। নাজুক মাছ ভেঙে যায় যখন শক্ত মাছ এখনও রান্না হচ্ছে, তাই ধাপে ধাপে দিন।"],"faq":[["দোকান থেকে কেনা মাছের স্টক ব্যবহার করা যাবে?","হ্যাঁ। ভালো মানের স্টক বেছে নিন, আর লেখা অনুযায়ী সবজি ও জাফরান দিয়ে ফোটান। তবু সমৃদ্ধ স্বাদ আসবে।"],["রুই কী?","প্রোভঁসের জাফরান ও রসুনের মেয়োনিজ, টোস্টে মাখানো ও স্যুপে নাড়া হয়। এটা সমৃদ্ধি ও রং যোগ করে।"],["খোলসযুক্ত সামুদ্রিক খাবার ছাড়া কি বুইয়াবেস বানানো যায়?","হ্যাঁ, শুধু মাছ ব্যবহার করুন, আর একটু বাড়তি মাছের স্টক দিন। স্যুপ তবু চমৎকার, যদিও কম বৈচিত্র্যময়।"],["জাফরান কি অপরিহার্য?","এটা ক্লাসিক রং ও সুগন্ধ দেয়। সেটা ছাড়া স্যুপ তবু ভালো, তবে পুরোপুরি বুইয়াবেস নয়।"]]},"paella":{"intro":"পায়েয়া স্পেনের ভ্যালেন্সিয়া থেকে এসেছে, যেখানে এটা বাইরে চওড়া অগভীর প্যানে রান্না করা হয়, আর ভাত, সামুদ্রিক খাবার নয়, আসল প্রধান। জাফরান সোনালি রং দেয়, ভালো স্টক স্বাদ দেয়, আর রান্নার শেষ কয়েক মিনিট, বিরক্ত না করে রাখলে, সোকারাত তৈরি করে, নিচে মচমচে সেঁকা ভাতের স্তর যার জন্য সবাই লড়াই করে। পারলে ছোট দানার বোম্বা ভাত ব্যবহার করুন, সমান স্তরে ছড়িয়ে দিন, আর স্টক ঢালার পর নাড়ার ইচ্ছাকে প্রতিরোধ করুন। প্যানেই পরিবেশন করুন, টেবিলের মাঝখানে, লেবুর ফালি দিয়ে, আর সবাইকে একসঙ্গে ডুব দিতে দিন।","ing":["বোম্বা বা ছোট দানার ভাত 400 গ্রাম","চিংড়ি 300 গ্রাম","ঝিনুক 300 গ্রাম (পরিষ্কার করা)","স্কুইডের গোলা 200 গ্রাম (ঐচ্ছিক)","মুরগি বা মাছের স্টক 1 লিটার (গরম)","জাফরান 1 বড় চিমটি","পেঁয়াজ 1টি","লাল মরিচ 1টি","রসুন 3 কোয়া","টমেটো 2টি (কাটা)","ধোঁয়াটে পাপরিকা 1 চা চামচ","জলপাই তেল 4 টেবিল চামচ","লেবু 1টি","মটর 100 গ্রাম"],"steps":["জাফরান 3 টেবিল চামচ গরম স্টকে 10 মিনিট ভিজিয়ে রাখুন, আর বাকি স্টক গরম রাখুন।","চওড়া পায়েয়া প্যানে জলপাই তেল গরম করুন, পেঁয়াজ ও মরিচ নরম হওয়া পর্যন্ত 6 মিনিট ভাজুন, তারপর রসুন ও পাপরিকা দিন।","কাটা টমেটো দিন আর কালো হয়ে ঘন হওয়া পর্যন্ত 4 মিনিট রান্না করুন।","ভাত দিন আর সোফ্রিতোতে মাখানোর জন্য 1 মিনিট নাড়ুন, তারপর সমান স্তরে ছড়িয়ে দিন।","গরম স্টক ও জাফরানের তরল ঢালুন, লবণ দিয়ে মসলা দিন, আর আলতো ফোটানো অবস্থায় আনুন। এই পর্যায় থেকে নাড়বেন না।","মাঝারি আঁচে 15 মিনিট রান্না করুন, তারপর সামুদ্রিক খাবার ও মটর উপরে সাজান, ভাতের মধ্যে হালকা চেপে দিন।","আঁচ কমিয়ে দিন, ফয়েল দিয়ে আলগা ঢেকে দিন, আর ভাত নরম হয়ে ঝিনুক খুলে যাওয়া পর্যন্ত আরও 10 মিনিট রান্না করুন।","প্যান ঢেকে 5 মিনিট রেখে দিন, তারপর প্যানে লেবুর ফালি দিয়ে পরিবেশন করুন, সোকারাতের চিড়বিড় শব্দ শুনুন।"],"tip":"স্টক ঢালার পর ভাত নাড়বেন না। নাড়লে স্টার্চ বেরিয়ে ভাত আঠালো হয়, আর সোকারাত তৈরি হতে বাধা দেয়।","notes":["বোম্বা ভাত অনেক তরল শোষে আর আলাদা থাকে। লম্বা দানার ভাত পায়েয়ায় নরম পিণ্ড হয়, তাই বোম্বা না পেলে ছোট দানার ভাত ব্যবহার করুন।","স্টক গরম রাখুন। ঠান্ডা স্টক প্যান ঠান্ডা করে আর ভাত অসমান রান্না হয়।","ধোঁয়াটে পাপরিকা উষ্ণ, ধোঁয়াটে সুর দেয়। মিষ্টি পাপরিকাও চলে, তবে ঝাল পাপরিকা জাফরানকে ছাপিয়ে যেতে পারে।","জাফরান ব্যবহারের আগে ভিজিয়ে রাখা উচিত, যাতে রং ও সুগন্ধ ভাতের সব জায়গায় সমান ছড়ায়।"],"variations":["মুরগি ও চোরিজো পায়েয়া: সোফ্রিতোর সঙ্গে বাদামি করা মুরগি ও কাটা চোরিজো দিন, আর মুরগির স্টক ব্যবহার করুন।","সবজির পায়েয়া: সবজির স্টক, আর্টিচোক, সবুজ শিম ও মাখন শিম ব্যবহার করুন, একই জাফরান ভাতের পদ্ধতিতে।","মিশ্র পায়েয়া: মুরগি, চিংড়ি ও ঝিনুক একত্র করুন, মুরগি তাড়াতাড়ি আর সামুদ্রিক খাবার দেরিতে দিয়ে, প্রধান পদ্ধতির মতো।"],"serving":"প্যানে, টেবিলের মাঝখানে, লেবুর ফালি ও পাশে সবুজ সালাদ দিয়ে 6 জনের জন্য যথেষ্ট। প্রত্যেকে কিনারা থেকে ভেতরের দিকে এক ভাগ নেয়, যাতে সবাই মচমচে নিচের স্তরের কিছুটা পায়। পায়েয়া ভাগ করে খাওয়ার পদ, তাই বাড়তি লেবু, শক্ত রুটি ও পছন্দ হলে আইওলি সাজিয়ে রাখুন, আর রান্নাঘরে আলাদা প্লেটে পরিবেশন করবেন না।","storage":"পায়েয়া টাটকা খাওয়াই সেরা, সরাসরি প্যান থেকে। বেঁচে যাওয়া খাবার ফ্রিজে 2 দিন পর্যন্ত থাকে, আর একটু স্টক দিয়ে ঢেকে গরম প্যানে, বাষ্প ওঠা পর্যন্ত গরম করা যায়। ভাত তত মচমচে হবে না, আর সামুদ্রিক খাবার বেশিক্ষণ গরম করা উচিত নয়। খোলসযুক্ত সামুদ্রিক খাবারসহ পায়েয়া ফ্রিজ করবেন না, গঠন খারাপ হয়। সোকারাত শুধু সেদিনই থাকে।","mistakes":["ভাত নাড়া। আঠালো হয়ে যায় আর নিচটা কখনও মচমচে হয় না।","ভুল ভাত ব্যবহার করা। লম্বা দানার ভাত ও রিসোত্তো ভাত দুটোই ভুল গঠন দেয়।","ঠান্ডা স্টক দেওয়া। রান্না থেমে আবার শুরু হয়, আর ভাত অসমান রান্না হয়।","প্যান বেশি ভরা। উপরে বেশি সামুদ্রিক খাবার ভাতকে সেঁকার বদলে ভাপে সেদ্ধ করে, তাই স্তর সমান ও খুব গভীর নয় এমন রাখুন।"],"faq":[["পায়েয়া প্যান কি দরকার?","ভাতের স্তর পাতলা থাকলে চওড়া অগভীর প্যান চলে। গভীর হাঁড়ি ভাত খুব মোটা করে আর সেঁকার বদলে ভাপে সেদ্ধ করে।"],["জাফরান ছাড়া কি পায়েয়া বানানো যায়?","রঙের জন্য এক চিমটি হলুদ দিয়ে যাবে, তবে স্বাদ আলাদা। জাফরানই পায়েয়ার নির্ধারক স্বাদ।"],["ভাত হয়েছে বুঝব কীভাবে?","স্বাদ দেখুন। নরম হওয়া উচিত, একটু কামড় থাকবে, আর তরল শুষে যাওয়া উচিত। 5 মিনিট রেখে দিলে রান্না শেষ হয়।"],["আমার পায়েয়া নরম পিণ্ড হলো কেন?","ভাত নাড়া হয়েছিল, স্টক ঠান্ডা ছিল, বা আঁচ খুব কম ছিল। ভাত বিরক্ত না করে রাখুন আর আঁচ স্থির রাখুন।"]]},"beefpho":{"intro":"ফো ভিয়েতনামের সবচেয়ে বিখ্যাত স্যুপ, আর এর হৃদয় হলো পরিষ্কার ঝোল যার স্বাদ পোড়া পেঁয়াজ ও আদা, তারকা মৌরি, দারুচিনি, লবঙ্গ ও মাছের সসের, গরুর হাড় দিয়ে আলতো করে ফোটানো যতক্ষণ না সমৃদ্ধ কিন্তু কখনও ঘোলাটে হয়। নুডলস আলাদা রান্না হয়, গরুর মাংস কাগজের মতো পাতলা করে কাটা হয় আর ঢালার সময় গরম ঝোলে রান্না হয়, আর বাটি টেবিলে বিন স্প্রাউট, থাই তুলসি, ধনেপাতা, লেবু ও লঙ্কা দিয়ে শেষ করা হয়। সময় লাগে, তবে কাজের বেশিরভাগটাই অপেক্ষা করা ও ফেনা তোলা, আর ফলাফল এমন বাটি যা হালকা, সুগন্ধি ও গভীরভাবে আরামদায়ক, ভারী ঝোলের মতো কিছু নয়।","ing":["গরুর হাড় 1.5 কেজি","মজ্জা বা গাঁটের হাড়","গরুর ব্রিসকেট বা শিন 500 গ্রাম","চালের নুডলস 500 গ্রাম (চ্যাপ্টা)","পেঁয়াজ 2টি","আদা 1 বড় টুকরো","তারকা মৌরি 3টি","দারুচিনির কাঠি 1টি","লবঙ্গ 4টি","ধনের বীজ 1 চা চামচ","মৌরির বীজ 1 চা চামচ","মাছের সস 4 টেবিল চামচ","পাথরের চিনি 1 টেবিল চামচ","পরিবেশনের জন্য বিন স্প্রাউট","থাই তুলসি","ধনেপাতা","লেবু","লঙ্কা"],"steps":["হাড় ফুটন্ত জলে 5 মিনিট ব্লাঞ্চ করুন, ছেঁকে নিন, ধুয়ে নিন, আর টাটকা ঠান্ডা জল দিয়ে পরিষ্কার হাঁড়িতে ফিরিয়ে দিন।","পেঁয়াজের অর্ধেক ও আদা খোলা আগুনে বা গরম গ্রিলের নিচে জায়গায় জায়গায় কালো হওয়া পর্যন্ত পুড়িয়ে নিন, তারপর হাঁড়িতে দিন।","তারকা মৌরি, দারুচিনি, লবঙ্গ, ধনে ও মৌরি শুকনো প্যানে সুগন্ধ আসা পর্যন্ত 2 মিনিট ভেজে নিন, মসলিনে বেঁধে নিন বা আলগা দিয়ে পরে ছেঁকে নিন।","ঝোল খুব আলতো করে 2.5 ঘণ্টা ফোটান, ঘন ঘন ফেনা তুলুন, আর ব্রিসকেট শেষ 60 মিনিট নরম হওয়া পর্যন্ত দিন।","ব্রিসকেট তুলে নিন, একটু ঠান্ডা করুন, পাতলা করে কাটুন, আর ঝোল পরিষ্কার হওয়া পর্যন্ত মিহি ছাঁকনি দিয়ে ছেঁকে নিন।","ঝোল মাছের সস ও পাথরের চিনি দিয়ে মসলা দিন, স্বাদ দেখতে দেখতে, যতক্ষণ না নোনতা, সুগন্ধি ও একটু মিষ্টি হয়।","চালের নুডলস আলাদা রান্না করুন, ছেঁকে নিন, আর ব্রিসকেটের ফালি ও কাঁচা পাতলা কাটা গরুর মাংস দিয়ে বাটিতে ভাগ করুন।","প্রতিটি বাটিতে ফুটন্ত ঝোল ঢালুন, যাতে কাঁচা গরুর মাংস গরমে রান্না হয়, আর ভেষজ, স্প্রাউট, লেবু ও লঙ্কা দিয়ে পরিবেশন করুন।"],"tip":"ফোটানো আলতো রাখুন আর ঘন ঘন ফেনা তুলুন। জোরে ফোটানো ঝোল ঘোলাটে ও তেলতেলে করে, আর শান্ত ফোটানো পরিষ্কার ও পরিচ্ছন্ন স্বাদ রাখে।","notes":["পেঁয়াজ ও আদা পোড়ানো ধোঁয়াটে মিষ্টি যোগ করে যা ফোর জন্য অপরিহার্য। বাদ দেবেন না, আর পেঁয়াজ পুরোপুরি খোসা ছাড়াবেন না, খোসা রং যোগ করে।","পাথরের চিনি ঝোল মিষ্টি স্বাদের না করে মাছের সসের ভারসাম্য আনে। সাধারণ চিনিও চলে, তবে একটু কম ব্যবহার করুন।","কাঁচা গরুর মাংস আংশিক জমাট অবস্থায় কাটুন। পাতলা ও সমানভাবে কাটা যায়, আর গরম ঝোলে সেকেন্ডের মধ্যে রান্না হয়।","চালের নুডলস সবে নরম হওয়া পর্যন্ত ভেজানো বা রান্না করা উচিত, তারপর ভালো করে ছেঁকে নিন, যাতে বাটিতে সব ঝোল শুষে না নেয়।"],"variations":["মুরগির ফো: গোটা মুরগি ও মুরগির হাড় ব্যবহার করুন, 60 থেকে 75 মিনিট ফোটান, আর বাটির জন্য মাংস ছিঁড়ে নিন।","নিরামিষ ফো: একই মসলা, পোড়া পেঁয়াজ ও আদা দিয়ে মাশরুম ও সবজির স্টক ব্যবহার করুন, আর উপরে টোফু ও মাশরুম দিন।","বেশি ঝাল ফো: ঝোলে নয়, টেবিলে কাটা টাটকা লঙ্কা ও লঙ্কার সস দিন, যাতে প্রত্যেকে ঝাল নিয়ন্ত্রণ করে।"],"serving":"গভীর বাটিতে, ভেষজ, স্প্রাউট, লেবু ও লঙ্কা টেবিলের মাঝখানে আলাদা বাটিতে 6 জনের জন্য যথেষ্ট। প্রত্যেকে নিজের ভেষজ ও লেবুর চাপ দেয়, আর চপস্টিক ও চামচ দিয়ে খায়, প্রথমে নুডলস, তারপর ঝোল। ফো বাষ্প উঠতে উঠতে পরিবেশন করা হয় আর সঙ্গে সঙ্গে খাওয়া হয়, ভেষজ এখনও টাটকা ও গরুর মাংস সবে রান্না থাকতে।","storage":"ঝোল ফ্রিজে 4 দিন পর্যন্ত থাকে আর 3 মাস পর্যন্ত ভালো ফ্রিজ হয়। ঝোল, নুডলস ও উপরের জিনিস আলাদা রাখুন, আর টাটকা সাজান। ঝোল ফুটতে থাকা পর্যন্ত গরম করুন, টাটকা নুডলস রান্না করুন, আর পরিবেশনের ঠিক আগে গরুর মাংস কাটুন। বেঁচে যাওয়া রান্না করা ব্রিসকেট ফ্রিজে 2 দিন থাকে। সাজানো বাটি জমিয়ে রাখবেন না।","mistakes":["ঝোল জোরে ফোটানো। ঘোলাটে হয়ে যায় আর চর্বি স্যুপে মিশে যায়, তাই সবে ফোটানো অবস্থায় রাখুন।","ফেনা না তোলা। হাঁড়িতে থাকা ফেনা ও চর্বি স্বাদ ও পরিষ্কার ভাব ম্লান করে।","নুডলস বেশি রান্না করা। ঝোল শুষে নেয় আর নরম পিণ্ড হয়, তাই আলাদা রান্না করুন আর ভালো করে ছেঁকে নিন।","মসলার স্বাদ দেখতে ভুলে যাওয়া। মাছের সস ও চিনি শেষে ভারসাম্য করতে হয়, তাই অল্প পরিমাণে মসলা দিন আর ঘন ঘন স্বাদ দেখুন।"],"faq":[["প্রেসার কুকারে কি ফো বানানো যায়?","হ্যাঁ। চাপে হাড় 60 থেকে 75 মিনিট রান্না করুন, তারপর ছেঁকে মসলা দিন। স্বাদ খুব কাছাকাছি, যদিও ঝোল একটু কম পরিষ্কার।"],["কাঁচা ফালির জন্য কোন গরুর মাংস সবচেয়ে ভালো?","সারলয়েন বা আই অফ রাউন্ড, আংশিক জমাট অবস্থায় খুব পাতলা করে কাটা। গরম ঝোলে সেকেন্ডের মধ্যে রান্না হয়।"],["ফো কি গ্লুটেনমুক্ত?","চালের নুডলস ও বেশিরভাগ মাছের সস স্বাভাবিকভাবে গ্লুটেনমুক্ত, তবে সংযোজনের জন্য আপনার মাছের সস ও হয়সিনের লেবেল দেখে নিন।"],["ঝোল কি আগে বানানো যায়?","হ্যাঁ, আর সারারাত থাকলে আরও ভালো হয়। ফ্রিজে রাখুন, জমাট চর্বি সরিয়ে নিন, আর ফুটতে থাকা পর্যন্ত গরম করুন।"]]},"poutine":{"intro":"পাউটিন কানাডার কুইবেক থেকে এসেছে, আর এটা চমৎকারভাবে সহজ, গরম মচমচে ফ্রেঞ্চ ফ্রাই, টাটকা পনিরের ছানা যা কামড় দিলে কিচকিচ করে, আর উপরে ঢালা সমৃদ্ধ বাদামি গ্রেভি যাতে ছানা সবে গলতে শুরু করে। ফ্রাই এত মচমচে হতে হবে যাতে এক মিনিটে ভিজে না গিয়ে গ্রেভি ধরে রাখতে পারে, তাই দুবার ভাজা মূল্যবান, আর গ্রেভি টগবগে গরম হতে হবে, কারণ তাপই ছানাকে নরম করে। সঙ্গে সঙ্গে, বাটিতে, কাঁটাচামচ দিয়ে পরিবেশন করুন, আর ফ্রাই কিনারায় এখনও মচমচে ও গ্রেভি নিচে জমা থাকতে খান।","ing":["আলু 1 কেজি (ময়দাযুক্ত জাত)","পনিরের ছানা 250 গ্রাম (ঘরের তাপমাত্রায়)","গরু বা সবজির স্টক 500 মিলি","মাখন 2 টেবিল চামচ","ময়দা 2 টেবিল চামচ","সয়া সস 1 চা চামচ","ওরচেস্টারশায়ার সস 1 চা চামচ","রসুন 1 কোয়া","কালো গোলমরিচ","গভীর ভাজার জন্য তেল","লবণ","পরিবেশনের জন্য পেঁয়াজকলি (ঐচ্ছিক)"],"steps":["আলু মোটা লাঠি করে কাটুন, ঠান্ডা জলে 30 মিনিট ভিজিয়ে রাখুন, তারপর ছেঁকে খুব ভালো করে শুকিয়ে নিন।","তেল 160C তাপে গরম করুন, চিপস ব্যাচে 5 থেকে 6 মিনিট ভাজুন যতক্ষণ না ফ্যাকাসে ও নরম হয়, তারপর ছেঁকে 10 মিনিট রেখে দিন।","চিপস বিশ্রাম নেওয়ার সময় প্যানে মাখন গলিয়ে নিন, ময়দা নাড়ুন, আর হালকা সোনালি হওয়া পর্যন্ত 2 মিনিট রান্না করুন।","গরম স্টক অল্প অল্প করে ফেটিয়ে দিন, তারপর সয়া, ওরচেস্টারশায়ার, রসুন ও গোলমরিচ দিন, আর মসৃণ ও চকচকে হওয়া পর্যন্ত 5 মিনিট ফোটান।","তেল 190C তাপে গরম করুন, আর চিপস আবার ব্যাচে 2 থেকে 3 মিনিট ভাজুন যতক্ষণ না গাঢ় সোনালি ও খুব মচমচে হয়। ছেঁকে সঙ্গে সঙ্গে লবণ দিন।","গরম চিপস গরম বাটিতে স্তূপ করুন, উপরে পনিরের ছানা ছড়িয়ে দিন, আর ছানা ঘরের তাপমাত্রায় রাখুন যাতে গলে যাওয়ার বদলে নরম হয়।","টগবগে গরম গ্রেভি উপরে ঢালুন, যাতে ফাঁকে ঢুকে ছানা গলতে শুরু করে।","কাঁটাচামচ দিয়ে সঙ্গে সঙ্গে পরিবেশন করুন, পছন্দ হলে উপরে পেঁয়াজকলি ছড়িয়ে, আর গরম থাকতে খান।"],"tip":"ঘরের তাপমাত্রায় পনিরের ছানা ব্যবহার করুন। ঠান্ডা ছানা শক্ত থাকে আর নরম হয় না, আর ঘরের তাপমাত্রার ছানা গরম গ্রেভির নিচে নরম ও কিচকিচে হয়।","notes":["ময়দাযুক্ত আলু সবচেয়ে ফুলো চিপস বানায়। মোমযুক্ত আলু ঘন থাকে আর একইভাবে মচমচে হয় না।","পনিরের ছানা টাটকা ও কিচকিচে হওয়া উচিত। ছানা না পেলে টাটকা মোজারেলার টুকরো ব্যবহার করুন, যদিও কিচকিচে ভাব থাকবে না।","গ্রেভি বয়ে যাওয়ার মতো পাতলা হওয়া উচিত, ঝোলের মতো ঘন নয়। ঠান্ডা হলে ঘন হয়, তাই খুব গরম পরিবেশন করুন।","দুবার ভাজাই টেকসই মচমচে চিপসের গোপন কথা। প্রথম ভাজা ভেতরটা রান্না করে, দ্বিতীয় ভাজা বাইরেটা মচমচে করে।"],"variations":["টানা শূকর দিয়ে: আরও ভরাট প্রধান পদের জন্য ধীরে রান্না করা টানা শূকর ও বাড়তি গ্রেভি দিয়ে উপরে দিন।","মাশরুম দিয়ে: গ্রেভিতে ভাজা মাশরুম ও থাইম দিন, আর নিরামিষ সংস্করণের জন্য সবজির স্টক ব্যবহার করুন।","সকালের খাবারের পাউটিন: উপরে একটা ভাজা ডিম দিন, আর পাশে বেকন দিয়ে পরিবেশন করুন।"],"serving":"নাস্তা, পাশের পদ, বা ভাগ করে খাওয়ার প্রধান পদ হিসেবে, গভীর বাটিতে কাঁটাচামচ দিয়ে 4 জনের জন্য যথেষ্ট। গ্রেভি ঢালার মুহূর্তেই পরিবেশন করুন, চিপস মচমচে ও ছানা নরম হওয়ার সময়, আর বসিয়ে রাখবেন না, কারণ চিপস দ্রুত নরম হয়। পাউটিন অনানুষ্ঠানিক খাবার, তাই টেবিলের মাঝখানে পরিবেশন করুন, আরও চাইলে জগে বাড়তি গ্রেভি দিয়ে।","storage":"পাউটিন টাটকা খাওয়াই সেরা আর একবার সাজানোর পর ভালো গরম করা যায় না, কারণ চিপস নরম হয়ে যায়। উপাদানগুলো আলাদা রাখুন, চিপস, ছানা ও গ্রেভি, ফ্রিজে 2 দিন পর্যন্ত। চিপস মচমচে হওয়া পর্যন্ত গরম ওভেনে গরম করুন, গ্রেভি ফুটতে থাকা পর্যন্ত গরম করুন, আর টাটকা সাজান। একা গ্রেভি 1 মাস ভালো ফ্রিজ হয়।","mistakes":["ঠান্ডা পনিরের ছানা ব্যবহার করা। শক্ত থাকে আর ফ্রেঞ্চ ফ্রাইয়ে গলে না।","কুসুম গরম গ্রেভি ঢালা। ছানা নরম করে না, তাই গ্রেভি বাষ্প ওঠা পর্যন্ত গরম করুন।","চিপস শুধু একবার ভাজা। কয়েক মিনিটে গ্রেভির নিচে নরম হয়ে যায়, তাই দুবার ভাজুন।","দ্বিতীয় ভাজার আগে চিপসে লবণ দেওয়া। লবণ জল বের করে আর মচমচে হতে বাধা দেয়, তাই শুধু শেষে লবণ দিন।"],"faq":[["পনিরের ছানা কী?","হালকা চাপ দেওয়া টাটকা ছানার টুকরো, কামড় দিলে কিচকিচে গঠন। এটাই পাউটিনের নির্ধারক উপকরণ।"],["জমাট চিপস ব্যবহার করা যাবে?","হ্যাঁ। ওভেন বা এয়ার ফ্রায়ারে খুব মচমচে হওয়া পর্যন্ত রান্না করুন, তারপর গরম গ্রেভি ও ছানা দিয়ে সাজান। টাটকা চিপস দুবার ভাজা ভালো, তবে জমাট চিপসও চলে।"],["পাউটিন কি নিরামিষ?","সবজির স্টক ও নিরামিষ ওরচেস্টারশায়ার সস দিয়ে হতে পারে। ঐতিহ্যবাহী গ্রেভিতে গরুর স্টক ব্যবহার করা হয়, তাই আপনার ব্যবহৃত স্টক দেখে নিন।"],["গ্রেভি কি আগে বানানো যায়?","হ্যাঁ। 3 দিন আগে পর্যন্ত বানিয়ে, ফ্রিজে রাখুন, আর চিপসের উপর ঢালার আগে ফুটতে থাকা পর্যন্ত গরম করুন।"]]},"bobotie":{"intro":"বোবোটি দক্ষিণ আফ্রিকার প্রিয় বেক করা কিমার পদ, যার শিকড় কেপ মালয় রান্নায়, যেখানে মসলাদার কিমা ফল দিয়ে মিষ্টি করা হয়, ভেজানো রুটি দিয়ে সমৃদ্ধ করা হয়, আর তেজপাতা দিয়ে সোনালি ডিমের কাস্টার্ডের তলায় বেক করা হয়। স্বাদ উষ্ণ ও আলতো মিষ্টি, কারি গুঁড়ো, হলুদ, চাটনি, কিশমিশ ও এপ্রিকট সব একসঙ্গে কাজ করে, আর গঠন নরম ও আরামদায়ক, ঝাল বেক ও হালকা মিটলোফের মাঝামাঝি কোথাও। হলুদ ভাত, চাটনি ও সাধারণ সালাদ দিয়ে পরিবেশন করুন, আর মিষ্টি ও ঝালের ভারসাম্যকে কথা বলতে দিন। এটা ভিড়ের জন্য আদর্শ আগে বানানো পদ, কারণ সুন্দরভাবে গরম হয় আর পরের দিন আরও ভালো স্বাদ হয়।","ing":["গরু বা খাসির কিমা 750 গ্রাম","পেঁয়াজ 1টি","রসুন 2 কোয়া","আদা 1 চা চামচ","কারি গুঁড়ো 2 টেবিল চামচ","হলুদ 1 চা চামচ","সাদা রুটি 2 ফালি","দুধ 250 মিলি","ডিম 3টি","তেজপাতা 4টি","চাটনি 3 টেবিল চামচ","কিশমিশ 3 টেবিল চামচ","শুকনো এপ্রিকট 4টি (কাটা)","লেবুর রস 1 টেবিল চামচ","বাদাম 2 টেবিল চামচ (ফালি করা)","লবণ","গোলমরিচ"],"steps":["রুটি দুধের 125 মিলিতে নরম হওয়া পর্যন্ত ভিজিয়ে রাখুন, তারপর বাড়তি দুধ চিপে ফেলে রুটি ভেঙে নিন।","পেঁয়াজ, রসুন ও আদা তেলে নরম হওয়া পর্যন্ত 5 মিনিট ভাজুন, তারপর কারি গুঁড়ো ও হলুদ দিন আর 1 মিনিট ভাজুন।","কিমা দিন আর ভাজুন, ভেঙে, সব জায়গায় বাদামি হয়ে তরল রান্না হয়ে যাওয়া পর্যন্ত।","ভেজানো রুটি, চাটনি, কিশমিশ, এপ্রিকট, লেবুর রস ও মসলা নাড়ুন, আর 5 মিনিট রান্না করুন। স্বাদ দেখুন আর মিষ্টি টক ভারসাম্য ঠিক করুন।","কিমা মাখন দেওয়া বেকিং পাত্রে চামচ দিয়ে দিন, সমানভাবে চেপে দিন, আর তেজপাতা উপরে গুঁজে দিন।","বাকি দুধ 2টি ডিম ও এক চিমটি লবণের সঙ্গে ফেটিয়ে নিন, আর কিমার উপর আলতো করে ঢেলে দিন।","180C তাপে 35 থেকে 40 মিনিট বেক করুন, যতক্ষণ না উপরটা জমাট ও সোনালি হয়, আর কিনারাগুলো টগবগ করে।","10 মিনিট রেখে দিন, ফালি করা বাদাম ছড়িয়ে দিন, আর হলুদ ভাত ও বাড়তি চাটনি দিয়ে পরিবেশন করুন।"],"tip":"বেক করার আগে কিমার স্বাদ দেখুন। মিষ্টি, টক ও ঝালের ভারসাম্য এই পর্যায়ে ঠিক হতে হবে, কারণ বেক করা সেটা ঠিক করবে না।","notes":["ভেজানো রুটি কিমা নরম ও হালকা রাখে। সেটা ছাড়া বোবোটি ঘন ও শুকনো হয়ে যেতে পারে।","কারি গুঁড়ো অনেক আলাদা হয়। পারলে মৃদু কেপ মালয় ধাঁচের কারি গুঁড়ো ব্যবহার করুন, আর স্বাদ দেখার পরই আরও দিন।","চাটনি মিষ্টি ও টক যোগ করে। ফলের চাটনি ঐতিহ্যবাহী, আর আমের চাটনিও ভালো কাজ করে।","তেজপাতা উপরে যায়, মেশানো হয় না, যাতে কাস্টার্ডে স্বাদ দেয় আর পরিবেশনের সময় সুন্দর দেখায়।"],"variations":["ডাল দিয়ে: একই মসলা দিয়ে হালকা সংস্করণের জন্য অর্ধেক কিমার বদলে রান্না করা বাদামি ডাল ব্যবহার করুন।","নিরামিষ বোবোটি: একই ফল, চাটনি ও ডিমের উপর দিয়ে ডাল ও মাশরুম ব্যবহার করুন।","বেশি ঝাল সংস্করণ: পেঁয়াজের সঙ্গে 1টি কাটা টাটকা লঙ্কা দিন, আর পাশে বাড়তি চাটনি ও সাম্বাল দিয়ে পরিবেশন করুন।"],"serving":"হলুদ ভাত, ফলের চাটনি ও মচমচে সবুজ সালাদ বা কাটা টমেটো ও পেঁয়াজের সালাদ দিয়ে 6 জনের জন্য যথেষ্ট। সরাসরি বেকিং পাত্র থেকে, উদার বর্গাকারে, সোনালি উপর ও প্রতিটি ভাগে একটি তেজপাতা দিয়ে পরিবেশন করুন। বোবোটি পারিবারিক পদ, তাই পাত্রটা টেবিলের মাঝখানে রাখুন, ভাত ও চাটনি পাশে রেখে, আর সবাইকে নিজে নিজে পরিবেশন করতে দিন।","storage":"বোবোটি ঢেকে ফ্রিজে 3 দিন পর্যন্ত থাকে, আর 160C ওভেনে পুরোপুরি গরম হওয়া পর্যন্ত ভালো গরম হয়। 3 মাস পর্যন্ত ভালো ফ্রিজ হয়, ফ্রিজে সারারাত গলিয়ে নিন। ডিমের উপরটা গরম করলে একটু জল ছাড়তে পারে, তাই আলতো করে আর ফয়েল দিয়ে ঢেকে গরম করুন। হলুদ ভাত আলাদাভাবে 2 দিন থাকে।","mistakes":["খুব চর্বিহীন কিমা রুটি ছাড়া ব্যবহার করা। শুকনো ও ঝুরঝুরে হয়ে যায়, তাই ভেজানো রুটি ভেতরে রাখুন।","উপরটা বেশি বেক করা। রাবারের মতো হয়ে যায়, তাই জমাট ও সোনালি হওয়ার সঙ্গে সঙ্গেই বের করে নিন।","বিশ্রাম বাদ দেওয়া। বোবোটি গরম কাটলে ভেঙে যায়, তাই পরিবেশনের আগে 10 মিনিট রেখে দিন।","খুব মিষ্টি বানানো। কিমার স্বাদ দেখুন, আর চাটনি ও ফলের ভারসাম্য আরও চিনি দিয়ে নয়, লেবুর রস দিয়ে করুন।"],"faq":[["বোবোটি কি আগে বানানো যায়?","হ্যাঁ। পুরোপুরি সাজিয়ে, 1 দিন পর্যন্ত ফ্রিজে রাখুন, আর দরকার হলে বেক করুন, বেক করার সময় 10 মিনিট যোগ করে।"],["বোবোটি কি ঝাল?","উষ্ণ মসলাদার, ঝাল নয়। কারি গুঁড়ো স্বাদ দেয়, আর ফল ও চাটনি নরম রাখে।"],["হলুদ ভাত কী?","দক্ষিণ আফ্রিকায় বোবোটির সঙ্গে পরিবেশন করা হলুদ, কিশমিশ ও কখনও দারুচিনি দিয়ে রান্না করা ভাত। সাদা ভাতও চলে।"],["খাসির কিমা ব্যবহার করা যাবে?","হ্যাঁ। খাসি আরও সমৃদ্ধ বোবোটি বানায়। বাদামি করার পর বাড়তি চর্বি ছেঁকে নিন, যাতে বেক তেলতেলে না হয়।"]]},"moussaka":{"intro":"মুসাকা গ্রিসের মহান স্তরযুক্ত বেক, নরম বেগুন, দারুচিনির গন্ধযুক্ত সমৃদ্ধ টমেটো ও খাসি বা গরুর কিমার সস, আর ঘন বেচামেলের উপর যা ওভেনে সোনালি হয়। একটু সময় লাগে, কারণ পদ সাজানোর আগে প্রতিটি স্তর আলাদা রান্না করা হয়, তবে সেটাই এর কাঠামো ও স্বাদ দেয়, আর সবচেয়ে ভালো আগে বানিয়ে রেখে দেওয়া হয়, যাতে স্তরগুলো বসে আর পরিষ্কারভাবে কাটা যায়। গরম পরিবেশন করুন, বর্গাকারে, সাধারণ সালাদ দিয়ে, আর বিশ্রামের সময়ে তাড়াহুড়ো করবেন না। এটা রবিবারের পদ, উদার ও আরামদায়ক, আর টেবিলকে খুশিভাবে খাওয়ায়।","ing":["বেগুন 2টি বড় (কাটা)","আলু 3টি (কাটা, ঐচ্ছিক)","খাসি বা গরুর কিমা 600 গ্রাম","পেঁয়াজ 1টি","রসুন 3 কোয়া","টমেটো 400 গ্রাম (কাটা)","টমেটো বাটা 2 টেবিল চামচ","দারুচিনি 1 চা চামচ","ওরেগানো 1 চা চামচ","জায়ফল","দুধ 500 মিলি","মাখন 50 গ্রাম","ময়দা 50 গ্রাম","ডিম 2টি","পনির 80 গ্রাম (কাটা)","কেফালোটিরি বা পারমেসান"],"steps":["বেগুনের ফালিতে লবণ দিন আর 30 মিনিট রেখে দিন, তারপর মুছে শুকিয়ে নিন আর সোনালি ও নরম হওয়া পর্যন্ত ভাজুন বা রোস্ট করুন। সরিয়ে রাখুন।","ব্যবহার করলে আলুর ফালি সবে নরম হওয়া পর্যন্ত সেদ্ধ বা রোস্ট করুন, আর সরিয়ে রাখুন।","পেঁয়াজ ও রসুন নরম হওয়া পর্যন্ত ভাজুন, কিমা দিন, আর ভেঙে ভালো করে বাদামি করুন।","টমেটো বাটা, কাটা টমেটো, দারুচিনি, ওরেগানো ও মসলা দিন, আর ঘন হওয়া পর্যন্ত 20 মিনিট ফোটান।","মাখন গলিয়ে, ময়দা নেড়ে, আর গরম দুধ ঘন ও মসৃণ হওয়া পর্যন্ত ফেটিয়ে বেচামেল বানান। একটু ঠান্ডা করুন, তারপর ডিম ও অর্ধেক পনির ফেটিয়ে দিন।","মাখন দেওয়া বেকিং পাত্রে আলু, তারপর বেগুন, তারপর কিমার সস স্তরে স্তরে সাজান, একবার আবার করুন, আর বেচামেল দিয়ে শেষ করুন।","বাকি পনির ও একটু জায়ফল ছড়িয়ে দিন, আর 180C তাপে 40 থেকে 45 মিনিট বেক করুন যতক্ষণ না সোনালি ও টগবগ করে।","কাটার আগে 20 মিনিট রেখে দিন, যাতে স্তরগুলো বসে, আর সালাদ দিয়ে গরম পরিবেশন করুন।"],"tip":"কাটার আগে মুসাকা রেখে দিন। ওভেন থেকে গরম অবস্থায় ভেঙে যায়, রেখে দিলে পরিষ্কার, সুন্দর স্তরে কাটা যায়।","notes":["বেগুনে লবণ দিলে তেতো জল বেরিয়ে যায় আর বেশি তেল শোষণ বন্ধ হয়। ভাজার আগে মুছে শুকিয়ে নিন।","দারুচিনি গ্রিক কিমার সসে স্বাক্ষর মসলা। হালকা ব্যবহার করুন, যাতে মিষ্টি স্বাদ না দিয়ে সসকে উষ্ণ করে।","বেচামেল উপরে বসার মতো ঘন হতে হবে। পাতলা হলে কিমার মধ্যে ডুবে যায়, তাই চামচ ঢেকে ফেলা পর্যন্ত রান্না করুন।","পনির মিহি করে কাটুন যাতে বেচামেলে সমানভাবে গলে আর উপরে সুন্দরভাবে বাদামি হয়।"],"variations":["নিরামিষ মুসাকা: কিমার বদলে ডাল ও মাশরুম ব্যবহার করুন, একই মসলা ও বেচামেল রেখে।","জুকিনি দিয়ে: বেগুনের সঙ্গে বাড়তি সবজির জন্য ভাজা জুকিনির ফালির স্তর দিন।","হালকা সংস্করণ: বেগুন ভাজার বদলে রোস্ট করুন, আর বেচামেলের জন্য আধা স্কিমড দুধ ব্যবহার করুন।"],"serving":"উদার বর্গাকারে, টমেটো, শসা, পেঁয়াজ ও জলপাইয়ের সাধারণ গ্রিক সালাদ, আর পাশে শক্ত রুটি দিয়ে 6 জনের জন্য যথেষ্ট। গরম পরিবেশন করুন, টগবগে গরম নয়, যাতে স্বাদ বসে যায় আর স্তরগুলো ধরে থাকে। মুসাকা ভাগ করে খাওয়ার পদ, তাই বেকিং পাত্র টেবিলে আনুন, আর আরও চাইলে বাড়তি সালাদ ও রুটি দিয়ে পরিবেশন করুন।","storage":"মুসাকা ঢেকে ফ্রিজে 3 দিন পর্যন্ত থাকে, আর 160C ওভেনে পুরোপুরি গরম হওয়া পর্যন্ত ভালো গরম হয়। ভাগে ভাগে 3 মাস পর্যন্ত ভালো ফ্রিজ হয়, ফ্রিজে সারারাত গলিয়ে নিন। উপরটা বেশি বাদামি না হওয়ার জন্য ফয়েল দিয়ে ঢেকে গরম করুন। পুরো পদ মাইক্রোওয়েভ করবেন না, বেচামেল আলাদা হয়ে যেতে পারে।","mistakes":["বেগুনে লবণ দেওয়া বাদ দেওয়া। তেতো থাকে আর তেল শুষে নেয়, বেক তেলতেলে করে।","পাতলা বেচামেল বানানো। ডুবে যায় আর উপরটা কখনও সোনালি জমাট হয় না।","খুব তাড়াতাড়ি কাটা। স্তরগুলো সরে যায়, তাই অন্তত 20 মিনিট রেখে দিন।","কিমার সস কম রান্না করা। জলীয় সস বেক ভেজা করে, তাই ঘন হওয়া পর্যন্ত ফোটান।"],"faq":[["মুসাকা কি আগে বানানো যায়?","হ্যাঁ, আর আগে বানানোই ভালো। সাজিয়ে নিন, 1 দিন পর্যন্ত ফ্রিজে রাখুন, আর দরকার হলে বেক করুন, 10 মিনিট যোগ করে।"],["খাসির বদলে কি গরুর মাংস ব্যবহার করা যায়?","হ্যাঁ। গরুর মাংস মৃদু মুসাকা বানায়। খাসি ঐতিহ্যবাহী ও সমৃদ্ধ, তাই পছন্দেরটা বেছে নিন।"],["মুসাকা কি গ্লুটেনমুক্ত?","লেখা অনুযায়ী নয়, বেচামেলের ময়দার কারণে। বেচামেলের জন্য গ্লুটেনমুক্ত ময়দার মিশ্রণ ব্যবহার করুন, আর আপনার স্টক দেখে নিন।"],["আমার বেচামেল ডেলাযুক্ত হলো কেন?","দুধ খুব দ্রুত দেওয়া হয়েছিল, বা ময়দা রান্না হয়নি। অনবরত ফেটান, গরম দুধ ধীরে দিন, আর মসৃণ হওয়া পর্যন্ত রান্না করুন।"]]},"hummus":{"intro":"ভালো হামুস পুরোটাই গঠন নিয়ে, রেশমের মতো, হালকা ও ফেটানো, কখনও দানাদার বা ভারী নয়। এটা লেভান্ট থেকে এসেছে, যেখানে ছোলা, তাহিনি, লেবু ও রসুন বরফের জল দিয়ে মেশানো হয় যতক্ষণ না ডিপ ফ্যাকাসে ও ফুলো হয়, তারপর জলপাই তেল, পাপরিকা ও গোটা ছোলা দিয়ে শেষ করা হয়। গোপন কথা হলো তাহিনি আগে, একা, পুরোপুরি মসৃণ হওয়া পর্যন্ত মেশানো, আর সবচেয়ে মসৃণ ফলের জন্য গরম ছোলা, বা খোসা ঘষে ফেলা ছোলা ব্যবহার করা। মেজে প্লেটের অংশ হিসেবে, গরম পিটা, জলপাই ও সালাদ দিয়ে পরিবেশন করুন, আর সবাইকে চামচ দিয়ে তুলে ভাগ করে খেতে দিন।","ing":["ছোলা 400 গ্রাম (রান্না করা, ছেঁকে নেওয়া)","তাহিনি 120 গ্রাম (ভালো করে নাড়া)","লেবুর রস 3 টেবিল চামচ","রসুন 1 ছোট কোয়া","বরফের জল 4 থেকে 6 টেবিল চামচ","জলপাই তেল 2 টেবিল চামচ (সঙ্গে পরিবেশনের জন্য আরও)","লবণ 1 চা চামচ","জিরা 1/2 চা চামচ (ঐচ্ছিক)","পরিবেশনের জন্য পাপরিকা","পার্সলে","পরিবেশনের জন্য গরম পিটা রুটি"],"steps":["কৌটোর ছোলা ব্যবহার করলে, তরলে 5 মিনিট গরম করুন, ছেঁকে নিন, আর একটু তরল রেখে দিন। সময় থাকলে আলগা খোসা ঘষে ফেলুন।","তাহিনি, লেবুর রস, রসুন ও লবণ 2 মিনিট মেশান যতক্ষণ না খুব মসৃণ, ফ্যাকাসে ও একটু ফুলো হয়।","গরম ছোলা দিন আর পাশ চেঁছে, পুরোপুরি মসৃণ হওয়া পর্যন্ত 3 থেকে 4 মিনিট মেশান।","বরফের জল একবারে এক টেবিল চামচ করে দিন, প্রতিবার মেশান, যতক্ষণ না হামুস হালকা, ফেটানো ও চামচ দিয়ে তোলার মতো নরম হয়।","লেবু, লবণ ও রসুনের স্বাদ দেখুন আর ঠিক করুন। তাহিনির স্বাদসহ উজ্জ্বল ও নোনতা হওয়া উচিত, তীক্ষ্ণ নয়।","অগভীর বাটিতে চামচ দিয়ে দিন, চামচের পেছন দিয়ে উপরটা ঘূর্ণি করুন, আর জলপাই তেল ছিটিয়ে দিন।","উপরে কয়েকটা গোটা ছোলা, এক চিমটি পাপরিকা ও কাটা পার্সলে দিন।","ঘরের তাপমাত্রায় গরম পিটা, সবজির কাঠি ও জলপাই দিয়ে পরিবেশন করুন।"],"tip":"ছোলার আগে তাহিনি মেশান। একা মেশানো তাহিনি ফ্যাকাসে ও ক্রিমের মতো হয়, আর সেটাই হামুসকে রেশমের মতো করে।","notes":["তাহিনির মান সবচেয়ে গুরুত্বপূর্ণ। খোসা ছাড়ানো তিলের বীজ দিয়ে বানানো, তরল, ভালো করে নাড়া তাহিনি ব্যবহার করুন। ঘন, শুকনো তাহিনি ভারী হামুস বানায়।","বরফের জল হামুসে বাতাস ফেটিয়ে দেয় আর তেল না দিয়ে পাতলা করে। ধীরে দিন, নইলে হামুস তরল হয়ে যায়।","রসুন ছোট ও টাটকা হওয়া উচিত। একটা বড় কাঁচা কোয়া পুরো বাটিকে ছাপিয়ে যেতে পারে, তাই ছোট দিয়ে শুরু করুন।","গরম ছোলা ঠান্ডা ছোলার চেয়ে মসৃণভাবে মেশে, কারণ এগুলোর স্টার্চ নরম। ঠান্ডা ছোলা ব্যবহার করলে আগে গরম করুন।"],"variations":["ভাজা লাল মরিচের হামুস: 1টি ভাজা লাল মরিচ মেশান, আর লেবু একটু কমিয়ে দিন।","বিটরুটের হামুস: রং ও মিষ্টির জন্য 1টি ছোট রান্না করা বিটরুট মেশান, সুন্দর গোলাপি সংস্করণ।","ঝাল হামুস: তাহিনির সঙ্গে 1 চা চামচ হারিসা বা লঙ্কার বাটা দিন, আর উপরে লঙ্কার তেল দিন।"],"serving":"মেজে প্লেটের অংশ হিসেবে, গরম পিটা, জলপাই, আচার, সালাদ ও অন্যান্য ডিপ দিয়ে 6 জনের জন্য যথেষ্ট। হামুস চওড়া অগভীর বাটিতে পরিবেশন করুন, ঘূর্ণিতে জলপাই তেল জমা রেখে, আর সবাইকে পিটা ছিঁড়ে চামচ দিয়ে তুলতে দিন। এটা স্যান্ডউইচের মাখন হিসেবে, ভাজা সবজির ভিত্তি হিসেবে, বা গ্রিল করা মাংস ও ফালাফেলের পাশের পদ হিসেবেও চমৎকার।","storage":"হামুস বায়ুরোধী পাত্রে, উপরে জলপাই তেলের পাতলা স্তর দিয়ে ফ্রিজে 4 দিন পর্যন্ত থাকে। পরিবেশনের আগে ঘরের তাপমাত্রায় ফিরিয়ে আনুন, আর ভালো করে নাড়ুন। 3 মাস পর্যন্ত ভালো ফ্রিজ হয়, ফ্রিজে সারারাত গলিয়ে নিন, তারপর আবার মসৃণ করে ফেটিয়ে নিন। ঘরের তাপমাত্রায় 2 ঘণ্টার বেশি রেখে দেবেন না।","mistakes":["সবকিছু একসঙ্গে মেশানো। তাহিনি কখনও মসৃণ হয় না, তাই আগে একা মেশান।","ঠান্ডা, শুকনো ছোলা ব্যবহার করা। দানাদারভাবে মেশে, তাই গরম করুন আর বরফের জল ধীরে দিন।","বেশি রসুন দেওয়া। কাঁচা রসুন হামুস বসে থাকলে আরও শক্তিশালী হয়, তাই অল্প ব্যবহার করুন আর স্বাদ দেখুন।","ফ্রিজ থেকে সরাসরি পরিবেশন করা। ঠান্ডা হামুস শক্ত ও ম্লান, তাই আগে গরম হতে দিন।"],"faq":[["শুকনো ছোলা ব্যবহার করা যাবে?","হ্যাঁ। সারারাত ভিজিয়ে রাখুন, এক চিমটি খাবার সোডা দিয়ে খুব নরম হওয়া পর্যন্ত রান্না করুন, আর গরম ব্যবহার করুন। সেগুলো সবচেয়ে মসৃণ হামুস দেয়।"],["আমার হামুস দানাদার কেন?","তাহিনি আগে মেশানো হয়নি, ছোলা ঠান্ডা ছিল, বা খোসা রেখে দেওয়া হয়েছিল। বেশি সময় মেশান আর বরফের জল দিন।"],["তাহিনি ছাড়া কি হামুস বানানো যায়?","যাবে, বাড়তি জলপাই তেল ও একটু তিলের তেল দিয়ে, তবে ক্লাসিক হামুসের মতো স্বাদ হবে না। তাহিনিই পদের হৃদয়।"],["হামুস কি স্বাস্থ্যকর?","এটা ছোলা, তাহিনি, লেবু ও জলপাই তেল দিয়ে বানানো, আর এখানে কোনো সংখ্যা দেওয়া হয়নি। তেল ও লবণই দেখার অংশ, তাই সবজি ও পিটা দিয়ে পরিবেশন করুন।"]]},"falafel":{"intro":"আসল ফালাফেল বানানো হয় কাঁচা ভেজানো ছোলা দিয়ে, কখনও কৌটোর বা রান্না করা ছোলা দিয়ে নয়, আর সেটাই হালকা, ফুলো ভেতর ও মচমচে, এবড়োখেবড়ো খোলস দেয়। ছোলা পেঁয়াজ, রসুন, পার্সলে, ধনেপাতা ও জিরা দিয়ে মোটা করে পিষে নেওয়া হয়, মিশ্রণ একসঙ্গে থাকার জন্য রেখে দেওয়া হয়, তারপর আকৃতি দিয়ে গাঢ় সোনালি হওয়া পর্যন্ত ভাজা হয়। গরম পিটায় সালাদ ও তাহিনি সস দিয়ে পরিবেশন করুন, বা হামুসসহ মেজে প্লেটের অংশ হিসেবে। মিশ্রণ আগে বানিয়ে ঠান্ডা করা যায়, আর ফালাফেল কয়েক মিনিটে ভাজা হয়, তাই প্যান ভরে না ফেললে ভিড়ের জন্য উপযুক্ত।","ing":["শুকনো ছোলা 250 গ্রাম (সারারাত ভেজানো)","পেঁয়াজ 1টি","রসুন 3 কোয়া","পার্সলে 1 বড় গোছা","ধনেপাতা 1 গোছা","জিরা 2 চা চামচ","ধনে গুঁড়ো 1 চা চামচ","বেকিং পাউডার 1/2 চা চামচ","ময়দা 2 টেবিল চামচ","লবণ 1 চা চামচ","কালো গোলমরিচ","লঙ্কার গুঁড়ো","ভাজার জন্য তেল","পিটা","সালাদ","পরিবেশনের জন্য তাহিনি সস"],"steps":["ছোলা প্রচুর ঠান্ডা জলে সারারাত ভিজিয়ে রাখুন, তারপর খুব ভালো করে ছেঁকে নিন। রান্না করবেন না।","ছোলা, পেঁয়াজ, রসুন, ভেষজ, মসলা, লবণ ও গোলমরিচ ফুড প্রসেসরে রাখুন, আর বাটা নয়, মোটা ও ঝুরঝুরে হওয়া পর্যন্ত পালস করুন।","বাটিতে ঢেলে নিন, ময়দা ও বেকিং পাউডার নাড়ুন, ঢেকে দিন, আর শক্ত হওয়ার জন্য 30 মিনিট ফ্রিজে রাখুন।","আগে একটা ফালাফেল পরীক্ষা করুন, ছোট বল আকৃতি দিন, ভাজুন, আর দেখে নিন সেটা একসঙ্গে থাকে আর ভেতর পর্যন্ত রান্না হয়।","বাকিগুলো ভেজা হাতে আখরোটের আকারের ছোট বল বা প্যাটি আকারে বানান।","তেল 175C তাপে গরম করুন, আর ব্যাচে 3 থেকে 4 মিনিট ভাজুন, একবার উল্টে, সব জায়গায় গাঢ় সোনালি ও মচমচে হওয়া পর্যন্ত।","কাগজে নয়, তারের র্যাকে ছেঁকে নিন, যাতে খোলস মচমচে থাকে, আর একটু লবণ ছড়িয়ে দিন।","পিটায় সালাদ, টমেটো, শসা ও তাহিনি সস দিয়ে গরম পরিবেশন করুন, বা হামুসসহ মেজে প্লেটে।"],"tip":"কাঁচা ভেজানো ছোলা ব্যবহার করুন, কখনও রান্না করা ছোলা নয়। রান্না করা ছোলায় নরম, নরম পিণ্ডের ফালাফেল হয় যা তেলে ভেঙে যায়।","notes":["সারারাত ভেজানো অপরিহার্য। কম ভেজানো ছোলা ভেতরে শক্ত থাকে, তাই ঠান্ডা জলে পুরো 12 ঘণ্টা দিন।","পালস করুন, পিউরি করবেন না। ভেষজের দৃশ্যমান টুকরোসহ মোটা গঠন ফালাফেলকে হালকা, ফুলো কামড় দেয়।","মিশ্রণ ঠান্ডা করলে আকৃতি ধরে রাখতে সাহায্য হয়। ভেজা মনে হলে এক চামচ ময়দা দিন, তবে বেশি দেবেন না, নইলে ফালাফেল ভারী হয়ে যায়।","তেলের তাপমাত্রা গুরুত্বপূর্ণ। বেশি ঠান্ডা হলে ফালাফেল তেল শুষে নেয়, বেশি গরম হলে বাইরে বাদামি হয় আর ভেতরে কাঁচা থাকে।"],"variations":["বেক করা ফালাফেল: তেল মাখিয়ে 200C তাপে 20 থেকে 25 মিনিট বেক করুন, একবার উল্টে, হালকা সংস্করণের জন্য।","ব্রড বিন দিয়ে: মিশরীয় ধাঁচের তামেয়ার জন্য অর্ধেক ছোলার বদলে ভেজানো ভাঙা ব্রড বিন ব্যবহার করুন।","ঝাল ফালাফেল: মিশ্রণে 1টি কাটা টাটকা লঙ্কা ও বাড়তি জিরা দিন, আর লঙ্কার সস দিয়ে পরিবেশন করুন।"],"serving":"প্রতিজনকে 4 থেকে 5টি ফালাফেল, গরম পিটায় সালাদ ও তাহিনি দিয়ে, বা মেজে প্লেটের অংশ হিসেবে 4 জনের জন্য যথেষ্ট। তেল থেকে বেরোনোর মুহূর্তেই পরিবেশন করুন, খোলস মচমচে ও ভেতরটা গরম ও ফুলো থাকতে, পাশে লেবুর ফালি ও বাড়তি তাহিনি দিয়ে। ফালাফেল হাতের খাবার, তাই প্রচুর পিটা, সালাদ ও সস সাজিয়ে রাখুন, আর সবাইকে নিজেরটা বানাতে দিন।","storage":"রান্না না করা ফালাফেলের মিশ্রণ ঢেকে ফ্রিজে 2 দিন পর্যন্ত থাকে। রান্না করা ফালাফেল ফ্রিজে 2 দিন থাকে, আর প্রায় 8 মিনিট গরম ওভেনে মচমচে হওয়া পর্যন্ত গরম করা যায়। মাইক্রোওয়েভ করবেন না, নরম হয়ে যায়। রান্না না করা আকৃতি দেওয়া ফালাফেল 1 মাস ভালো ফ্রিজ হয়, জমাট অবস্থা থেকে এক মিনিট বেশি ভাজা হয়।","mistakes":["কৌটোর ছোলা ব্যবহার করা। সেগুলো ইতিমধ্যে রান্না করা, তাই ফালাফেল নরম পিণ্ড হয়ে ভেঙে যায়।","মিশ্রণ বেশি প্রসেস করা। মসৃণ বাটায় ঘন, ভারী ফালাফেল হয়, তাই অল্প পালস করুন আর মোটা রাখুন।","খুব ঠান্ডা তেলে ভাজা। ফালাফেল তেল শুষে নেয় আর তেলতেলে হয়, তাই আগে তেল ঠিকমতো গরম করুন।","বেশি বড় আকৃতি দেওয়া। বড় ফালাফেল ভেতরে কাঁচা থাকে, তাই আখরোটের আকারে রাখুন।"],"faq":[["ভাজার বদলে কি ফালাফেল বেক করা যায়?","হ্যাঁ। কম মচমচে, তবে তবু সুস্বাদু। তেল মাখিয়ে, 200C তাপে বেক করুন, আর মাঝপথে একবার উল্টে দিন।"],["আমার ফালাফেল ভেঙে গেল কেন?","মিশ্রণ খুব ভেজা ছিল, বা তেল খুব ঠান্ডা ছিল। মিশ্রণ ঠান্ডা করুন, একটু ময়দা দিন, আর আগে একটা পরীক্ষা করুন।"],["ময়দা দিলে কি কৌটোর ছোলা ব্যবহার করা যায়?","সুপারিশ করা হয় না। ময়দা দিয়েও রান্না করা ছোলায় ঘন ফালাফেল হয়। ভেজানো কাঁচা ছোলা অপরিহার্য।"],["ফালাফেলের সঙ্গে কোন সস যায়?","লেবু ও জল দিয়ে পাতলা করা তাহিনি সস, সঙ্গে পিটায় সালাদ। লঙ্কার সস ও আচারও ঐতিহ্যবাহী।"]]},"feijoada":{"intro":"ফেইজোয়াদা ব্রাজিলের জাতীয় পদ, শূকর, সসেজ ও ধোঁয়াটে মাংসের মিশ্রণ দিয়ে সমৃদ্ধ কালো শিমের ঝোল, ধীরে রান্না করা যতক্ষণ না শিম ক্রিমের মতো হয় আর মাংস নরম হয়। এটা ঐতিহ্যগতভাবে শনিবারে পরিবেশন করা হয়, লম্বা পারিবারিক দুপুরের খাবার হিসেবে, সাদা ভাত, ভাজা কলার্ড শাক, ফারোফা, সেঁকা কাসাভা ময়দা, আর সমৃদ্ধি কাটার জন্য কমলার ফালি দিয়ে। সময় লাগে, আর ভিড়কে খাওয়ায়, তাই বড় হাঁড়ি রান্না করুন, সঙ্গের জিনিস সাধারণ রাখুন, আর খাবারটা লম্বা হতে দিন। শিম সারারাত ভিজিয়ে রাখুন, মাংস ভালো করে বাদামি করুন, আর হাঁড়িকে লম্বা, আলতো ফোটানো দিন, আর ফলাফল গভীরভাবে তৃপ্তিদায়ক।","ing":["শুকনো কালো শিম 500 গ্রাম (সারারাত ভেজানো)","শূকরের কাঁধ 500 গ্রাম (কিউব করে কাটা)","ধোঁয়াটে সসেজ 300 গ্রাম (ফালি করা)","বেকন বা লবণযুক্ত শূকর 200 গ্রাম (কিউব করা)","পেঁয়াজ 1টি","রসুন 4 কোয়া","তেজপাতা 3টি","জিরা 1 চা চামচ","ওরেগানো 1 চা চামচ","কমলা 1টি (পরিবেশনের জন্য)","ভাত","কলার্ড শাক (ফারোফা বা সেঁকা ব্রেডক্রাম্ব পরিবেশনের জন্য, ঐচ্ছিক)"],"steps":["শিম সারারাত ঠান্ডা জলে ভিজিয়ে রাখুন, ছেঁকে নিন, আর ধুয়ে নিন।","শূকর, সসেজ ও বেকন বড় হাঁড়িতে ব্যাচে বাদামি করুন, তারপর সরিয়ে রাখুন, চর্বি হাঁড়িতে রেখে।","একই হাঁড়িতে পেঁয়াজ ও রসুন নরম হওয়া পর্যন্ত ভাজুন, তারপর জিরা ও ওরেগানো দিন।","মাংস হাঁড়িতে ফিরিয়ে দিন, শিম, তেজপাতা দিন আর 3 সেমি ঢেকে যায় এমন পরিমাণ জল দিন।","ফুটতে দিন, ফেনা তুলুন, তারপর খুব আলতো ফোটানো অবস্থায় নামিয়ে আনুন, আংশিক ঢেকে, 2 থেকে 2.5 ঘণ্টা।","মাঝে মাঝে নাড়ুন, দরকার হলে গরম জল দিন, যতক্ষণ না শিম ক্রিমের মতো হয় আর মাংস নরম হয়।","স্বাদ দেখুন আর লবণ ও গোলমরিচ দিয়ে মসলা দিন। মাংস লবণ যোগ করে, তাই আরও দেওয়ার আগে স্বাদ দেখুন।","গভীর বাটিতে সাদা ভাত, ভাজা কলার্ড শাক, ফারোফা ও পাশে কমলার ফালি দিয়ে পরিবেশন করুন।"],"tip":"শিম সারারাত ভিজিয়ে রাখুন আর আলতো করে ফোটান। তাড়াহুড়ো করা শিম শক্ত থাকে, আর জোরে ফোটানো সেগুলোকে ক্রিমের মতো শিমের বদলে নরম পিণ্ডে ভেঙে দেয়।","notes":["কালো শিম অপরিহার্য। সেগুলো ক্রিমের মতো ও গাঢ় হয়, আর পুরো ঝোলকে রং দেয়। কিডনি বিন অন্য পদ বানায়।","মাংসের মিশ্রণ ফেইজোয়াদাকে গভীরতা দেয়। যা পাবেন ব্যবহার করুন, তবে ক্লাসিক স্বাদের জন্য ধোঁয়াটে কিছু রাখুন।","তেজপাতা পরিবেশনের আগে সরিয়ে ফেলা উচিত। সেগুলো ঝোলে স্বাদ দেয়, তবে খেতে সুখকর নয়।","কমলার ফালি সাজানো নয়। এগুলোর অম্লতা শূকর ও শিমের সমৃদ্ধি কাটে, তাই উদারভাবে পরিবেশন করুন।"],"variations":["মুরগি দিয়ে: হালকা সংস্করণের জন্য অর্ধেক শূকরের বদলে মুরগির থাই ব্যবহার করুন, শেষ 45 মিনিটের জন্য দেওয়া।","নিরামিষ ফেইজোয়াদা: একই মসলা রেখে সবজির স্টক দিয়ে মাশরুম, ধোঁয়াটে টোফু ও বাড়তি শিম ব্যবহার করুন।","প্রেসার কুকার সংস্করণ: ভেজানো শিম ও মাংস চাপে 35 মিনিট রান্না করুন, তারপর ঘন করতে 15 মিনিট ঢাকা ছাড়া ফোটান।"],"serving":"লম্বা পারিবারিক দুপুরের খাবার হিসেবে, সাদা ভাত, রসুন দিয়ে ভাজা কলার্ড শাক, ফারোফা ও টেবিলের মাঝখানে কমলার ফালি দিয়ে 8 জনের জন্য যথেষ্ট। প্রত্যেকে ভাতের উপর শিম ও মাংস পরিবেশন করে, শাক ও ফারোফা দেয়, আর তালু সতেজ করতে কামড়ের মাঝে কমলা খায়। ঠান্ডা পানীয় দিয়ে পরিবেশন করুন আর হাঁড়ি চুলায় রাখুন, কারণ দ্বিতীয়বার আশা করা হয়।","storage":"ফেইজোয়াদা ফ্রিজে 4 দিন পর্যন্ত থাকে, আর স্বাদ সারারাত থাকলে আরও ভালো হয়। ঘন হয়ে গেলে একটু জল দিয়ে টগবগ করা পর্যন্ত আলতো করে গরম করুন। ভাগে ভাগে 3 মাস পর্যন্ত খুব ভালো ফ্রিজ হয়, ফ্রিজে সারারাত গলিয়ে নিন। ভাত, শাক ও ফারোফা টাটকা বানানো উচিত, বা আলাদাভাবে 2 দিন রাখা উচিত।","mistakes":["সারারাত ভেজানো বাদ দেওয়া। শিম অনেক বেশি সময় নেয় আর অসমান রান্না হয়।","জোরে ফোটানো। শিম ভেঙে যায় আর ঝোল নরম পিণ্ড হয়, তাই আলতো ফোটানো রাখুন।","লবণ খুব তাড়াতাড়ি দেওয়া। লবণ শিম শক্ত করতে পারে, তাই স্বাদ দেখার পর শেষে ভালো করে মসলা দিন।","সঙ্গের জিনিস ছাড়া পরিবেশন করা। ভাত, শাক, ফারোফা ও কমলা পদের অংশ, বাড়তি নয়।"],"faq":[["কৌটোর কালো শিম ব্যবহার করা যাবে?","হ্যাঁ, ঠেকায়। বাদামি করা মাংসের সঙ্গে শেষ 30 মিনিটের জন্য দিন, আর জল কমিয়ে দিন, তবে ঝোল কম সমৃদ্ধ হবে।"],["ফেইজোয়াদা কি খুব চর্বিযুক্ত?","এটা শূকর ও সসেজ দিয়ে বানানো সমৃদ্ধ ঝোল। হালকা সংস্করণ পছন্দ হলে চর্বিহীন টুকরো ব্যবহার করুন আর বাদামি করার পর বাড়তি চর্বি ছেঁকে নিন।"],["ফারোফা কী?","সেঁকা কাসাভা ময়দা, প্রায়ই পেঁয়াজ ও বেকন দিয়ে, শিম ও ভাতের উপর ছড়িয়ে দেওয়া হয়। সেঁকা ব্রেডক্রাম্ব মোটামুটি বদলি।"],["ফেইজোয়াদা কি আগে বানানো যায়?","হ্যাঁ, আর পরের দিন আরও ভালো। পুরোপুরি রান্না করুন, ঠান্ডা করুন, ফ্রিজে রাখুন, আর আলতো করে গরম করুন।"]]},"meatpie":{"intro":"অসি মিট পাই একটা আইকন, হাতে ধরা, সোনালি আর অস্ট্রেলিয়ার সর্বত্র ফুটবল খেলা, বেকারি ও রান্নাঘরের টেবিলে খাওয়া হয়। মচমচে শর্টক্রাস্ট বেস ও ফ্লেকি পাফ পেস্ট্রির ঢাকনার ভেতরে সমৃদ্ধ গরুর মাংসের পুর, পেঁয়াজ, টমেটো, ওরচেস্টারশায়ার সস ও গভীরতার জন্য একটু ভেজিমাইট দিয়ে ধীরে রান্না করা, পাই কাটলে আকৃতি ধরে রাখার মতো ঘন, তবে উপরে টমেটো সস দরকার এমন রসালো। পুর আগে বানিয়ে পুরোপুরি ঠান্ডা করুন, কারণ গরম পুর পেস্ট্রি গলিয়ে দেয়, তারপর ঢাকনা গাঢ় সোনালি হওয়া পর্যন্ত বেক করুন। গরম পরিবেশন করুন, উপরে টমেটো সস দিয়ে, আর অস্ট্রেলীয় ধাঁচে হাতে খান।","ing":["গরুর চাক 700 গ্রাম (ছোট কিউব করা)","পেঁয়াজ 1টি","রসুন 2 কোয়া","টমেটো বাটা 2 টেবিল চামচ","গরুর স্টক 400 মিলি","ওরচেস্টারশায়ার সস 2 টেবিল চামচ","ভেজিমাইট 1 চা চামচ","ময়দা 2 টেবিল চামচ","থাইম 1 চা চামচ","বেসের জন্য শর্টক্রাস্ট পেস্ট্রি","ঢাকনার জন্য পাফ পেস্ট্রি","ডিম 1টি (ফেটানো, গ্লেজের জন্য)","পরিবেশনের জন্য টমেটো সস","লবণ","গোলমরিচ"],"steps":["গরুর মাংস গরম হাঁড়িতে ব্যাচে বাদামি করুন, তারপর সরিয়ে রাখুন। পেঁয়াজ ও রসুন একই হাঁড়িতে বাদামি করুন।","টমেটো বাটা ও ময়দা দিন, 1 মিনিট রান্না করুন, তারপর বাদামি স্বাদ তুলতে নেড়ে স্টক ঢালুন।","গরুর মাংস ফিরিয়ে দিন, ওরচেস্টারশায়ার, ভেজিমাইট ও থাইম দিন, আর নরম ও ঘন হওয়া পর্যন্ত 60 থেকে 75 মিনিট আলতো করে ফোটান।","পুর পুরোপুরি ঠান্ডা করুন, পারলে ফ্রিজে। গরম পুর পেস্ট্রি গলিয়ে ভেজা করে দেবে।","মাখন দেওয়া পাই টিন বা মাফিন টিন শর্টক্রাস্ট পেস্ট্রি দিয়ে সাজান, ঠান্ডা গরুর মাংসের মিশ্রণ দিয়ে ভরুন, আর কিনারা ডিম দিয়ে মাখান।","পাফ পেস্ট্রির ঢাকনা দিয়ে ঢেকে দিন, বন্ধ করতে কিনারা চাপ দিন, ছেঁটে নিন, আর প্রতিটি ঢাকনায় ছোট বাষ্পের ছিদ্র কাটুন।","ফেটানো ডিম দিয়ে মাখান, আর 200C তাপে 25 থেকে 30 মিনিট বেক করুন, যতক্ষণ না গাঢ় সোনালি ও মচমচে হয়।","5 মিনিট রেখে দিন, টিন থেকে তুলে নিন, আর টমেটো সস দিয়ে গরম পরিবেশন করুন।"],"tip":"পেস্ট্রি ভরার আগে পুর পুরোপুরি ঠান্ডা করুন। একটু গরম পুরও পেস্ট্রি নরম করে আর ওভেনে মচমচে হতে বাধা দেয়।","notes":["গরুর চাক ধীর রান্নায় নরম ও সমৃদ্ধ হয়। চর্বিহীন ঝোলের গরুর মাংস শুকিয়ে যায়, আর কিমা অন্য, নরম পাই বানায়।","ভেজিমাইট নোনতা গভীরতা যোগ করে যা চেনা কঠিন তবে নিঃসন্দেহে অস্ট্রেলীয়। শুধু অল্প ব্যবহার করুন, নইলে পুরকে ছাপিয়ে যাবে।","বেসের জন্য শর্টক্রাস্ট কাঠামো দেয়, ঢাকনার জন্য পাফ পেস্ট্রি ফ্লেক দেয়। দুটোর জন্য পাফ পেস্ট্রি ব্যবহার করলে বেস ভেজা হয়।","ডিমের ধোয়া সোনালি চকচকে ভাব দেয়। বেক করার ঠিক আগে মাখান, আর বাষ্পের ছিদ্রে জমতে দেবেন না।"],"variations":["মাশরুম দিয়ে: বাড়তি স্বাদ ও হালকা পুরের জন্য পেঁয়াজের সঙ্গে কাটা মাশরুম দিন।","মুরগির পাই: মুরগির সংস্করণের জন্য একই সস দিয়ে 40 মিনিট রান্না করা মুরগির থাই ব্যবহার করুন।","পনির ও বেকনের পাই: বেক করার আগে ঠান্ডা পুরে কাটা পনির ও রান্না করা বেকন দিন।"],"serving":"আলাদা পাই হিসেবে, ওভেন থেকে গরম, উপরে টমেটো সস ও পাশে সাধারণ সালাদ বা মটর দিয়ে 6 জনের জন্য যথেষ্ট। মিট পাই হাতের খাবার, তাই প্লেটে পরিবেশন করুন, কাছাকাছি কাঁটাচামচ রেখে, তবে গরম থাকতে হাতে খেতে উৎসাহ দিন। দুপুরের খাবার, পিকনিক, আর খেলা দেখার জন্য উপযুক্ত, টেবিলে বাড়তি টমেটো সস দিয়ে।","storage":"রান্না করা পাই ঢেকে ফ্রিজে 3 দিন পর্যন্ত থাকে, আর 180C ওভেনে গরম ও মচমচে হওয়া পর্যন্ত, প্রায় 15 মিনিট গরম করা যায়। বেক করা বা না বেক করা অবস্থায় 3 মাস পর্যন্ত ভালো ফ্রিজ হয়, ফ্রিজে সারারাত গলিয়ে নিন। একা পুর ফ্রিজে 3 দিন থাকে আর 3 মাস ফ্রিজ হয়। মচমচে খোলস চাইলে পাই মাইক্রোওয়েভ করবেন না।","mistakes":["গরম থাকতে পেস্ট্রি ভরা। পেস্ট্রি গলে ভেজা হয়ে যায়, তাই পুর পুরোপুরি ঠান্ডা করুন।","বেস কম বেক করা। নিচটা ফ্যাকাসে ও নরম থাকে, তাই ঢাকনা গাঢ় সোনালি হওয়া ও বেস জমাট হওয়া পর্যন্ত বেক করুন।","বাষ্পের ছিদ্র ভুলে যাওয়া। বাষ্প জমে ঢাকনা ফাটিয়ে দেয়, তাই প্রতিটি পাইয়ে ছোট ছিদ্র কাটুন।","পুর খুব পাতলা বানানো। কাটলে বেরিয়ে যায়, তাই চামচে স্তূপ হওয়ার মতো ঘন হওয়া পর্যন্ত ফোটান।"],"faq":[["দোকান থেকে কেনা পেস্ট্রি ব্যবহার করা যাবে?","হ্যাঁ। ভালো মানের শর্টক্রাস্ট ও পাফ পেস্ট্রি ভালো কাজ করে, আর অনেক সময় বাঁচায়। ব্যবহারের আগে পর্যন্ত ঠান্ডা রাখুন।"],["তার বদলে কি একটা বড় পাই বানানো যায়?","হ্যাঁ। 20 সেমি পাই ডিশ ব্যবহার করুন, শর্টক্রাস্ট দিয়ে সাজান, ভরুন, পাফ পেস্ট্রি দিয়ে ঢেকে দিন, আর 40 থেকে 45 মিনিট বেক করুন।"],["ভেজিমাইট কীসের জন্য?","এটা পুরে নোনতা, ইস্টের গভীরতা যোগ করে। না পেলে একটু বাড়তি ওরচেস্টারশায়ার সস ও এক চিমটি লবণ ব্যবহার করুন।"],["মিট পাই কি ফ্রিজ করা যায়?","হ্যাঁ, বেক করা বা না বেক করা, 3 মাস পর্যন্ত। জমাট অবস্থা থেকে বেক করুন, পুরোপুরি গরম হওয়া পর্যন্ত 10 থেকে 15 মিনিট যোগ করে।"]]},"haleem":{"intro":"হালিম সবচেয়ে সত্যিকার অর্থে ধীর রান্নার খাবার, ধৈর্যের এমন একটি পদ যা ঘণ্টার পর ঘণ্টা রান্নার পুরস্কার হিসেবে ঘন, মসৃণ হালুয়া আর রেস্তা নামের বিখ্যাত আঁশযুক্ত গঠন দেয়। গম, বার্লি ও চার ধরনের ডাল সারারাত ভিজিয়ে রাখা হয়, তারপর পুরোপুরি নরম হওয়া পর্যন্ত রান্না করা হয়, আর গরুর মাংস আলাদাভাবে রান্না করা হয় যতক্ষণ না তা সূক্ষ্ম আঁশ হয়ে ছিঁড়ে যায়। তারপর দুটো একসঙ্গে মিশিয়ে ঐতিহ্যবাহী ঘোটায় মথা হয়, যতক্ষণ না দানা আর মাংস এক হয়ে যায়। হালিমের শিকড় আরবি পদ হারিসে, যা মুঘল যুগে হায়দরাবাদে এসেছিল এবং শতাব্দী ধরে আজকের পাকিস্তানজুড়ে প্রিয় সমৃদ্ধ পদে রূপ নিয়েছে। এটি রমজানের রাত, মুহাররমের জমায়েত ও বড় পারিবারিক সপ্তাহান্তের খাবার, ভাজা পেঁয়াজ, আদা, কাঁচা মরিচ, লেবু ও চাট মশলা দিয়ে গরম পরিবেশন করা হয়।","ing":["গম (গন্দুম) 1 কাপ (সারারাত ভেজানো)","বার্লি (জৌ) ½ কাপ (সারারাত ভেজানো)","ছোলার ডাল ½ কাপ","মসুর ডাল ¼ কাপ","মুগ ডাল ¼ কাপ","মাশ ডাল ¼ কাপ","গরুর মাংস 1 কেজি","গরুর হাড় 250 গ্রাম","ঘি বা তেল 1 কাপ","পেঁয়াজ 2টি বড় (পাতলা করে কাটা)","আদা বাটা 2 টেবিল চামচ","রসুন বাটা 2 টেবিল চামচ","দই 1 কাপ (ফেটানো)","লাল মরিচ গুঁড়া 2 টেবিল চামচ","কাশ্মীরি মরিচ গুঁড়া 1 টেবিল চামচ","ধনে গুঁড়া 1½ টেবিল চামচ","হলুদ গুঁড়া 1 চা চামচ","হালিম মশলা 2 টেবিল চামচ","লবণ 2 টেবিল চামচ","জিরা 1 টেবিল চামচ","গোলমরিচ 1 চা চামচ","লবঙ্গ 6 থেকে 8টি","সবুজ এলাচ 5টি","কালো এলাচ 2টি","দারুচিনি 2টি","জায়ফল ফুল 2টি","জায়ফল ¼ টুকরা","তারকা মৌরি 1টি","ঘি ½ কাপ","পেঁয়াজ 1টি মাঝারি (পাতলা করে কাটা, তরকার জন্য)","আদা 2 টেবিল চামচ (সরু করে কাটা)","তাজা ধনেপাতা ½ কাপ (কুচি করা)","তাজা পুদিনা ½ কাপ (কুচি করা)","কাঁচা মরিচ 4টি","লেবু 3টি (সাজানোর জন্য)","চাট মশলা (ছিটানোর জন্য)"],"steps":["গম, বার্লি ও সব ডাল পরিষ্কার পানিতে ধুয়ে নিন যতক্ষণ না পানি পরিষ্কার বের হয়, তারপর প্রচুর তাজা পানি দিয়ে ঢেকে সারারাত বা কমপক্ষে 8 ঘণ্টা ভিজিয়ে রাখুন। মসুর, মুগ ও মাশ ডাল কমপক্ষে 2 ঘণ্টা ভিজান।","ভেজানো দানা ও ডাল ছেঁকে একটি বড় ভারী হাঁড়িতে 12 কাপ পানি, 1 চা চামচ হলুদ ও 1 চা চামচ লবণ দিয়ে দিন, আর ঢেকে হালকা আঁচে 2 থেকে 2.5 ঘণ্টা সেদ্ধ করুন, যতক্ষণ না সবকিছু পুরোপুরি নরম ও হালুয়ার মতো হয়ে যায়।","জিরা, গোলমরিচ, লবঙ্গ, সবুজ ও কালো এলাচ, দারুচিনি, জায়ফল ফুল, জায়ফল ও তারকা মৌরি শুকনো কড়াইয়ে 1 মিনিট ভেজে নিন, ঠান্ডা করে মিহি গুঁড়া করে নিন।","একটি বড় ভারী হাঁড়িতে 1 কাপ ঘি বা তেল গরম করুন, কাটা পেঁয়াজ গভীর সোনালি বাদামি হওয়া পর্যন্ত ভাজুন, আর অর্ধেকটা সাজানোর জন্য তুলে রাখুন। আদা ও রসুন বাটা দিয়ে 1 মিনিট ভাজুন।","গরুর মাংস ও হাড় দিয়ে তীব্র আঁচে 5 থেকে 7 মিনিট সেঁকে নিন, তারপর লাল মরিচ গুঁড়া, কাশ্মীরি মরিচ গুঁড়া, ধনে গুঁড়া, হলুদ, হালিম মশলা, লবণ ও অর্ধেক গুঁড়া মশলা দিয়ে 2 মিনিট নাড়ুন। ফেটানো দই ঢেলে তেল আলাদা না হওয়া পর্যন্ত রান্না করুন, তারপর 6 কাপ পানি দিন।","ঢেকে রান্না করুন যতক্ষণ না মাংস পুরোপুরি নরম হয়ে ছিঁড়ে যায়, প্রেশার কুকারে 45 মিনিট বা সাধারণ হাঁড়িতে 2.5 ঘণ্টা। মাংস তুলে নিন, খালি হাড় ফেলে দিন, আর মুষল বা দুটি কাঁটাচামচ দিয়ে হাতে গরুর মাংস সূক্ষ্ম আঁশ করে ছিঁড়ে নিন। কোরমার ঝোল বাঁচিয়ে রাখুন।","রান্না করা দানা ও ডাল হ্যান্ড ব্লেন্ডার দিয়ে হালকা করে বেটে নিন, কিছুটা গঠন রেখে, আর ছেঁড়া মাংস বাঁচিয়ে রাখা ঝোলসহ দিন। বাকি মশলা গুঁড়া দিতে দিতে হালকা আঁচে 30 থেকে 45 মিনিট জোরে মথে ও নেড়ে রান্না করুন, যতক্ষণ না মিশ্রণ ঘন, আঠালো ও আঁশযুক্ত হয়ে যায়।","একটি ছোট কড়াইয়ে ½ কাপ ঘি গরম করুন, কাটা পেঁয়াজ মুচমুচে ও সোনালি করে ভাজুন, আর গরম ঘি ও পেঁয়াজ হালিমের ওপর ঢেলে দিন। 5 মিনিট ঢেকে রাখুন, তারপর গরম বাটিতে ভাজা পেঁয়াজ, আদা, ধনেপাতা, পুদিনা, কাঁচা মরিচ, লেবুর টুকরা ও চাট মশলা দিয়ে পরিবেশন করুন, পাশে গরম নান দিয়ে।"],"tip":"গম ও বার্লি কমপক্ষে 12 ঘণ্টা ভিজিয়ে রাখুন, আর মাংস হাতে মথুন। ফুড প্রসেসর মাংসের আঁশ খুব ছোট করে কেটে ফেলে আর রেস্তার আঁশযুক্ত গঠন নষ্ট করে দেয়। ভারী তলার হাঁড়ি ব্যবহার করুন আর বারবার নাড়ুন, কারণ ঘন হালিম সহজে তলায় লেগে পুড়ে যায়।","notes":["গোটা গম ও বার্লি দীর্ঘক্ষণ ভেজানো দরকার, কমপক্ষে 8 ঘণ্টা আর ভালো হয় সারারাত, নইলে সেগুলো দানাদার থেকে যায় আর ভাঙতে অনেক বেশি সময় লাগে।","পা বা কাঁধের গরুর মাংস, বড় টুকরো করে, লম্বা আঁশ দেয় যা রেস্তার আঁশযুক্ত গঠন তৈরি করে। হাড় হাঁড়িতে ভার ও সমৃদ্ধি যোগ করে।","হালিম মশলা ব্র্যান্ড অনুযায়ী শক্তিতে ভিন্ন হয়। প্রথমবার দেওয়া পরিমাণ ব্যবহার করুন, আর পরেরবার ঠিক করে নিন।","ঘি ঐতিহ্যবাহী স্বাদ দেয়। তেলও চলে, আর অর্ধেক ঘি অর্ধেক তেল ভালো মাঝামাঝি উপায়।"],"variations":["মুরগির হালিম: গরুর মাংসের বদলে একই ওজনের হাড়সহ মুরগি নিন, যা অনেক তাড়াতাড়ি রান্না হয় আর হালকা স্বাদ দেয়।","খাসির হালিম: সমৃদ্ধ স্বাদের জন্য ছাগলের মাংস বা ভেড়ার কাঁধ ব্যবহার করুন, যা রাজকীয় মুঘল রান্নায় ঐতিহ্যবাহী।","নিরামিষ ওটস হালিম: মাংস বাদ দিন, ডাল দ্বিগুণ করুন, রোল্ড ওটস দিন, আর সুস্বাদু গভীরতার জন্য সবজির ঝোল ও অতিরিক্ত ভাজা পেঁয়াজ ব্যবহার করুন।"],"serving":"চওড়া, অগভীর বাটিতে গরম পরিবেশন করুন, আর সাজানোর উপকরণ টেবিলে একটি থালায় রাখুন যাতে প্রত্যেকে নিজের পছন্দমতো ভাজা পেঁয়াজ, আদা, ধনেপাতা, পুদিনা, কাঁচা মরিচ, লেবু ও চাট মশলা দিতে পারে। হালিম ঐতিহ্যগতভাবে গরম তন্দুরি নানের সঙ্গে পরিবেশন করা হয়, বা চামচ দিয়ে একাই খাওয়া হয়। হাঁড়ি টেবিলে আনুন যখন সেটি এখনও ফুটছে।","storage":"ঠান্ডা করে বায়ুরোধী পাত্রে ফ্রিজে 3 দিন পর্যন্ত রাখুন। ঠান্ডা হলে হালিম ঘন হয়ে যায়। সামান্য পানি বা মাংসের ঝোল দিয়ে হালকা থেকে মাঝারি আঁচে ধীরে গরম করুন, ক্রমাগত নাড়তে থাকুন যাতে তলায় না লাগে। 3 মাস পর্যন্ত ফ্রিজে রাখুন, ফ্রিজে সারারাত গলিয়ে নিন, আর সাজানোর উপকরণ শুধু পরিবেশনের সময় তাজা দিন।","mistakes":["মাংসে ফুড প্রসেসর ব্যবহার করা। এতে আঁশ খুব ছোট কাটা পড়ে আর আঁশযুক্ত হালিমের বদলে দানাদার স্যুপ হয়।","সারারাত ভেজানো বাদ দেওয়া। দানা দানাদার থেকে যায় আর ভাঙতে অনেক বেশি সময় লাগে।","তীব্র আঁচে রান্না করা আর না নাড়া। ঘন হালিম তলায় লেগে পুড়ে যায়।","খুব পাতলা করে পরিবেশন করা। স্টার্চ এটিকে চামচে ঢিবি বাঁধার মতো ঘন হালুয়া না করা পর্যন্ত হালকা আঁচে সেদ্ধ ও মথতে থাকুন।"],"faq":[["আমি কি হালিম ফ্রিজে রাখতে পারি?","হ্যাঁ। হালিম খুব ভালোভাবে জমে যায়। এটি পুরোপুরি ঠান্ডা হতে দিন, বায়ুরোধী পাত্রে ভাগ করে 3 মাস পর্যন্ত জমিয়ে রাখুন। গরম করার আগে ফ্রিজে সারারাত গলিয়ে নিন।"],["হালিম কীভাবে আবার গরম করব?","ঠান্ডা হলে হালিম অনেক ঘন হয়ে যায়। এটি একটি হাঁড়িতে সামান্য পানি বা মাংসের ঝোল দিয়ে হালকা থেকে মাঝারি আঁচে গরম করুন, ক্রমাগত নাড়তে থাকুন যাতে তলায় না লাগে।"],["আমি কি হালিম গ্লুটেনমুক্ত বানাতে পারি?","ঐতিহ্যবাহী হালিম গম ও বার্লির ওপর নির্ভর করে, যাতে গ্লুটেন থাকে। গ্লুটেনমুক্ত বানাতে গম ও বার্লির বদলে রোল্ড ওটস ও বাদামি চাল ব্যবহার করুন।"],["আমার হালিম খুব পাতলা হলে কী করব?","ঢাকনা না দিয়ে হালকা আঁচে সেদ্ধ করতে থাকুন আর কাঠের চামচ দিয়ে মথতে থাকুন। ডাল ও গমের স্টার্চ অতিরিক্ত আর্দ্রতা বাষ্প হয়ে যাওয়ার সঙ্গে সঙ্গে মিশ্রণ ঘন করে দেয়।"]]}};
